var init_geography = __esm({
  "src/data/questions/geography.ts"() {
    GEOGRAPHY_QUESTIONS = {
      "\u062F\u0648\u0644 \u0648\u0639\u0648\u0627\u0635\u0645": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0631\u064A\u0627\u0636", explanation: "\u0627\u0644\u0631\u064A\u0627\u0636 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0648\u0623\u0643\u0628\u0631 \u0645\u062F\u0646\u0647\u0627.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0645\u0635\u0631 \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0642\u0627\u0647\u0631\u0629", explanation: "\u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0645\u0635\u0631 \u0648\u062A\u0644\u0642\u0628 \u0628\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0623\u0644\u0641 \u0645\u0626\u0630\u0646\u0629.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0639\u0631\u0628\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0641\u0631\u0646\u0633\u0627 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0628\u0631\u062C \u0625\u064A\u0641\u0644\u061F", correctAnswer: "\u0628\u0627\u0631\u064A\u0633", explanation: "\u0628\u0627\u0631\u064A\u0633 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0641\u0631\u0646\u0633\u0627 \u0648\u062A\u0644\u0642\u0628 \u0628\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0646\u0648\u0631.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 (\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627)\u061F", correctAnswer: "\u0644\u0646\u062F\u0646", explanation: "\u0644\u0646\u062F\u0646 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0639\u0644\u0649 \u0646\u0647\u0631 \u0627\u0644\u062A\u0627\u064A\u0645\u0632 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u061F", correctAnswer: "\u0637\u0648\u0643\u064A\u0648", explanation: "\u0637\u0648\u0643\u064A\u0648 \u0647\u064A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0644\u0644\u064A\u0627\u0628\u0627\u0646 \u0648\u0623\u0643\u062B\u0631 \u0627\u0644\u0645\u062F\u0646 \u0627\u0643\u062A\u0638\u0627\u0638\u0627\u064B \u0628\u0627\u0644\u0633\u0643\u0627\u0646 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0645\u062F\u0646" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A\u0629\u061F", correctAnswer: "\u0648\u0627\u0634\u0646\u0637\u0646 \u0627\u0644\u0639\u0627\u0635\u0645\u0629 (Washington, D.C.)", explanation: "\u0648\u0627\u0634\u0646\u0637\u0646 \u062F\u064A \u0633\u064A \u0647\u064A \u0627\u0644\u0645\u0642\u0631 \u0627\u0644\u0631\u0626\u0627\u0633\u064A \u0648\u0627\u0644\u062D\u0643\u0648\u0645\u064A \u0648\u0644\u064A\u0633\u062A \u0646\u064A\u0648\u064A\u0648\u0631\u0643 \u0643\u0645\u0627 \u064A\u0638\u0646 \u0627\u0644\u0628\u0639\u0636.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0627\u0644\u062A\u064A \u0643\u0627\u0646\u062A \u0645\u0641\u0635\u0648\u0644\u0629 \u0628\u062C\u062F\u0627\u0631 \u0634\u0647\u064A\u0631 \u062D\u062A\u0649 \u0639\u0627\u0645 1989\u061F", correctAnswer: "\u0628\u0631\u0644\u064A\u0646", explanation: "\u0628\u0631\u0644\u064A\u0646 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0627\u0644\u0627\u062A\u062D\u0627\u062F\u064A\u0629.", source: "\u0623\u0637\u0644\u0633 \u0623\u0648\u0631\u0648\u0628\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0625\u0633\u0628\u0627\u0646\u064A\u0627 \u0627\u0644\u062A\u064A \u062A\u0636\u0645 \u0645\u0642\u0631 \u0627\u0644\u0642\u0635\u0631 \u0627\u0644\u0645\u0644\u0643\u064A\u061F", correctAnswer: "\u0645\u062F\u0631\u064A\u062F", explanation: "\u0645\u062F\u0631\u064A\u062F \u0647\u064A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0648\u0627\u0644\u0642\u0644\u0628 \u0627\u0644\u0625\u062F\u0627\u0631\u064A \u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0627.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0643\u0646\u062F\u0627 \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A\u0629\u061F", correctAnswer: "\u0623\u0648\u062A\u0627\u0648\u0627", explanation: "\u0623\u0648\u062A\u0627\u0648\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0643\u0646\u062F\u0627 \u0648\u0644\u064A\u0633\u062A \u062A\u0648\u0631\u0648\u0646\u062A\u0648 \u0623\u0648 \u0645\u0648\u0646\u062A\u0631\u064A\u0627\u0644.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627 \u0627\u0644\u0631\u0633\u0645\u064A\u0629\u061F", correctAnswer: "\u0643\u0627\u0646\u0628\u0631\u0627", explanation: "\u0643\u0627\u0646\u0628\u0631\u0627 \u0647\u064A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A\u0629 \u0644\u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627 \u0648\u0627\u062E\u062A\u064A\u0631\u062A \u0643\u062D\u0644 \u0648\u0633\u0637 \u0628\u064A\u0646 \u0633\u064A\u062F\u0646\u064A \u0648\u0645\u0644\u0628\u0648\u0631\u0646.", source: "\u0623\u0637\u0644\u0633 \u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0627\u0644\u062A\u064A \u062A\u0645 \u062A\u062E\u0637\u064A\u0637\u0647\u0627 \u0647\u0646\u062F\u0633\u064A\u0627\u064B \u0639\u0644\u0649 \u0634\u0643\u0644 \u0637\u0627\u0626\u0631\u0629 \u0641\u064A \u0627\u0644\u0633\u062A\u064A\u0646\u064A\u0627\u062A\u061F", correctAnswer: "\u0628\u0631\u0627\u0632\u064A\u0644\u064A\u0627 (Bras\xEDlia)", explanation: "\u062A\u0645 \u0628\u0646\u0627\u0621 \u0628\u0631\u0627\u0632\u064A\u0644\u064A\u0627 \u0644\u062A\u0635\u0628\u062D \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0631\u064A\u0648 \u062F\u064A \u062C\u0627\u0646\u064A\u0631\u0648 \u0641\u064A \u0639\u0647\u062F \u0627\u0644\u0631\u0626\u064A\u0633 \u062C\u0648\u0633\u064A\u0644\u064A\u0646\u0648 \u0643\u0648\u0628\u064A\u062A\u0634\u064A\u0643.", source: "\u062A\u0627\u0631\u064A\u062E \u0639\u0648\u0627\u0635\u0645 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u062A\u0631\u0643\u064A\u0627 \u0627\u0644\u0631\u0633\u0645\u064A\u0629\u061F", correctAnswer: "\u0623\u0646\u0642\u0631\u0629", explanation: "\u0623\u0646\u0642\u0631\u0629 \u0623\u0635\u0628\u062D\u062A \u0639\u0627\u0635\u0645\u0629 \u062A\u0631\u0643\u064A\u0627 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0639\u0627\u0645 1923 \u0628\u0642\u0631\u0627\u0631 \u0645\u0646 \u0643\u0645\u0627\u0644 \u0623\u062A\u0627\u062A\u0648\u0631\u0643 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0625\u0633\u0637\u0646\u0628\u0648\u0644.", source: "\u062A\u0627\u0631\u064A\u062E \u062A\u0631\u0643\u064A\u0627 \u0627\u0644\u062D\u062F\u064A\u062B" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0633\u0648\u064A\u0633\u0631\u0627 \u0627\u0644\u0641\u0639\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0636\u0645 \u0645\u0642\u0631 \u0627\u0644\u062D\u0643\u0648\u0645\u0629 \u0627\u0644\u0627\u062A\u062D\u0627\u062F\u064A\u0629\u061F", correctAnswer: "\u0628\u0631\u0646 (Bern)", explanation: "\u062A\u0639\u062A\u0628\u0631 \u0628\u0631\u0646 \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0627\u062A\u062D\u0627\u062F\u064A\u0629 \u0648\u0639\u0627\u0635\u0645\u0629 \u0633\u0648\u064A\u0633\u0631\u0627 \u0627\u0644\u0641\u0639\u0644\u064A\u0629 \u0628\u062D\u0643\u0645 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0648\u0627\u0642\u0639.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u063A\u0631\u0628\u064A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0631\u0628\u0627\u0637", explanation: "\u0627\u0644\u0631\u0628\u0627\u0637 \u0647\u064A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0625\u062F\u0627\u0631\u064A\u0629 \u0644\u0644\u0645\u063A\u0631\u0628 \u0648\u062A\u0636\u0645 \u0627\u0644\u0642\u0635\u0631 \u0627\u0644\u0645\u0644\u0643\u064A.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0645\u063A\u0631\u0628 \u0627\u0644\u0639\u0631\u0628\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0646\u064A\u0648\u0632\u064A\u0644\u0646\u062F\u0627 \u0627\u0644\u0631\u0633\u0645\u064A\u0629\u061F", correctAnswer: "\u0648\u064A\u0644\u064A\u0646\u063A\u062A\u0648\u0646 (Wellington)", explanation: "\u0648\u064A\u0644\u064A\u0646\u063A\u062A\u0648\u0646 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u062C\u0646\u0648\u0628 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0646\u064A\u0648\u0632\u064A\u0644\u0646\u062F\u0627 \u0648\u0644\u064A\u0633\u062A \u0623\u0648\u0643\u0644\u0627\u0646\u062F.", source: "\u0623\u0637\u0644\u0633 \u0623\u0648\u0642\u064A\u0627\u0646\u0648\u0633\u064A\u0627" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0644\u0645\u064A\u0627\u0646\u0645\u0627\u0631 (\u0628\u0648\u0631\u0645\u0627) \u0627\u0644\u062A\u064A \u062A\u0645 \u0625\u0646\u0634\u0627\u0624\u0647\u0627 \u0648\u0646\u0642\u0644 \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0625\u0644\u064A\u0647\u0627 \u0639\u0627\u0645 2005 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u064A\u0627\u0646\u063A\u0648\u0646\u061F", correctAnswer: "\u0646\u0627\u064A\u0628\u064A\u062F\u0627\u0648 (Naypyidaw)", explanation: "\u0646\u0627\u064A\u0628\u064A\u062F\u0627\u0648 \u0634\u064F\u064A\u062F\u062A \u0643\u0639\u0627\u0635\u0645\u0629 \u062C\u062F\u064A\u062F\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0646\u064F\u0642\u0644\u062A \u0627\u0644\u0648\u0632\u0627\u0631\u0627\u062A \u0625\u0644\u064A\u0647\u0627 \u0641\u064A \u0646\u0648\u0641\u0645\u0628\u0631 2005.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 \u0644\u0622\u0633\u064A\u0627" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0643\u0627\u0632\u0627\u062E\u0633\u062A\u0627\u0646 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u0643\u0627\u0646 \u0627\u0633\u0645\u0647\u0627 \u0623\u0633\u062A\u0627\u0646\u0627 \u062B\u0645 \u0646\u0648\u0631 \u0633\u0644\u0637\u0627\u0646 \u062B\u0645 \u0639\u0627\u062F\u062A \u0623\u0633\u062A\u0627\u0646\u0627\u061F", correctAnswer: "\u0623\u0633\u062A\u0627\u0646\u0627 (Astana)", explanation: "\u0646\u0642\u0644\u062A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0645\u0646 \u0623\u0644\u0645\u0627\u062A\u064A \u0625\u0644\u0649 \u0623\u0633\u062A\u0627\u0646\u0627 \u0639\u0627\u0645 1997 \u0648\u0623\u0639\u064A\u062F\u062A \u062A\u0633\u0645\u064A\u062A\u0647\u0627 \u0623\u0633\u062A\u0627\u0646\u0627 \u0639\u0627\u0645 2022.", source: "\u0623\u0637\u0644\u0633 \u0622\u0633\u064A\u0627 \u0627\u0644\u0648\u0633\u0637\u0649" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0646\u064A\u062C\u064A\u0631\u064A\u0627 \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u062D\u0644\u062A \u0645\u062D\u0644 \u0644\u0627\u063A\u0648\u0633 \u0639\u0627\u0645 1991\u061F", correctAnswer: "\u0623\u0628\u0648\u062C\u0627 (Abuja)", explanation: "\u0623\u0628\u0648\u062C\u0627 \u062A\u0642\u0639 \u0641\u064A \u0648\u0633\u0637 \u0646\u064A\u062C\u064A\u0631\u064A\u0627 \u0644\u062A\u0648\u0641\u064A\u0631 \u0645\u0648\u0642\u0639 \u0645\u062D\u0627\u064A\u062F \u0628\u064A\u0646 \u0645\u062E\u062A\u0644\u0641 \u0627\u0644\u0642\u0648\u0645\u064A\u0627\u062A \u0648\u0627\u0644\u0623\u062F\u064A\u0627\u0646.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0627\u0644\u062D\u062F\u064A\u062B\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0628\u0648\u062A\u0627\u0646 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0641\u064A \u062C\u0628\u0627\u0644 \u0627\u0644\u0647\u064A\u0645\u0627\u0644\u0627\u064A\u0627 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0639\u062F\u0645 \u0648\u062C\u0648\u062F \u0623\u064A \u0625\u0634\u0627\u0631\u0627\u062A \u0645\u0631\u0648\u0631 \u0636\u0648\u0626\u064A\u0629 \u0641\u064A\u0647\u0627\u061F", correctAnswer: "\u062A\u064A\u0645\u0641\u0648 (Thimphu)", explanation: "\u062A\u064A\u0645\u0641\u0648 \u0639\u0627\u0635\u0645\u0629 \u0628\u0648\u062A\u0627\u0646 \u0648\u062A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u0631\u062C\u0627\u0644 \u0627\u0644\u0634\u0631\u0637\u0629 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0625\u0634\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0622\u0644\u064A\u0629.", source: "\u063A\u0631\u0627\u0626\u0628 \u0645\u062F\u0646 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u062F\u0648\u0644\u0629 \u0644\u064A\u062E\u062A\u0646\u0634\u062A\u0627\u064A\u0646 \u0627\u0644\u0635\u063A\u064A\u0631\u0629 \u0641\u064A \u0648\u0633\u0637 \u0623\u0648\u0631\u0648\u0628\u0627\u061F", correctAnswer: "\u0641\u0627\u062F\u0648\u0632 (Vaduz)", explanation: "\u0641\u0627\u062F\u0648\u0632 \u0647\u064A \u0645\u0642\u0631 \u0623\u0645\u064A\u0631 \u0644\u064A\u062E\u062A\u0646\u0634\u062A\u0627\u064A\u0646 \u0648\u0645\u0642\u0631 \u0627\u0644\u0628\u0631\u0644\u0645\u0627\u0646 \u0627\u0644\u0648\u0637\u0646\u064A.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0635\u063A\u064A\u0631\u0629" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0643\u0648\u062A \u062F\u064A\u0641\u0648\u0627\u0631 (\u0633\u0627\u062D\u0644 \u0627\u0644\u0639\u0627\u062C) \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 \u0648\u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0648\u0644\u064A\u0633\u062A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A\u0629 \u0623\u0628\u064A\u062F\u062C\u0627\u0646\u061F", correctAnswer: "\u064A\u0627\u0645\u0648\u0633\u0648\u0643\u0631\u0648 (Yamoussoukro)", explanation: "\u064A\u0627\u0645\u0648\u0633\u0648\u0643\u0631\u0648 \u0647\u064A \u0645\u0633\u0642\u0637 \u0631\u0623\u0633 \u0627\u0644\u0631\u0626\u064A\u0633 \u0627\u0644\u0623\u0633\u0628\u0642 \u0628\u0648\u0627\u0646\u064A\u064A \u0648\u062A\u0636\u0645 \u0643\u0646\u064A\u0633\u0629 \u0628\u0627\u0632\u064A\u0644\u064A\u0643 \u0633\u064A\u062F\u0629 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0634\u0647\u064A\u0631\u0629.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0648\u0644\u0627\u064A\u0629 \u0623\u0644\u0627\u0633\u0643\u0627 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0627\u0644\u062A\u064A \u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627 \u0628\u0627\u0644\u0633\u064A\u0627\u0631\u0629 \u0645\u0646 \u0633\u0627\u0626\u0631 \u0627\u0644\u0648\u0644\u0627\u064A\u0629\u061F", correctAnswer: "\u062C\u0648\u0646\u0648 (Juneau)", explanation: "\u062C\u0648\u0646\u0648 \u0639\u0627\u0635\u0645\u0629 \u0623\u0644\u0627\u0633\u0643\u0627 \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627 \u0625\u0644\u0627 \u0628\u0627\u0644\u0637\u0627\u0626\u0631\u0629 \u0623\u0648 \u0627\u0644\u0633\u0641\u064A\u0646\u0629 \u0646\u0638\u0631\u0627\u064B \u0644\u0644\u062A\u0636\u0627\u0631\u064A\u0633 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0627\u0644\u0648\u0639\u0631\u0629.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u062A\u064A \u062A\u0645\u062A\u0644\u0643 3 \u0639\u0648\u0627\u0635\u0645 \u0631\u0633\u0645\u064A\u0629 \u0645\u0642\u0633\u0645\u0629 \u0628\u064A\u0646 \u0627\u0644\u0633\u0644\u0637\u0627\u062A \u0627\u0644\u062A\u0646\u0641\u064A\u0630\u064A\u0629 \u0648\u0627\u0644\u062A\u0634\u0631\u064A\u0639\u064A\u0629 \u0648\u0627\u0644\u0642\u0636\u0627\u0626\u064A\u0629\u061F", correctAnswer: "\u062C\u0646\u0648\u0628 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 (\u0628\u0631\u064A\u062A\u0648\u0631\u064A\u0627\u060C \u0643\u064A\u0628 \u062A\u0627\u0648\u0646\u060C \u0628\u0644\u0648\u0645\u0641\u0648\u0646\u062A\u064A\u0646)", explanation: "\u0628\u0631\u064A\u062A\u0648\u0631\u064A\u0627 \u0644\u0644\u0633\u0644\u0637\u0629 \u0627\u0644\u062A\u0646\u0641\u064A\u0630\u064A\u0629\u060C \u0643\u064A\u0628 \u062A\u0627\u0648\u0646 \u0644\u0644\u062A\u0634\u0631\u064A\u0639\u064A\u0629\u060C \u0648\u0628\u0644\u0648\u0645\u0641\u0648\u0646\u062A\u064A\u0646 \u0644\u0644\u0642\u0636\u0627\u0626\u064A\u0629.", source: "\u0627\u0644\u062F\u0633\u0627\u062A\u064A\u0631 \u0648\u0627\u0644\u0646\u0638\u0645 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0628\u0627\u0644\u0627\u0648 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0627\u0644\u062A\u064A \u062A\u0639\u062A\u0628\u0631 \u0648\u0627\u062D\u062F\u0629 \u0645\u0646 \u0623\u0635\u063A\u0631 \u0627\u0644\u0639\u0648\u0627\u0635\u0645 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0633\u0643\u0627\u0646\u0627\u064B\u061F", correctAnswer: "\u0646\u063A\u064A\u0631\u0648\u0644\u0645\u0648\u062F (Ngerulmud)", explanation: "\u0646\u063A\u064A\u0631\u0648\u0644\u0645\u0648\u062F \u0641\u064A \u0648\u0644\u0627\u064A\u0629 \u0645\u064A\u0644\u0643\u064A\u0648\u0643 \u062A\u0645 \u0627\u0641\u062A\u062A\u0627\u062D \u0645\u062C\u0645\u0639\u0647\u0627 \u0627\u0644\u062D\u0643\u0648\u0645\u064A \u0639\u0627\u0645 2006 \u0644\u064A\u0635\u0628\u062D \u0639\u0627\u0635\u0645\u0629 \u0628\u0627\u0644\u0627\u0648.", source: "\u0623\u0637\u0644\u0633 \u062C\u0632\u0631 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0633\u0627\u0646 \u0645\u0627\u0631\u064A\u0646\u0648 \u0627\u0644\u0645\u062D\u0627\u0637\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0628\u0627\u0644\u0623\u0631\u0627\u0636\u064A \u0627\u0644\u0625\u064A\u0637\u0627\u0644\u064A\u0629\u061F", correctAnswer: "\u0645\u062F\u064A\u0646\u0629 \u0633\u0627\u0646 \u0645\u0627\u0631\u064A\u0646\u0648 (Citt\xE0 di San Marino)", explanation: "\u062A\u0642\u0639 \u0645\u062F\u064A\u0646\u0629 \u0633\u0627\u0646 \u0645\u0627\u0631\u064A\u0646\u0648 \u0641\u0648\u0642 \u0642\u0645\u0629 \u062C\u0628\u0644 \u062A\u064A\u062A\u0627\u0646\u0648 \u0648\u0647\u064A \u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0644\u0623\u0642\u062F\u0645 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0628\u0627\u0642\u064A\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" }
      ],
      "\u062E\u0645\u0646 \u0627\u0644\u062F\u0648\u0644\u0629": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u062F\u0648\u0644\u0629 \u0622\u0633\u064A\u0648\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0623\u0634\u062C\u0627\u0631 \u0627\u0644\u0633\u0627\u0643\u0648\u0631\u0627 \u0648\u0642\u0637\u0627\u0631\u0627\u062A \u0627\u0644\u0634\u064A\u0646\u0643\u0627\u0646\u0633\u0646 \u0648\u062C\u0628\u0644 \u0641\u0648\u062C\u064A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0627\u0644\u064A\u0627\u0628\u0627\u0646", explanation: "\u062A\u0634\u062A\u0647\u0631 \u0627\u0644\u064A\u0627\u0628\u0627\u0646 \u0628\u062C\u0628\u0644 \u0641\u0648\u062C\u064A \u0627\u0644\u0628\u0631\u0643\u0627\u0646\u064A \u0648\u0632\u0647\u0648\u0631 \u0627\u0644\u0643\u0631\u0632 \u0648\u0642\u0637\u0627\u0631 \u0627\u0644\u0631\u0635\u0627\u0635\u0629.", source: "\u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u062F\u0648\u0644" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u062F\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u062A\u0623\u062E\u0630 \u062E\u0631\u064A\u0637\u062A\u0647\u0627 \u0634\u0643\u0644 \u062D\u0630\u0627\u0621 \u0630\u064A \u0643\u0639\u0628 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0627\u0644\u0628\u064A\u062A\u0632\u0627 \u0648\u0627\u0644\u0628\u0627\u0633\u062A\u0627 \u0648\u0628\u0631\u062C \u0628\u064A\u0632\u0627 \u0627\u0644\u0645\u0627\u0626\u0644\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0625\u064A\u0637\u0627\u0644\u064A\u0627", explanation: "\u0634\u0628\u0647 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0625\u064A\u0637\u0627\u0644\u064A\u0629 \u062A\u062A\u062E\u0630 \u0634\u0643\u0644\u0627\u064B \u0645\u0634\u0627\u0628\u0647\u0627\u064B \u0644\u0644\u062D\u0630\u0627\u0621 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0627\u0644\u0645\u0623\u0643\u0648\u0644\u0627\u062A \u0627\u0644\u0625\u064A\u0637\u0627\u0644\u064A\u0629 \u0648\u0628\u0631\u062C \u0628\u064A\u0632\u0627.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0623\u0648\u0631\u0648\u0628\u0627" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u062F\u0648\u0644\u0629 \u062A\u0642\u0639 \u0641\u064A \u0634\u0645\u0627\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u064A\u0645\u0631 \u0628\u0647\u0627 \u0623\u0637\u0648\u0644 \u0646\u0647\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0623\u0647\u0631\u0627\u0645\u0627\u062A \u0627\u0644\u062C\u064A\u0632\u0629 \u0627\u0644\u062B\u0644\u0627\u062B\u0629\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0645\u0635\u0631", explanation: "\u0645\u0635\u0631 \u0647\u0628\u0629 \u0627\u0644\u0646\u064A\u0644 \u0648\u0645\u0648\u0637\u0646 \u0639\u062C\u0627\u0626\u0628 \u0627\u0644\u0623\u0647\u0631\u0627\u0645\u0627\u062A \u0648\u0623\u0628\u0648 \u0627\u0644\u0647\u0648\u0644.", source: "\u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0642\u062F\u064A\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u062A\u0639\u062F \u0623\u0643\u0628\u0631 \u0645\u0646\u062A\u062C \u0644\u0644\u0628\u0646 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u0641\u0627\u0632\u062A \u0628\u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u0644\u0643\u0631\u0629 \u0627\u0644\u0642\u062F\u0645 5 \u0645\u0631\u0627\u062A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644", explanation: "\u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644 \u0645\u0648\u0637\u0646 \u063A\u0627\u0628\u0627\u062A \u0627\u0644\u0623\u0645\u0627\u0632\u0648\u0646 \u0648\u0627\u0644\u0633\u0627\u0645\u0628\u0627 \u0648\u0635\u0627\u062D\u0628\u0629 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0642\u064A\u0627\u0633\u064A \u0641\u064A \u0627\u0644\u0645\u0648\u0646\u062F\u064A\u0627\u0644.", source: "\u0623\u0637\u0644\u0633 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u062F\u0648\u0644\u0629 \u0648\u0642\u0627\u0631\u0629 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0646\u0641\u0633\u0647 \u062A\u0634\u062A\u0647\u0631 \u0628\u062D\u064A\u0648\u0627\u0646 \u0627\u0644\u0643\u0646\u063A\u0631 \u0648\u0627\u0644\u0643\u0648\u0627\u0644\u0627 \u0648\u062F\u0627\u0631 \u0623\u0648\u0628\u0631\u0627 \u0633\u064A\u062F\u0646\u064A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627", explanation: "\u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627 \u062A\u0634\u063A\u0644 \u0642\u0627\u0631\u0629 \u0643\u0627\u0645\u0644\u0629 \u0648\u0647\u064A \u0627\u0644\u0645\u0648\u0637\u0646 \u0627\u0644\u0637\u0628\u064A\u0639\u064A \u0644\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0627\u0644\u062C\u0631\u0627\u0628\u064A\u0629 \u0643\u0627\u0644\u0643\u0646\u063A\u0631.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u062D\u064A\u0627\u0629 \u0627\u0644\u0641\u0637\u0631\u064A\u0629" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u062F\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0637\u0648\u0627\u062D\u064A\u0646 \u0627\u0644\u0647\u0648\u0627\u0621 \u0648\u0632\u0647\u0648\u0631 \u0627\u0644\u062A\u0648\u0644\u064A\u0628 \u0648\u0627\u0644\u0633\u062F\u0648\u062F \u0627\u0644\u0645\u0627\u0626\u064A\u0629 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0623\u0645\u0633\u062A\u0631\u062F\u0627\u0645\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0647\u0648\u0644\u0646\u062F\u0627 (\u0627\u0644\u0623\u0631\u0627\u0636\u064A \u0627\u0644\u0645\u0646\u062E\u0641\u0636\u0629)", explanation: "\u0647\u0648\u0644\u0646\u062F\u0627 \u062A\u0642\u0639 \u0623\u062C\u0632\u0627\u0621 \u0648\u0627\u0633\u0639\u0629 \u0645\u0646 \u0623\u0631\u0627\u0636\u064A\u0647\u0627 \u062A\u062D\u062A \u0645\u0633\u062A\u0648\u0649 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0632\u0631\u0627\u0639\u0629 \u0627\u0644\u062A\u0648\u0644\u064A\u0628.", source: "\u0645\u0639\u0627\u0644\u0645 \u0623\u0648\u0631\u0648\u0628\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u062F\u0648\u0644\u0629 \u0625\u0633\u0643\u0646\u062F\u0646\u0627\u0641\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0627\u0644\u062E\u0644\u062C\u0627\u0646 \u0627\u0644\u0645\u0627\u0626\u064A\u0629 \u0627\u0644\u0639\u0645\u064A\u0642\u0629 (\u0627\u0644\u0645\u0636\u0627\u064A\u0642) \u0648\u0638\u0627\u0647\u0631\u0629 \u0634\u0645\u0633 \u0645\u0646\u062A\u0635\u0641 \u0627\u0644\u0644\u064A\u0644 \u0648\u0635\u064A\u062F \u0627\u0644\u0633\u0644\u0645\u0648\u0646\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0627\u0644\u0646\u0631\u0648\u064A\u062C", explanation: "\u062A\u0634\u062A\u0647\u0631 \u0627\u0644\u0646\u0631\u0648\u064A\u062C \u0628\u0645\u0636\u0627\u064A\u0642\u0647\u0627 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0623\u0648\u0633\u0644\u0648.", source: "\u0623\u0637\u0644\u0633 \u0623\u0648\u0631\u0648\u0628\u0627 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0630\u0627\u062A \u0634\u0631\u064A\u0637 \u0633\u0627\u062D\u0644\u064A \u0636\u064A\u0642 \u0648\u0637\u0648\u064A\u0644 \u062C\u062F\u0627\u064B \u064A\u0645\u062A\u062F \u0639\u0644\u0649 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0628\u0645\u062D\u0627\u0630\u0627\u0629 \u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0646\u062F\u064A\u0632\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u062A\u0634\u064A\u0644\u064A", explanation: "\u062A\u0634\u064A\u0644\u064A \u062A\u0645\u062A\u062F \u0644\u0623\u0643\u062B\u0631 \u0645\u0646 4000 \u0643\u064A\u0644\u0648\u0645\u062A\u0631 \u0637\u0648\u0644\u0627\u064B \u0628\u0639\u0631\u0636 \u0645\u062A\u0648\u0633\u0637 \u0644\u0627 \u064A\u062A\u062C\u0627\u0648\u0632 175 \u0643\u064A\u0644\u0648\u0645\u062A\u0631\u0627\u064B.", source: "\u062A\u0636\u0627\u0631\u064A\u0633 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u062F\u0648\u0644\u0629 \u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0634\u0644\u0627\u0644\u0627\u062A \u0641\u064A\u0643\u062A\u0648\u0631\u064A\u0627 \u0648\u0645\u062D\u0645\u064A\u0627\u062A \u0627\u0644\u0633\u0627\u0641\u0627\u0631\u064A \u0648\u0645\u0627\u0631\u0627\u062B\u0648\u0646\u0627\u062A \u0627\u0644\u062C\u0631\u064A \u0644\u0644\u0645\u0633\u0627\u0641\u0627\u062A \u0627\u0644\u0637\u0648\u064A\u0644\u0629 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0646\u064A\u0631\u0648\u0628\u064A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0643\u064A\u0646\u064A\u0627", explanation: "\u0643\u064A\u0646\u064A\u0627 \u0645\u0648\u0637\u0646 \u0623\u0634\u0647\u0631 \u0639\u062F\u0627\u0626\u064A \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062A \u0627\u0644\u0637\u0648\u064A\u0644\u0629 \u0648\u062D\u062F\u064A\u0642\u0629 \u0645\u0627\u0633\u0627\u064A \u0645\u0627\u0631\u0627 \u0627\u0644\u0648\u0637\u0646\u064A\u0629.", source: "\u0623\u0637\u0644\u0633 \u0625\u0641\u0631\u064A\u0642\u064A\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u062F\u0648\u0644\u0629 \u0622\u0633\u064A\u0648\u064A\u0629 \u062D\u0628\u064A\u0633\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0631\u064A\u0627\u0636\u0629 \u0627\u0644\u0631\u0643\u0628\u064A \u0648\u0633\u0647\u0648\u0644 \u0627\u0644\u0625\u0633\u062A\u0628\u0633 \u0627\u0644\u0634\u0627\u0633\u0639\u0629 \u0648\u062E\u064A\u0627\u0645 \u0627\u0644\u064A\u0648\u0631\u062A \u0648\u0645\u0624\u0633\u0633\u0647\u0627 \u062C\u0646\u0643\u064A\u0632 \u062E\u0627\u0646\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0645\u0646\u063A\u0648\u0644\u064A\u0627", explanation: "\u0645\u0646\u063A\u0648\u0644\u064A\u0627 \u0628\u0644\u062F \u0627\u0644\u0633\u0647\u0648\u0644 \u0627\u0644\u0634\u0627\u0633\u0639\u0629 \u0648\u0623\u0642\u0644 \u062F\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645 \u0643\u062B\u0627\u0641\u0629 \u0633\u0643\u0627\u0646\u064A\u0629 \u0646\u0633\u0628\u0629 \u0644\u0645\u0633\u0627\u062D\u062A\u0647\u0627.", source: "\u062A\u0627\u0631\u064A\u062E \u0622\u0633\u064A\u0627" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u062F\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0645\u062D\u0627\u064A\u062F\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0633\u0627\u0639\u0627\u062A \u0627\u0644\u0641\u0627\u062E\u0631\u0629\u060C \u0648\u0627\u0644\u0634\u0648\u0643\u0648\u0644\u0627\u062A\u0629\u060C \u0648\u0627\u0644\u062C\u0628\u0646\u060C \u0648\u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0644\u0628 \u0648\u0645\u0642\u0631 \u0627\u0644\u0635\u0644\u064A\u0628 \u0627\u0644\u0623\u062D\u0645\u0631 \u0627\u0644\u062F\u0648\u0644\u064A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0633\u0648\u064A\u0633\u0631\u0627", explanation: "\u0633\u0648\u064A\u0633\u0631\u0627 \u062F\u0648\u0644\u0629 \u0641\u064A\u062F\u0631\u0627\u0644\u064A\u0629 \u0641\u064A \u0642\u0644\u0628 \u0627\u0644\u0623\u0644\u0628 \u062A\u0634\u062A\u0647\u0631 \u0628\u0627\u0644\u062D\u064A\u0627\u062F \u0627\u0644\u0633\u064A\u0627\u0633\u064A \u0648\u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u0645\u0635\u0631\u0641\u064A \u0648\u0627\u0644\u0633\u0627\u0639\u0627\u062A.", source: "\u062F\u0644\u064A\u0644 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u062F\u0648\u0644\u0629 \u062C\u0632\u064A\u0631\u0629 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0646\u062F\u064A \u0642\u0628\u0627\u0644\u0629 \u0627\u0644\u0633\u0627\u062D\u0644 \u0627\u0644\u062C\u0646\u0648\u0628\u064A \u0627\u0644\u0634\u0631\u0642\u064A \u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u062A\u0634\u062A\u0647\u0631 \u0628\u062D\u064A\u0648\u0627\u0646 \u0627\u0644\u0644\u064A\u0645\u0648\u0631 \u0648\u0623\u0634\u062C\u0627\u0631 \u0627\u0644\u0628\u0627\u0648\u0628\u0627\u0628\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0645\u062F\u063A\u0634\u0642\u0631", explanation: "\u0645\u062F\u063A\u0634\u0642\u0631 \u0631\u0627\u0628\u0639 \u0623\u0643\u0628\u0631 \u062C\u0632\u064A\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u0645\u0648\u0637\u0646 \u0641\u0631\u064A\u062F \u0644\u0643\u0627\u0626\u0646\u0627\u062A \u0644\u0627 \u062A\u0648\u062C\u062F \u0641\u064A \u0623\u064A \u0645\u0643\u0627\u0646 \u0622\u062E\u0631.", source: "\u0627\u0644\u062A\u0646\u0648\u0639 \u0627\u0644\u0628\u064A\u0648\u0644\u0648\u062C\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0645\u0648\u0637\u0646 \u0645\u062F\u064A\u0646\u0629 \u0645\u0627\u062A\u0634\u0648 \u0628\u064A\u062A\u0634\u0648 \u0627\u0644\u0623\u062B\u0631\u064A\u0629 \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u062D\u0636\u0627\u0631\u0629 \u0627\u0644\u0625\u0646\u0643\u0627 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0644\u064A\u0645\u0627\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0628\u064A\u0631\u0648 (Peru)", explanation: "\u0628\u064A\u0631\u0648 \u0645\u0647\u062F \u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u064A\u0629 \u0627\u0644\u0625\u0646\u0643\u0627 \u0648\u062A\u0636\u0645 \u0628\u062D\u064A\u0631\u0629 \u062A\u064A\u062A\u064A\u0643\u0627\u0643\u0627 \u0627\u0644\u0623\u0633\u0637\u0648\u0631\u064A\u0629 \u0648\u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0646\u062F\u064A\u0632.", source: "\u0639\u062C\u0627\u0626\u0628 \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062D\u0636\u0627\u0631\u0627\u062A\u0647" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u062F\u0648\u0644\u0629 \u062A\u0642\u0639 \u0641\u064A \u0627\u0644\u0642\u0648\u0642\u0627\u0632 \u062A\u062F\u0639\u064A \u0623\u0646\u0647\u0627 \u0623\u0642\u062F\u0645 \u062F\u0648\u0644\u0629 \u0627\u062A\u062E\u0630\u062A \u0627\u0644\u0645\u0633\u064A\u062D\u064A\u0629 \u062F\u064A\u0627\u0646\u0629 \u0631\u0633\u0645\u064A\u0629 \u0639\u0627\u0645 301\u0645 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u064A\u0631\u064A\u0641\u0627\u0646\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0623\u0631\u0645\u064A\u0646\u064A\u0627", explanation: "\u0623\u0631\u0645\u064A\u0646\u064A\u0627 \u0623\u0639\u0644\u0646\u062A \u0627\u0644\u0645\u0633\u064A\u062D\u064A\u0629 \u062F\u064A\u0627\u0646\u0629 \u0644\u0644\u062F\u0648\u0644\u0629 \u0639\u0627\u0645 301\u0645 \u0641\u064A \u0639\u0647\u062F \u0627\u0644\u0645\u0644\u0643 \u062A\u064A\u0631\u064A\u062F\u0627\u062A\u0633 \u0627\u0644\u062B\u0627\u0644\u062B.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0642\u0648\u0642\u0627\u0632" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u062F\u0648\u0644\u0629 \u0622\u0633\u064A\u0648\u064A\u0629 \u0623\u0631\u062E\u0628\u064A\u0644\u064A\u0629 \u062A\u062A\u0643\u0648\u0646 \u0645\u0646 \u0623\u0643\u062B\u0631 \u0645\u0646 17,000 \u062C\u0632\u064A\u0631\u0629 \u0648\u0647\u064A \u0623\u0643\u0628\u0631 \u062F\u0648\u0644\u0629 \u0625\u0633\u0644\u0627\u0645\u064A\u0629 \u0645\u0646 \u062D\u064A\u062B \u0639\u062F\u062F \u0627\u0644\u0633\u0643\u0627\u0646\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0625\u0646\u062F\u0648\u0646\u064A\u0633\u064A\u0627", explanation: "\u0625\u0646\u062F\u0648\u0646\u064A\u0633\u064A\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u062F\u0648\u0644\u0629 \u062C\u0632\u0631\u064A\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062A\u0636\u0645 \u062C\u0632\u0631 \u062C\u0627\u0648\u0629 \u0648\u0633\u0648\u0645\u0637\u0631\u0629 \u0648\u0628\u0627\u0644\u064A.", source: "\u0623\u0637\u0644\u0633 \u062C\u0646\u0648\u0628 \u0634\u0631\u0642 \u0622\u0633\u064A\u0627" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u062F\u0648\u0644\u0629 \u062D\u0628\u064A\u0633\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062F\u0627\u062E\u0644 \u0623\u0631\u0627\u0636\u064A \u062F\u0648\u0644\u0629 \u0623\u062E\u0631\u0649 (\u0645\u062D\u0627\u0637\u0629 \u0628\u062C\u0646\u0648\u0628 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0641\u0642\u0637) \u0648\u062A\u0639\u062A\u0628\u0631 \u0643\u0644\u0647\u0627 \u0641\u0648\u0642 \u0627\u0631\u062A\u0641\u0627\u0639 1000 \u0645\u062A\u0631\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0644\u064A\u0633\u0648\u062A\u0648 (Lesotho)", explanation: "\u062A\u0644\u0642\u0628 \u0644\u064A\u0633\u0648\u062A\u0648 \u0628\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0647\u064A \u062F\u0648\u0644\u0629 \u062D\u0628\u064A\u0633\u0629 \u062C\u063A\u0631\u0627\u0641\u064A\u0627\u064B \u062A\u0642\u0639 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062F\u0627\u062E\u0644 \u062C\u0646\u0648\u0628 \u0625\u0641\u0631\u064A\u0642\u064A\u0627.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 \u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0627" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u062F\u0648\u0644\u0629 \u062C\u0632\u064A\u0631\u064A\u0629 \u0641\u064A \u0628\u062D\u0631 \u0627\u0644\u0643\u0627\u0631\u064A\u0628\u064A \u062A\u0634\u062A\u0647\u0631 \u0628\u0639\u062F\u0627\u0626\u064A \u0627\u0644\u0633\u0631\u0639\u0629 \u0645\u062B\u0644 \u064A\u0648\u0633\u064A\u0646 \u0628\u0648\u0644\u062A \u0648\u0645\u0648\u0633\u064A\u0642\u0649 \u0627\u0644\u0631\u064A\u063A\u064A \u0648\u0645\u0633\u0642\u0637 \u0631\u0623\u0633 \u0628\u0648\u0628 \u0645\u0627\u0631\u0644\u064A\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u062C\u0627\u0645\u0627\u064A\u0643\u0627", explanation: "\u062C\u0627\u0645\u0627\u064A\u0643\u0627 \u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0643\u064A\u0646\u063A\u0633\u062A\u0648\u0646 \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u062A\u0641\u0648\u0642\u0647\u0627 \u0627\u0644\u0639\u0627\u0644\u0645\u064A \u0641\u064A \u0633\u0628\u0627\u0642\u0627\u062A \u0627\u0644\u0633\u0631\u0639\u0629 \u0648\u0645\u0648\u0633\u064A\u0642\u0649 \u0627\u0644\u0631\u064A\u063A\u064A.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0643\u0627\u0631\u064A\u0628\u064A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u062D\u0628\u064A\u0633\u0629 \u0644\u0627 \u062A\u0637\u0644 \u0639\u0644\u0649 \u0627\u0644\u0628\u062D\u0631\u060C \u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0623\u0633\u0648\u0646\u0633\u064A\u0648\u0646 \u0648\u062A\u0639\u062A\u0645\u062F \u0627\u0644\u0644\u063A\u062A\u064A\u0646 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0648\u0627\u0644\u063A\u0648\u0627\u0631\u0627\u0646\u064A\u0629 \u0643\u0644\u063A\u062A\u064A\u0646 \u0631\u0633\u0645\u064A\u062A\u064A\u0646\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0628\u0627\u0631\u0627\u063A\u0648\u0627\u064A (Paraguay)", explanation: "\u0628\u0627\u0631\u0627\u063A\u0648\u0627\u064A \u062A\u062A\u0645\u064A\u0632 \u0628\u0623\u0646 \u0627\u0644\u063A\u0627\u0644\u0628\u064A\u0629 \u0627\u0644\u0639\u0638\u0645\u0649 \u0645\u0646 \u0633\u0643\u0627\u0646\u0647\u0627 \u064A\u062A\u062D\u062F\u062B\u0648\u0646 \u0644\u063A\u0629 \u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0623\u0635\u0644\u064A\u064A\u0646 (\u0627\u0644\u063A\u0648\u0627\u0631\u0627\u0646\u064A).", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u062F\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u0623\u0646\u0647\u0627 \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u062E\u0636\u0631\u0627\u0621 \u0648\u0627\u0644\u062C\u0644\u064A\u062F \u0648\u0627\u0644\u0628\u0631\u0627\u0643\u064A\u0646 \u0648\u0627\u0644\u064A\u0646\u0627\u0628\u064A\u0639 \u0627\u0644\u062D\u0627\u0631\u0629 (\u0627\u0644\u063A\u064A\u0648\u0632\u0631) \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0631\u064A\u0643\u064A\u0627\u0641\u064A\u0643\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0622\u064A\u0633\u0644\u0646\u062F\u0627 (Iceland)", explanation: "\u0622\u064A\u0633\u0644\u0646\u062F\u0627 \u062C\u0632\u064A\u0631\u0629 \u0628\u0631\u0643\u0627\u0646\u064A\u0629 \u0641\u064A \u0634\u0645\u0627\u0644 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0623\u0637\u0644\u0633\u064A \u062A\u0639\u062A\u0645\u062F \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u062D\u0631\u0627\u0631\u064A\u0629 \u0627\u0644\u0623\u0631\u0636\u064A\u0629.", source: "\u0623\u0637\u0644\u0633 \u0623\u0648\u0631\u0648\u0628\u0627 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0622\u0633\u064A\u0627 \u0627\u0644\u0648\u0633\u0637\u0649 \u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0639\u0634\u0642 \u0622\u0628\u0627\u062F \u0648\u062A\u0634\u062A\u0647\u0631 \u0628\u0648\u062C\u0648\u062F \xAB\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u062C\u062D\u064A\u0645\xBB (\u062D\u0641\u0631\u0629 \u062F\u0627\u0631\u0641\u0627\u0632\u0627 \u0627\u0644\u063A\u0627\u0632\u064A\u0629 \u0627\u0644\u0645\u0634\u062A\u0639\u0644\u0629)\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u062A\u0631\u0643\u0645\u0627\u0646\u0633\u062A\u0627\u0646", explanation: "\u062D\u0641\u0631\u0629 \u063A\u0627\u0632 \u062F\u0627\u0631\u0641\u0627\u0632\u0627 \u0645\u0634\u062A\u0639\u0644\u0629 \u0645\u0646\u0630 \u0639\u0627\u0645 1971 \u0641\u064A \u0635\u062D\u0631\u0627\u0621 \u0642\u0631\u0647 \u0642\u0648\u0645 \u0641\u064A \u062A\u0631\u0643\u0645\u0627\u0646\u0633\u062A\u0627\u0646.", source: "\u0645\u0639\u0627\u0644\u0645 \u0622\u0633\u064A\u0627 \u0627\u0644\u0648\u0633\u0637\u0649" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u062F\u0648\u0644\u0629 \u062C\u0632\u0631\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u062A\u0639\u062F \u0623\u0648\u0644 \u062F\u0648\u0644\u0629 \u0645\u0623\u0647\u0648\u0644\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u062A\u0631\u0649 \u0634\u0631\u0648\u0642 \u0634\u0645\u0633 \u0643\u0644 \u064A\u0648\u0645 \u062C\u062F\u064A\u062F \u0648\u062A\u0642\u0639 \u0641\u064A \u0623\u0642\u0635\u0649 \u062E\u0637 \u0627\u0644\u062A\u0648\u0642\u064A\u062A (UTC+14)\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0643\u064A\u0631\u064A\u0628\u0627\u062A\u064A (Kiribati)", explanation: "\u0639\u062F\u0644\u062A \u0643\u064A\u0631\u064A\u0628\u0627\u062A\u064A \u062E\u0637 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062F\u0648\u0644\u064A \u0639\u0627\u0645 1995 \u0644\u062A\u0635\u0628\u062D \u062C\u0632\u0631 \u0644\u0627\u064A\u0646 \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u0647\u0627 \u0623\u0648\u0644 \u0628\u0642\u0639\u0629 \u062A\u0633\u062A\u0642\u0628\u0644 \u0627\u0644\u064A\u0648\u0645 \u0627\u0644\u062C\u062F\u064A\u062F.", source: "\u0627\u0644\u0645\u0648\u0627\u0642\u064A\u062A \u0648\u062E\u0637\u0648\u0637 \u0627\u0644\u0637\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u062F\u0648\u0644\u0629 \u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0635\u063A\u064A\u0631\u0629 \u062C\u062F\u0627\u064B \u062A\u0642\u0639 \u0641\u064A \u062C\u0628\u0627\u0644 \u0627\u0644\u0628\u0631\u0627\u0646\u0633 \u0628\u064A\u0646 \u0641\u0631\u0646\u0633\u0627 \u0648\u0625\u0633\u0628\u0627\u0646\u064A\u0627 \u0648\u064A\u062D\u0643\u0645\u0647\u0627 \u0631\u0626\u064A\u0633\u0627 \u062F\u0648\u0644\u0629 \u0645\u0634\u0627\u0631\u0643\u0627\u0646 (\u0623\u062D\u062F\u0647\u0645\u0627 \u0631\u0626\u064A\u0633 \u0641\u0631\u0646\u0633\u0627 \u0648\u0627\u0644\u0622\u062E\u0631 \u0623\u0633\u0642\u0641 \u0623\u0648\u0631\u063A\u0644)\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0623\u0646\u062F\u0648\u0631\u0627 (Andorra)", explanation: "\u0625\u0645\u0627\u0631\u0629 \u0623\u0646\u062F\u0648\u0631\u0627 \u062A\u062E\u0636\u0639 \u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0631\u0626\u0627\u0633\u0629 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u0629 \u0628\u064A\u0646 \u0631\u0626\u064A\u0633 \u0641\u0631\u0646\u0633\u0627 \u0648\u0623\u0633\u0642\u0641 \u0623\u0628\u0631\u0634\u064A\u0629 \u0623\u0648\u0631\u063A\u0644 \u0627\u0644\u0643\u0627\u062A\u0627\u0644\u0648\u0646\u064A.", source: "\u0627\u0644\u062F\u0633\u0627\u062A\u064A\u0631 \u0648\u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0645\u0644\u0643\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u062F\u0648\u0644\u0629 \u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u062A\u0634\u062A\u0647\u0631 \u0628\u062A\u0633\u062C\u064A\u0644\u0647\u0627 \u0623\u0633\u0631\u0639 \u0646\u0645\u0648 \u0627\u0642\u062A\u0635\u0627\u062F\u064A \u0641\u064A \u0627\u0644\u0642\u0627\u0631\u0629 \u0628\u0639\u062F \u0627\u0643\u062A\u0634\u0627\u0641 \u0627\u0644\u0623\u0644\u0645\u0627\u0633 \u0639\u0627\u0645 1967 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u063A\u0627\u0628\u0648\u0631\u0648\u0646 \u0648\u0645\u062D\u0645\u064A\u0629 \u062F\u0644\u062A\u0627 \u0623\u0648\u0643\u0627\u0641\u0627\u0646\u063A\u0648\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0628\u0648\u062A\u0633\u0648\u0627\u0646\u0627 (Botswana)", explanation: "\u062A\u0639\u062F \u0628\u0648\u062A\u0633\u0648\u0627\u0646\u0627 \u0646\u0645\u0648\u0630\u062C\u0627\u064B \u0625\u0641\u0631\u064A\u0642\u064A\u0627\u064B \u0641\u064A \u0627\u0644\u0627\u0633\u062A\u0642\u0631\u0627\u0631 \u0648\u0627\u0644\u062F\u064A\u0645\u0642\u0631\u0627\u0637\u064A\u0629 \u0648\u0625\u062F\u0627\u0631\u0629 \u062B\u0631\u0648\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0633 \u0648\u0635\u062D\u0631\u0627\u0621 \u0643\u0627\u0644\u0627\u0647\u0627\u0631\u064A.", source: "\u0627\u0642\u062A\u0635\u0627\u062F\u0627\u062A \u0625\u0641\u0631\u064A\u0642\u064A\u0627" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0645\u0644\u0643 \u0639\u0627\u0635\u0645\u0629 \u0631\u0633\u0645\u064A\u0629 \u0642\u0627\u0646\u0648\u0646\u064A\u0627\u064B \u0628\u062D\u0643\u0645 \u0627\u0644\u062F\u0633\u062A\u0648\u0631\u060C \u0648\u062A\u062A\u062E\u0630 \u064A\u0627\u0631\u064A\u0646 \u0645\u0642\u0631\u0627\u064B \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062A \u0627\u0644\u062D\u0643\u0648\u0645\u064A\u0629\u061F", correctAnswer: "\u0646\u0627\u0648\u0631\u0648 (Nauru)", explanation: "\u0646\u0627\u0648\u0631\u0648 \u0647\u064A \u062C\u0632\u064A\u0631\u0629 \u0641\u0648\u0633\u0641\u0627\u062A\u064A\u0629 \u0635\u063A\u064A\u0631\u0629 \u0641\u064A \u0645\u064A\u0643\u0631\u0648\u0646\u064A\u0632\u064A\u0627 \u0648\u0644\u0627 \u064A\u0648\u062C\u062F \u0646\u0635 \u062F\u0633\u062A\u0648\u0631\u064A \u064A\u062D\u062F\u062F \u0639\u0627\u0635\u0645\u0629 \u0631\u0633\u0645\u064A\u0629 \u0644\u0647\u0627.", source: "\u0623\u0637\u0644\u0633 \u0623\u0648\u0642\u064A\u0627\u0646\u0648\u0633\u064A\u0627" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u062F\u0648\u0644\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u062A\u0639\u062A\u0628\u0631 \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u063A\u064A\u0631 \u0627\u0644\u0646\u0627\u0637\u0642\u0629 \u0628\u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0623\u0648 \u0627\u0644\u0628\u0631\u062A\u063A\u0627\u0644\u064A\u0629 \u0648\u0644\u063A\u062A\u0647\u0627 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0627\u0644\u0647\u0648\u0644\u0646\u062F\u064A\u0629 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0627 \u0628\u0627\u0631\u0627\u0645\u0627\u0631\u064A\u0628\u0648\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0633\u0648\u0631\u064A\u0646\u0627\u0645 (Suriname)", explanation: "\u0633\u0648\u0631\u064A\u0646\u0627\u0645 \u0643\u0627\u0646\u062A \u0645\u0633\u062A\u0639\u0645\u0631\u0629 \u0647\u0648\u0644\u0646\u062F\u064A\u0629 \u0633\u0627\u0628\u0642\u0629 \u0648\u062A\u0639\u062F \u0644\u063A\u062A\u0647\u0627 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u062D\u062A\u0649 \u0627\u0644\u064A\u0648\u0645 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0647\u0648\u0644\u0646\u062F\u064A\u0629.", source: "\u0623\u0637\u0644\u0633 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629" }
      ],
      "\u0627\u0639\u0644\u0627\u0645": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u064A\u062D\u062A\u0648\u064A \u0639\u0644\u0645\u0647\u0627 \u0639\u0644\u0649 \u0648\u0631\u0642\u0629 \u0634\u062C\u0631 \u0627\u0644\u0642\u064A\u0642\u0628 (\u0627\u0644\u0628\u0644\u0633\u0627\u0646) \u0627\u0644\u062D\u0645\u0631\u0627\u0621 \u0641\u064A \u0648\u0633\u0637\u0647\u061F", correctAnswer: "\u0643\u0646\u062F\u0627", explanation: "\u0648\u0631\u0642\u0629 \u0627\u0644\u0642\u064A\u0642\u0628 \u0647\u064A \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0648\u0637\u0646\u064A \u0627\u0644\u0623\u0643\u062B\u0631 \u0634\u0647\u0631\u0629 \u0644\u0639\u0644\u0645 \u0643\u0646\u062F\u0627 \u0627\u0644\u0645\u0639\u062A\u0645\u062F \u0639\u0627\u0645 1965.", source: "\u062F\u0644\u064A\u0644 \u0623\u0639\u0644\u0627\u0645 \u062F\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u064A\u062A\u0645\u064A\u0632 \u0639\u0644\u0645\u0647\u0627 \u0628\u0648\u062C\u0648\u062F \u0642\u0631\u0635 \u062F\u0627\u0626\u0631\u064A \u0623\u062D\u0645\u0631 \u0641\u064A \u0645\u0646\u062A\u0635\u0641 \u062E\u0644\u0641\u064A\u0629 \u0628\u064A\u0636\u0627\u0621 \u0646\u0642\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u064A\u0627\u0628\u0627\u0646", explanation: "\u064A\u0639\u0631\u0641 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u064A \u0628\u0640 \xAB\u0647\u064A\u0646\u0648\u0645\u0627\u0631\u0648\xBB \u0648\u064A\u0645\u062B\u0644 \u0642\u0631\u0635 \u0627\u0644\u0634\u0645\u0633 \u0627\u0644\u0645\u0634\u0631\u0642\u0629.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0623\u0639\u0644\u0627\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0628\u0627\u0631\u0629 \u0627\u0644\u062A\u0648\u062D\u064A\u062F \u0627\u0644\u0645\u0643\u062A\u0648\u0628\u0629 \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u0628\u064A\u0636 \u0639\u0644\u0649 \u0639\u0644\u0645 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0627\u0644\u0623\u062E\u0636\u0631\u061F", correctAnswer: "\u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0645\u062D\u0645\u062F \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647", explanation: "\u064A\u062A\u0645\u064A\u0632 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0633\u0639\u0648\u062F\u064A \u0628\u0648\u062C\u0648\u062F \u0643\u0644\u0645\u0629 \u0627\u0644\u062A\u0648\u062D\u064A\u062F \u0648\u0633\u064A\u0641 \u0645\u0633\u0644\u0648\u0644 \u064A\u0631\u0645\u0632 \u0644\u0644\u0639\u062F\u0644 \u0648\u0627\u0644\u0642\u0648\u0629.", source: "\u0646\u0638\u0627\u0645 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0633\u0639\u0648\u062F\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u0646\u062C\u0648\u0645 \u0627\u0644\u0645\u0648\u062C\u0648\u062F\u0629 \u0639\u0644\u0649 \u0639\u0644\u0645 \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629\u060C \u0648\u0625\u0644\u0649 \u0645\u0627\u0630\u0627 \u062A\u0631\u0645\u0632\u061F", correctAnswer: "50 \u0646\u062C\u0645\u0629 \u062A\u0631\u0645\u0632 \u0644\u0640 50 \u0648\u0644\u0627\u064A\u0629 \u0623\u0645\u0631\u064A\u0643\u064A\u0629", explanation: "\u062A\u0645\u062B\u0644 \u0643\u0644 \u0646\u062C\u0645\u0629 \u062E\u0645\u0627\u0633\u064A\u0629 \u0648\u0644\u0627\u064A\u0629 \u0645\u0646 \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0648\u0627\u0644\u062E\u0637\u0648\u0637 \u0627\u0644\u0640 13 \u062A\u0645\u062B\u0644 \u0627\u0644\u0645\u0633\u062A\u0639\u0645\u0631\u0627\u062A \u0627\u0644\u0623\u0648\u0644\u0649.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0637\u0627\u0626\u0631 \u0648\u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0623\u0633\u0637\u0648\u0631\u064A \u0627\u0644\u0645\u0648\u062C\u0648\u062F \u0641\u064A \u0645\u0646\u062A\u0635\u0641 \u0639\u0644\u0645 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0645\u0635\u0631 \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u061F", correctAnswer: "\u0646\u0633\u0631 \u0635\u0644\u0627\u062D \u0627\u0644\u062F\u064A\u0646 \u0627\u0644\u0630\u0647\u0628\u064A", explanation: "\u064A\u062A\u0648\u0633\u0637 \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u0623\u0628\u064A\u0636 \u0641\u064A \u0639\u0644\u0645 \u0645\u0635\u0631 \u0646\u0633\u0631 \u0635\u0644\u0627\u062D \u0627\u0644\u062F\u064A\u0646 \u0628\u0644\u0648\u0646 \u0630\u0647\u0628\u064A \u0628\u0627\u0633\u0637\u0627\u064B \u062C\u0646\u0627\u062D\u064A\u0647.", source: "\u0627\u0644\u0647\u064A\u0626\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0644\u0627\u0633\u062A\u0639\u0644\u0627\u0645\u0627\u062A \u0627\u0644\u0645\u0635\u0631\u064A\u0629" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u062A\u064A \u0644\u0627 \u064A\u062A\u062E\u0630 \u0639\u0644\u0645\u0647\u0627 \u0627\u0644\u0648\u0637\u0646\u064A \u0634\u0643\u0644\u0627\u064B \u0645\u0633\u062A\u0637\u064A\u0644\u0627\u064B \u0623\u0648 \u0645\u0631\u0628\u0639\u0627\u064B \u0628\u0644 \u0645\u062B\u0644\u062B\u064A\u0646 \u0645\u062A\u062F\u0627\u062E\u0644\u064A\u0646\u061F", correctAnswer: "\u0646\u064A\u0628\u0627\u0644 (Nepal)", explanation: "\u0639\u0644\u0645 \u0646\u064A\u0628\u0627\u0644 \u0647\u0648 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0648\u0637\u0646\u064A \u0627\u0644\u0648\u062D\u064A\u062F \u063A\u064A\u0631 \u0631\u0628\u0627\u0639\u064A \u0627\u0644\u0623\u0636\u0644\u0627\u0639 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u064A\u062A\u0643\u0648\u0646 \u0645\u0646 \u0645\u062B\u0644\u062B\u064A\u0646 \u0645\u062A\u0631\u0627\u0643\u0628\u064A\u0646.", source: "\u0639\u0644\u0645 \u0627\u0644\u0641\u064A\u0643\u0633\u064A\u0644\u0648\u0644\u0648\u062C\u064A\u0627 (\u062F\u0631\u0627\u0633\u0629 \u0627\u0644\u0623\u0639\u0644\u0627\u0645)" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0648\u062C\u0648\u062F \u0641\u064A \u0648\u0633\u0637 \u0627\u0644\u062E\u0637 \u0627\u0644\u0623\u0628\u064A\u0636 \u0644\u0639\u0644\u0645 \u0644\u0628\u0646\u0627\u0646 \u0628\u064A\u0646 \u0627\u0644\u062E\u0637\u064A\u0646 \u0627\u0644\u0623\u062D\u0645\u0631\u064A\u0646\u061F", correctAnswer: "\u0634\u062C\u0631\u0629 \u0627\u0644\u0623\u0631\u0632 \u0627\u0644\u062E\u0636\u0631\u0627\u0621", explanation: "\u062A\u0631\u0645\u0632 \u0634\u062C\u0631\u0629 \u0627\u0644\u0623\u0631\u0632 \u0641\u064A \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0644\u0628\u0646\u0627\u0646\u064A \u0625\u0644\u0649 \u0627\u0644\u062E\u0644\u0648\u062F \u0648\u0627\u0644\u0634\u0645\u0648\u062E \u0648\u0627\u0644\u0633\u0644\u0627\u0645.", source: "\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u0627\u0644\u0627\u0633\u0643\u0646\u062F\u0646\u0627\u0641\u064A\u062A\u0627\u0646 \u0627\u0644\u0644\u062A\u0627\u0646 \u064A\u0634\u0628\u0647 \u0639\u0644\u0645\u0627\u0647\u0645\u0627 \u0635\u0644\u064A\u0628 \u0627\u0644\u0634\u0645\u0627\u0644 \u0628\u0644\u0648\u0646\u064A\u0646: \u0623\u0635\u0641\u0631 \u0639\u0644\u0649 \u0623\u0632\u0631\u0642\u060C \u0648\u0623\u0628\u064A\u0636 \u0639\u0644\u0649 \u0623\u062D\u0645\u0631\u061F", correctAnswer: "\u0627\u0644\u0633\u0648\u064A\u062F (\u0623\u0635\u0641\u0631 \u0639\u0644\u0649 \u0623\u0632\u0631\u0642) \u0648\u0627\u0644\u062F\u0646\u0645\u0627\u0631\u0643 (\u0623\u0628\u064A\u0636 \u0639\u0644\u0649 \u0623\u062D\u0645\u0631)", explanation: "\u0627\u0644\u062F\u0646\u0645\u0627\u0631\u0643 \u062A\u062D\u0645\u0644 \u0623\u0642\u062F\u0645 \u0639\u0644\u0645 \u0645\u0633\u062A\u062E\u062F\u0645 \u0628\u0627\u0633\u062A\u0645\u0631\u0627\u0631 (\u062F\u0627\u0646\u064A\u0628\u0631\u0648\u063A) \u0648\u0627\u0644\u0633\u0648\u064A\u062F \u0628\u0627\u0644\u0623\u0635\u0641\u0631 \u0648\u0627\u0644\u0623\u0632\u0631\u0642.", source: "\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0625\u0633\u0643\u0646\u062F\u0646\u0627\u0641\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u0646\u062C\u0648\u0645 \u0627\u0644\u0635\u0641\u0631\u0627\u0621 \u0627\u0644\u062E\u0645\u0627\u0633\u064A\u0629 \u0627\u0644\u0645\u0648\u062C\u0648\u062F\u0629 \u0639\u0644\u0649 \u0639\u0644\u0645 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u0635\u064A\u0646 \u0627\u0644\u0634\u0639\u0628\u064A\u0629 \u0627\u0644\u0623\u062D\u0645\u0631\u061F", correctAnswer: "5 \u0646\u062C\u0648\u0645 (\u0646\u062C\u0645\u0629 \u0643\u0628\u0631\u0649 \u0648\u0623\u0631\u0628\u0639 \u0646\u062C\u0648\u0645 \u0635\u063A\u0631\u0649)", explanation: "\u062A\u0631\u0645\u0632 \u0627\u0644\u0646\u062C\u0645\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0644\u0644\u062D\u0632\u0628 \u0627\u0644\u0634\u064A\u0648\u0639\u064A \u0648\u0627\u0644\u0646\u062C\u0648\u0645 \u0627\u0644\u0623\u0631\u0628\u0639 \u0644\u0637\u0628\u0642\u0627\u062A \u0627\u0644\u0634\u0639\u0628 \u0627\u0644\u0645\u0644\u062A\u0641\u0629 \u062D\u0648\u0644\u0647.", source: "\u062F\u0644\u064A\u0644 \u0623\u0639\u0644\u0627\u0645 \u0622\u0633\u064A\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u062F\u0627\u0626\u0631\u064A \u0630\u0648 \u0627\u0644\u0623\u0634\u0639\u0629 \u0627\u0644\u0645\u0648\u062C\u0648\u062F \u0641\u064A \u0645\u0631\u0643\u0632 \u0639\u0644\u0645 \u0627\u0644\u0623\u0631\u062C\u0646\u062A\u064A\u0646 \u0648\u0639\u0644\u0645 \u0627\u0644\u0623\u0648\u0631\u0648\u063A\u0648\u0627\u064A\u061F", correctAnswer: "\u0634\u0645\u0633 \u0623\u064A\u0627\u0631 (\u0634\u0645\u0633 \u0645\u0627\u064A\u0648 / Sun of May)", explanation: "\u062A\u0631\u0645\u0632 \u0634\u0645\u0633 \u0623\u064A\u0627\u0631 \u0644\u062B\u0648\u0631\u0629 \u0645\u0627\u064A\u0648 1810 \u0648\u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u062F\u0648\u0644 \u062D\u0648\u0636 \u0631\u064A\u0648 \u062F\u064A \u0644\u0627 \u0628\u0644\u0627\u062A\u0627.", source: "\u062A\u0627\u0631\u064A\u062E \u0623\u0639\u0644\u0627\u0645 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u062A\u064A \u064A\u0638\u0647\u0631 \u0639\u0644\u0649 \u0639\u0644\u0645\u0647\u0627 \u0627\u0644\u0648\u0637\u0646\u064A \u0633\u0644\u0627\u062D \u0643\u0644\u0627\u0634\u064A\u0646\u0643\u0648\u0641 (AK-47) \u062D\u062F\u064A\u062B\u061F", correctAnswer: "\u0645\u0648\u0632\u0645\u0628\u064A\u0642 (Mozambique)", explanation: "\u064A\u062D\u062A\u0648\u064A \u0639\u0644\u0645 \u0645\u0648\u0632\u0645\u0628\u064A\u0642 \u0639\u0644\u0649 \u0643\u062A\u0627\u0628 \u0648\u0628\u0646\u062F\u0642\u064A\u0629 \u0643\u0644\u0627\u0634\u064A\u0646\u0643\u0648\u0641 \u0648\u0641\u0623\u0633 \u062A\u0631\u0645\u0632 \u0644\u0644\u062A\u0639\u0644\u064A\u0645 \u0648\u0627\u0644\u062F\u0641\u0627\u0639 \u0648\u0627\u0644\u0632\u0631\u0627\u0639\u0629.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0639\u0644\u0645 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629 (Union Jack) \u0647\u0648 \u062F\u0645\u062C \u0644\u0635\u0644\u0628\u0627\u0646 \u062B\u0644\u0627\u062B\u0629 \u0642\u062F\u064A\u0633\u064A\u0646\u060C \u0641\u0645\u0646 \u0647\u0645\u061F", correctAnswer: "\u0627\u0644\u0642\u062F\u064A\u0633 \u062C\u0627\u0648\u0631\u062C\u064A\u0648\u0633 (\u0625\u0646\u062C\u0644\u062A\u0631\u0627)\u060C \u0648\u0627\u0644\u0642\u062F\u064A\u0633 \u0623\u0646\u062F\u0631\u0627\u0648\u0633 (\u0627\u0633\u0643\u062A\u0644\u0646\u062F\u0627)\u060C \u0648\u0627\u0644\u0642\u062F\u064A\u0633 \u0628\u0627\u062A\u0631\u064A\u0643 (\u0625\u064A\u0631\u0644\u0646\u062F\u0627)", explanation: "\u064A\u062F\u0645\u062C \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0635\u0644\u064A\u0628 \u0627\u0644\u0623\u062D\u0645\u0631 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A \u0648\u0635\u0644\u064A\u0628 \u0627\u0633\u0643\u062A\u0644\u0646\u062F\u0627 \u0627\u0644\u0645\u0627\u0626\u0644 \u0648\u0635\u0644\u064A\u0628 \u0627\u0644\u0642\u062F\u064A\u0633 \u0628\u0627\u062A\u0631\u064A\u0643 \u0627\u0644\u0625\u064A\u0631\u0644\u0646\u062F\u064A.", source: "\u062A\u0627\u0631\u064A\u062E \u0639\u0644\u0645 \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u064A\u062D\u0645\u0644 \u0639\u0644\u0645\u0647\u0627 \u0639\u0628\u0627\u0631\u0629 \xABOrdem e Progresso\xBB (\u0627\u0644\u0646\u0638\u0627\u0645 \u0648\u0627\u0644\u062A\u0642\u062F\u0645) \u0641\u0648\u0642 \u0643\u0631\u0629 \u0633\u0645\u0627\u0648\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644", explanation: "\u0627\u0644\u0639\u0628\u0627\u0631\u0629 \u0645\u0642\u062A\u0628\u0633\u0629 \u0645\u0646 \u0627\u0644\u0641\u0644\u0633\u0641\u0629 \u0627\u0644\u0648\u0636\u0639\u064A\u0629 \u0644\u0623\u0648\u063A\u0633\u062A \u0643\u0648\u0646\u062A \u0648\u062A\u062A\u0648\u0633\u0637 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644\u064A \u0627\u0644\u0623\u062E\u0636\u0631 \u0648\u0627\u0644\u0623\u0635\u0641\u0631.", source: "\u062F\u0633\u062A\u0648\u0631 \u0648\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u062A\u064A \u064A\u062E\u062A\u0644\u0641 \u0648\u062C\u0647 \u0639\u0644\u0645\u0647\u0627 \u0627\u0644\u0623\u0645\u0627\u0645\u064A \u0639\u0646 \u0648\u062C\u0647\u0647 \u0627\u0644\u062E\u0644\u0641\u064A \u0628\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0634\u0639\u0627\u0631 \u0645\u0646 \u0627\u0644\u062E\u0644\u0641\u061F", correctAnswer: "\u0628\u0627\u0631\u0627\u063A\u0648\u0627\u064A (Paraguay)", explanation: "\u064A\u062D\u0645\u0644 \u0627\u0644\u0648\u062C\u0647 \u0627\u0644\u0623\u0645\u0627\u0645\u064A \u0644\u0639\u0644\u0645 \u0628\u0627\u0631\u0627\u063A\u0648\u0627\u064A \u0634\u0639\u0627\u0631 \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A \u0628\u064A\u0646\u0645\u0627 \u064A\u062D\u0645\u0644 \u0627\u0644\u0648\u062C\u0647 \u0627\u0644\u062E\u0644\u0641\u064A \u062E\u062A\u0645 \u0627\u0644\u062E\u0632\u0627\u0646\u0629 (\u0623\u0633\u062F \u0648\u0642\u0628\u0639\u0629 \u062D\u0631\u064A\u0629).", source: "\u063A\u0631\u0627\u0626\u0628 \u0627\u0644\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0648\u0637\u0646\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0646\u062C\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u062A\u0648\u0633\u0637 \u0639\u0644\u0645 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u063A\u0631\u0628\u064A\u0629\u060C \u0648\u0645\u0627 \u0647\u0648 \u0644\u0648\u0646\u0647\u0627 \u0648\u0639\u062F\u062F \u0631\u0624\u0648\u0633\u0647\u0627\u061F", correctAnswer: "\u0646\u062C\u0645\u0629 \u062E\u0645\u0627\u0633\u064A\u0629 \u062E\u0636\u0631\u0627\u0621", explanation: "\u0627\u0644\u062E\u0627\u062A\u0645 \u0627\u0644\u0633\u0644\u064A\u0645\u0627\u0646\u064A \u0647\u0648 \u0646\u062C\u0645\u0629 \u062E\u0645\u0627\u0633\u064A\u0629 \u062E\u0636\u0631\u0627\u0621 \u062A\u0631\u0645\u0632 \u0644\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u062E\u0645\u0633\u0629 \u0639\u0644\u0649 \u062E\u0644\u0641\u064A\u0629 \u062D\u0645\u0631\u0627\u0621.", source: "\u0627\u0644\u0645\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u0644\u0643\u064A \u0644\u0644\u0639\u0644\u0645 \u0627\u0644\u0645\u063A\u0631\u0628\u064A" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0645\u0627 \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u0627\u0644\u0645\u0633\u062A\u0642\u0644\u062A\u0627\u0646 \u0627\u0644\u0648\u062D\u064A\u062F\u062A\u0627\u0646 \u0627\u0644\u0644\u062A\u0627\u0646 \u062A\u0633\u062A\u062E\u062F\u0645\u0627\u0646 \u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0628\u0646\u0641\u0633\u062C\u064A (\u0627\u0644\u0623\u0631\u062C\u0648\u0627\u0646\u064A) \u0646\u0627\u062F\u0631\u0627\u064B \u0641\u064A \u062A\u0641\u0627\u0635\u064A\u0644 \u0639\u0644\u0645\u064A\u0647\u0645\u0627 \u0627\u0644\u0648\u0637\u0646\u064A\u064A\u0646\u061F", correctAnswer: "\u062F\u0648\u0645\u064A\u0646\u064A\u0643\u0627 \u0648\u0646\u064A\u0643\u0627\u0631\u0627\u063A\u0648\u0627", explanation: "\u062F\u0648\u0645\u064A\u0646\u064A\u0643\u0627 \u0641\u064A \u0631\u064A\u0634 \u0628\u0628\u063A\u0627\u0621 \u0627\u0644\u0633\u064A\u0633\u064A\u0631\u0648\u060C \u0648\u0646\u064A\u0643\u0627\u0631\u0627\u063A\u0648\u0627 \u0641\u064A \u0642\u0648\u0633 \u0642\u0632\u062D \u062F\u0627\u062E\u0644 \u0645\u062B\u0644\u062B \u0627\u0644\u0634\u0639\u0627\u0631 \u0627\u0644\u0648\u0637\u0646\u064A.", source: "\u0623\u0628\u062D\u0627\u062B \u0627\u0644\u0641\u064A\u0643\u0633\u064A\u0644\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0622\u0633\u064A\u0648\u064A\u0629 \u0627\u0644\u062A\u064A \u064A\u062A\u0648\u0633\u0637 \u0639\u0644\u0645\u0647\u0627 \u0627\u0644\u0648\u0637\u0646\u064A \u0645\u0639\u0628\u062F \u0623\u0646\u063A\u0643\u0648\u0631 \u0648\u0627\u062A \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0627\u0644\u0634\u0647\u064A\u0631\u061F", correctAnswer: "\u0643\u0645\u0628\u0648\u062F\u064A\u0627 (Cambodia)", explanation: "\u0643\u0645\u0628\u0648\u062F\u064A\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u062A\u064A \u064A\u0638\u0647\u0631 \u0645\u0628\u0646\u0649 \u0648\u0645\u0639\u0644\u0645 \u0645\u0639\u0645\u0627\u0631\u064A \u062D\u0642\u064A\u0642\u064A \u0639\u0644\u0649 \u0639\u0644\u0645\u0647\u0627.", source: "\u0623\u0639\u0644\u0627\u0645 \u062F\u0648\u0644 \u0622\u0633\u064A\u0627" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0645\u0627 \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u0627\u0644\u0645\u0633\u062A\u0642\u0644\u062A\u0627\u0646 \u0627\u0644\u0644\u062A\u0627\u0646 \u062A\u0645\u0644\u0643\u0627\u0646 \u0639\u0644\u0645\u064A\u0646 \u0645\u062A\u0637\u0627\u0628\u0642\u064A\u0646 \u062A\u0642\u0631\u064A\u0628\u0627\u064B \u0628\u0646\u0641\u0633 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u0623\u0641\u0642\u064A\u0629: \u0623\u0632\u0631\u0642\u060C \u0623\u0635\u0641\u0631\u060C \u0623\u062D\u0645\u0631\u061F", correctAnswer: "\u062A\u0634\u0627\u062F \u0648\u0631\u0648\u0645\u0627\u0646\u064A\u0627", explanation: "\u0639\u0644\u0645 \u062A\u0634\u0627\u062F \u0648\u0639\u0644\u0645 \u0631\u0648\u0645\u0627\u0646\u064A\u0627 \u0645\u062A\u0637\u0627\u0628\u0642\u0627\u0646 \u062A\u0642\u0631\u064A\u0628\u0627\u064B \u0641\u064A \u062A\u0631\u062A\u064A\u0628 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 (\u0645\u0639 \u0641\u0627\u0631\u0642 \u0637\u0641\u064A\u0641 \u062C\u062F\u0627\u064B \u0641\u064A \u062F\u0631\u062C\u0629 \u0627\u0644\u0623\u0632\u0631\u0642).", source: "\u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 - \u0642\u0633\u0645 \u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u0646\u062C\u0648\u0645 \u0627\u0644\u0645\u0648\u062C\u0648\u062F\u0629 \u0639\u0644\u0649 \u0639\u0644\u0645 \u0627\u0644\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A \u0630\u064A \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u0627\u0644\u0632\u0631\u0642\u0627\u0621\u061F", correctAnswer: "12 \u0646\u062C\u0645\u0629 \u0630\u0647\u0628\u064A\u0629", explanation: "\u062A\u0645\u062B\u0644 \u0627\u0644\u0640 12 \u0646\u062C\u0645\u0629 \u0627\u0644\u0643\u0645\u0627\u0644 \u0648\u0627\u0644\u0648\u062D\u062F\u0629 \u0648\u0627\u0644\u062A\u0636\u0627\u0645\u0646 \u0648\u0644\u0627 \u062A\u0631\u062A\u0628\u0637 \u0628\u0639\u062F\u062F \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0641\u064A \u0627\u0644\u0627\u062A\u062D\u0627\u062F.", source: "\u0627\u0644\u0645\u0641\u0648\u0636\u064A\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0627\u0644\u0623\u0633\u0637\u0648\u0631\u064A \u0627\u0644\u0645\u0631\u0633\u0648\u0645 \u0641\u064A \u0648\u0633\u0637 \u0639\u0644\u0645 \u062F\u0648\u0644\u0629 \u0628\u0648\u062A\u0627\u0646 \u0641\u064A \u062C\u0628\u0627\u0644 \u0627\u0644\u0647\u064A\u0645\u0627\u0644\u0627\u064A\u0627\u061F", correctAnswer: "\u062A\u0646\u064A\u0646 \u0627\u0644\u0631\u0639\u062F \u0627\u0644\u0623\u0628\u064A\u0636 (\u062F\u0631\u0648\u0643 / Druk)", explanation: "\u0628\u0648\u062A\u0627\u0646 \u062A\u0633\u0645\u0649 \u0628\u0623\u0631\u0636 \u062A\u0646\u064A\u0646 \u0627\u0644\u0631\u0639\u062F\u060C \u0648\u064A\u062D\u0645\u0644 \u0627\u0644\u062A\u0646\u064A\u0646 \u0641\u064A \u0645\u062E\u0627\u0644\u0628\u0647 \u062C\u0648\u0627\u0647\u0631 \u062A\u0631\u0645\u0632 \u0625\u0644\u0649 \u0627\u0644\u0631\u062E\u0627\u0621 \u0648\u0627\u0644\u062B\u0631\u0648\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0645\u0645\u0644\u0643\u0629 \u0628\u0648\u062A\u0627\u0646" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u0643\u0627\u0646 \u0639\u0644\u0645\u0647\u0627 \u0645\u062A\u0637\u0627\u0628\u0642\u0627\u064B \u062A\u0645\u0627\u0645\u0627\u064B \u0645\u0639 \u0639\u0644\u0645 \u0647\u0627\u064A\u064A\u062A\u064A\u060C \u0648\u0627\u0643\u062A\u0634\u0641\u0627 \u0630\u0644\u0643 \u0641\u064A \u0623\u0648\u0644\u0645\u0628\u064A\u0627\u062F 1936 \u0641\u0623\u0636\u0627\u0641\u062A \u062A\u0627\u062C\u0627\u064B \u0644\u0639\u0644\u0645\u0647\u0627\u061F", correctAnswer: "\u0644\u064A\u062E\u062A\u0646\u0634\u062A\u0627\u064A\u0646 (Liechtenstein)", explanation: "\u0641\u064A \u0623\u0648\u0644\u0645\u0628\u064A\u0627\u062F \u0628\u0631\u0644\u064A\u0646 1936 \u0644\u0627\u062D\u0638\u062A \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u062A\u0637\u0627\u0628\u0642 \u0627\u0644\u0639\u0644\u0645\u064A\u0646\u060C \u0641\u0642\u0627\u0645\u062A \u0644\u064A\u062E\u062A\u0646\u0634\u062A\u0627\u064A\u0646 \u0628\u0625\u0636\u0627\u0641\u0629 \u062A\u0627\u062C \u0630\u0647\u0628\u064A \u0623\u0632\u0631\u0642 \u0641\u064A \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u062A\u0627\u0644\u064A.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062D\u0631\u0643\u0629 \u0627\u0644\u0623\u0648\u0644\u0645\u0628\u064A\u0629 \u0648\u0627\u0644\u0623\u0639\u0644\u0627\u0645" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u0643\u0627\u0646 \u0639\u0644\u0645\u0647\u0627 \u0641\u064A \u0627\u0644\u0641\u062A\u0631\u0629 \u0628\u064A\u0646 1977 \u06482011 \u0639\u0628\u0627\u0631\u0629 \u0639\u0646 \u0645\u0633\u062A\u0637\u064A\u0644 \u0628\u0644\u0648\u0646 \u0623\u062E\u0636\u0631 \u0645\u0648\u062D\u062F \u062F\u0648\u0646 \u0623\u064A \u0631\u0633\u0645 \u0623\u0648 \u0643\u062A\u0627\u0628\u0629\u061F", correctAnswer: "\u0644\u064A\u0628\u064A\u0627 (\u0641\u064A \u0639\u0647\u062F \u0627\u0644\u062C\u0645\u0627\u0647\u064A\u0631\u064A\u0629)", explanation: "\u0643\u0627\u0646 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0644\u064A\u0628\u064A \u0627\u0644\u0623\u062E\u0636\u0631 \u0627\u0644\u0645\u0648\u062D\u062F \u0647\u0648 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0648\u062D\u064A\u062F \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0628\u0644\u0648\u0646 \u0648\u0627\u062D\u062F \u062E\u0627\u0644\u0635 \u062F\u0648\u0646 \u0623\u064A \u0631\u0645\u0648\u0632 \u0637\u0648\u0627\u0644 34 \u0639\u0627\u0645\u0627\u064B.", source: "\u062A\u0627\u0631\u064A\u062E \u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0639\u0631\u0628\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0627\u0644\u0645\u0641\u062A\u0631\u0633 \u0627\u0644\u0630\u064A \u064A\u062D\u0645\u0644 \u0633\u064A\u0641\u0627\u064B \u0641\u064A \u064A\u062F\u0647 \u0648\u064A\u0638\u0647\u0631 \u0639\u0644\u0649 \u0639\u0644\u0645 \u062F\u0648\u0644\u0629 \u0633\u0631\u064A\u0644\u0627\u0646\u0643\u0627\u061F", correctAnswer: "\u0627\u0644\u0623\u0633\u062F \u0627\u0644\u0630\u0647\u0628\u064A (\u0633\u0644\u0627\u0644\u0629 \u0627\u0644\u0633\u0646\u0647\u0627\u0644)", explanation: "\u064A\u0631\u0645\u0632 \u0627\u0644\u0623\u0633\u062F \u0627\u0644\u0630\u0647\u0628\u064A \u0625\u0644\u0649 \u0642\u0648\u0645\u064A\u0629 \u0627\u0644\u0633\u0646\u0647\u0627\u0644 \u0648\u064A\u062D\u0645\u0644 \u0633\u064A\u0641 \u0627\u0644\u0642\u0634\u062A\u0627\u0644\u0629 \u0643\u0631\u0645\u0632 \u0644\u0644\u0634\u062C\u0627\u0639\u0629 \u0648\u0627\u0644\u0633\u064A\u0627\u062F\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0639\u0644\u0645 \u0633\u0631\u064A\u0644\u0627\u0646\u0643\u0627" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0645\u0627 \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u062A\u0627\u0646 \u0627\u0644\u0648\u062D\u064A\u062F\u062A\u0627\u0646 \u0627\u0644\u0644\u062A\u0627\u0646 \u064A\u062A\u062E\u0630 \u0639\u0644\u0645\u0627\u0647\u0645\u0627 \u0627\u0644\u0648\u0637\u0646\u064A\u0627\u0646 \u0634\u0643\u0644\u0627\u064B \u0647\u0646\u062F\u0633\u064A\u0627\u064B \u0645\u0631\u0628\u0639\u0627\u064B \u0645\u062A\u0633\u0627\u0648\u064A \u0627\u0644\u0623\u0636\u0644\u0627\u0639 \u0628\u0646\u0633\u0628\u0629 (1:1)\u061F", correctAnswer: "\u0633\u0648\u064A\u0633\u0631\u0627 \u0648\u0627\u0644\u0641\u0627\u062A\u064A\u0643\u0627\u0646", explanation: "\u0633\u0648\u064A\u0633\u0631\u0627 \u0648\u062F\u0648\u0644\u0629 \u0627\u0644\u0641\u0627\u062A\u064A\u0643\u0627\u0646 \u0647\u0645\u0627 \u0627\u0644\u062F\u0648\u0644\u062A\u0627\u0646 \u0627\u0644\u0648\u062D\u064A\u062F\u062A\u0627\u0646 \u0630\u0648\u0627\u062A\u0627 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0645\u0631\u0628\u0639 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u062F\u0648\u0644\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0648\u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u064A\u062D\u0645\u0644 \u0639\u0644\u0645\u0647\u0627 \u0631\u0645\u0632 \xAB\u0627\u0644\u062A\u0631\u064A\u0633\u0643\u064A\u0644\u064A\u0648\u0646\xBB \u0627\u0644\u0645\u0643\u0648\u0646 \u0645\u0646 \u062B\u0644\u0627\u062B\u0629 \u0623\u0631\u062C\u0644 \u0628\u0634\u0631\u064A\u0629 \u062A\u062F\u0648\u0631 \u062D\u0648\u0644 \u0645\u0631\u0643\u0632 \u0648\u0627\u062D\u062F\u061F", correctAnswer: "\u062C\u0632\u064A\u0631\u0629 \u0645\u0627\u0646 (Isle of Man)", explanation: "\u0631\u0645\u0632 \u0627\u0644\u062A\u0631\u064A\u0633\u0643\u064A\u0644\u064A\u0648\u0646 \u0628\u0627\u0644\u0623\u0631\u062C\u0644 \u0627\u0644\u062B\u0644\u0627\u062B \u0627\u0644\u0645\u062F\u0631\u0639\u0629 \u0628\u0627\u0644\u0645\u0647\u0627\u0645\u064A\u0632 \u0627\u0644\u0630\u0647\u0628\u064A\u0629 \u064A\u0639\u0648\u062F \u0625\u0644\u0649 \u0623\u0633\u0627\u0637\u064A\u0631 \u0627\u0644\u0642\u0631\u0648\u0646 \u0627\u0644\u0648\u0633\u0637\u0649.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0631\u0645\u0648\u0632 \u0627\u0644\u0634\u0639\u0648\u0628" }
      ],
      "\u062C\u063A\u0631\u0627\u0641\u064A\u0627": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0623\u0637\u0648\u0644 \u0646\u0647\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0646\u0647\u0631 \u0627\u0644\u0646\u064A\u0644", explanation: "\u064A\u0645\u062A\u062F \u0646\u0647\u0631 \u0627\u0644\u0646\u064A\u0644 \u0641\u064A \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0644\u0645\u0633\u0627\u0641\u0629 \u062A\u0642\u0627\u0631\u0628 6650 \u0643\u064A\u0644\u0648\u0645\u062A\u0631\u0627\u064B.", source: "\u0627\u0644\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0644\u0649 \u0642\u0645\u0629 \u062C\u0628\u0644\u064A\u0629 \u0641\u0648\u0642 \u0645\u0633\u062A\u0648\u0649 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0642\u0645\u0629 \u0625\u0641\u0631\u0633\u062A (Everest)", explanation: "\u062A\u0631\u062A\u0641\u0639 \u0642\u0645\u0629 \u0625\u0641\u0631\u0633\u062A \u0641\u064A \u0633\u0644\u0633\u0644\u0629 \u062C\u0628\u0627\u0644 \u0627\u0644\u0647\u064A\u0645\u0627\u0644\u0627\u064A\u0627 8848.86 \u0645\u062A\u0631\u0627\u064B.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0623\u0643\u0628\u0631 \u0645\u062D\u064A\u0637\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645 \u0645\u0633\u0627\u062D\u0629 \u0648\u0639\u0645\u0642\u0627\u064B\u061F", correctAnswer: "\u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 (Pacific Ocean)", explanation: "\u064A\u063A\u0637\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0623\u0643\u062B\u0631 \u0645\u0646 \u062B\u0644\u062B \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0623\u0631\u0636\u064A\u0629.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0645\u062D\u064A\u0637\u0627\u062A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u0642\u0627\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0645\u0646 \u062D\u064A\u062B \u0627\u0644\u0645\u0633\u0627\u062D\u0629 \u0648\u0639\u062F\u062F \u0627\u0644\u0633\u0643\u0627\u0646\u061F", correctAnswer: "\u0642\u0627\u0631\u0629 \u0622\u0633\u064A\u0627", explanation: "\u062A\u0634\u063A\u0644 \u0622\u0633\u064A\u0627 \u0646\u062D\u0648 30% \u0645\u0646 \u0645\u0633\u0627\u062D\u0629 \u064A\u0627\u0628\u0633\u0629 \u0627\u0644\u0623\u0631\u0636 \u0648\u062A\u0636\u0645 \u0646\u062D\u0648 60% \u0645\u0646 \u0633\u0643\u0627\u0646\u0647\u0627.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u0635\u062D\u0631\u0627\u0621 \u062D\u0627\u0631\u0629 \u0648\u062C\u0627\u0641\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0627\u0644\u0635\u062D\u0631\u0627\u0621 \u0627\u0644\u0643\u0628\u0631\u0649 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629", explanation: "\u062A\u0645\u062A\u062F \u0627\u0644\u0635\u062D\u0631\u0627\u0621 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u064A \u0634\u0645\u0627\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0639\u0644\u0649 \u0645\u0633\u0627\u062D\u0629 \u062A\u062A\u062C\u0627\u0648\u0632 9 \u0645\u0644\u0627\u064A\u064A\u0646 \u0643\u064A\u0644\u0648\u0645\u062A\u0631 \u0645\u0631\u0628\u0639.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0623\u0643\u0628\u0631 \u0645\u0633\u0637\u062D \u0645\u0627\u0626\u064A \u0645\u063A\u0644\u0642 (\u0628\u062D\u0631 \u062D\u0628\u064A\u0633 / \u0628\u062D\u064A\u0631\u0629) \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0645\u0646 \u062D\u064A\u062B \u0627\u0644\u0645\u0633\u0627\u062D\u0629\u061F", correctAnswer: "\u0628\u062D\u0631 \u0642\u0632\u0648\u064A\u0646 (Caspian Sea)", explanation: "\u0628\u062D\u0631 \u0642\u0632\u0648\u064A\u0646 \u0647\u0648 \u0623\u0643\u0628\u0631 \u0628\u062D\u064A\u0631\u0629 \u0645\u0627\u0644\u062D\u0629 \u0645\u063A\u0644\u0642\u0629 \u0628\u0645\u0633\u0627\u062D\u0629 \u062A\u0642\u0627\u0631\u0628 371 \u0623\u0644\u0641 \u0643\u0645\xB2.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0647\u0631 \u0627\u0644\u0623\u0643\u062B\u0631 \u062A\u062F\u0641\u0642\u0627\u064B \u0648\u063A\u0632\u0627\u0631\u0629 \u0628\u0627\u0644\u0645\u064A\u0627\u0647 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u064A\u062D\u0645\u0644 \u0623\u0643\u0628\u0631 \u062D\u0648\u0636 \u062A\u0635\u0631\u064A\u0641\u061F", correctAnswer: "\u0646\u0647\u0631 \u0627\u0644\u0623\u0645\u0627\u0632\u0648\u0646", explanation: "\u064A\u0636\u062E \u0627\u0644\u0623\u0645\u0627\u0632\u0648\u0646 \u062E\u0645\u0633 \u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0645\u064A\u0627\u0647 \u0627\u0644\u0639\u0630\u0628\u0629 \u0627\u0644\u062A\u064A \u062A\u0635\u0628\u0647\u0627 \u0623\u0646\u0647\u0627\u0631 \u0627\u0644\u0639\u0627\u0644\u0645 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637\u0627\u062A.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0647\u064A\u062F\u0631\u0648\u0644\u0648\u062C\u064A\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0623\u062E\u0641\u0636 \u0646\u0642\u0637\u0629 \u064A\u0627\u0628\u0633\u0629 \u0639\u0644\u0649 \u0633\u0637\u062D \u0643\u0648\u0643\u0628 \u0627\u0644\u0623\u0631\u0636 \u062A\u062D\u062A \u0645\u0633\u062A\u0648\u0649 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631\u061F", correctAnswer: "\u0634\u0627\u0637\u0626 \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0645\u064A\u062A (\u0628\u064A\u0646 \u0627\u0644\u0623\u0631\u062F\u0646 \u0648\u0641\u0644\u0633\u0637\u064A\u0646)", explanation: "\u064A\u0646\u062E\u0641\u0636 \u0634\u0627\u0637\u0626 \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0645\u064A\u062A \u0628\u0646\u062D\u0648 430 \u0645\u062A\u0631\u0627\u064B \u062A\u062D\u062A \u0645\u0633\u062A\u0648\u0649 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631.", source: "\u0627\u0644\u0645\u0633\u062D \u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0641\u0635\u0644 \u0628\u064A\u0646 \u0642\u0627\u0631\u062A\u064A \u0623\u0648\u0631\u0648\u0628\u0627 \u0648\u0622\u0633\u064A\u0627 \u062F\u0627\u062E\u0644 \u0631\u0648\u0633\u064A\u0627\u061F", correctAnswer: "\u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0648\u0631\u0627\u0644 (Ural Mountains)", explanation: "\u062A\u0645\u062A\u062F \u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0648\u0631\u0627\u0644 \u0645\u0646 \u0627\u0644\u0634\u0645\u0627\u0644 \u0644\u0644\u062C\u0646\u0648\u0628 \u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u062D\u062F \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A \u0628\u064A\u0646 \u0627\u0644\u0642\u0627\u0631\u062A\u064A\u0646.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0642\u0627\u0631\u0627\u062A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0636\u064A\u0642 \u0627\u0644\u0645\u0627\u0626\u064A \u0627\u0644\u0636\u064A\u0642 \u0627\u0644\u0630\u064A \u064A\u0641\u0635\u0644 \u0628\u064A\u0646 \u0642\u0627\u0631\u0629 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0634\u0628\u0647 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0625\u064A\u0628\u064A\u0631\u064A\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629\u061F", correctAnswer: "\u0645\u0636\u064A\u0642 \u062C\u0628\u0644 \u0637\u0627\u0631\u0642 (Strait of Gibraltar)", explanation: "\u064A\u0631\u0628\u0637 \u0645\u0636\u064A\u0642 \u062C\u0628\u0644 \u0637\u0627\u0631\u0642 \u0628\u064A\u0646 \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0623\u0628\u064A\u0636 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0648\u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0623\u0637\u0644\u0633\u064A.", source: "\u0627\u0644\u0645\u0645\u0631\u0627\u062A \u0627\u0644\u0645\u0627\u0626\u064A\u0629 \u0627\u0644\u062F\u0648\u0644\u064A\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0645\u0642 \u0646\u0642\u0637\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0641\u064A \u0642\u064A\u0639\u0627\u0646 \u0645\u062D\u064A\u0637\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062A\u0642\u0639 \u0641\u064A \u062E\u0646\u062F\u0642 \u0645\u0627\u0631\u064A\u0627\u0646\u0627\u061F", correctAnswer: "\u062A\u0634\u0627\u0644\u0646\u062C\u0631 \u062F\u064A\u0628 (Challenger Deep) \u0628\u0639\u0645\u0642 \u0646\u062D\u0648 11,000 \u0645\u062A\u0631", explanation: "\u064A\u0635\u0644 \u0639\u0645\u0642 \u0646\u0642\u0637\u0629 \u062A\u0634\u0627\u0644\u0646\u062C\u0631 \u062F\u064A\u0628 \u0641\u064A \u062E\u0646\u062F\u0642 \u0645\u0627\u0631\u064A\u0627\u0646\u0627 \u0628\u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0644\u0646\u062D\u0648 10,928 \u0645\u062A\u0631\u0627\u064B \u062A\u062D\u062A \u0627\u0644\u0645\u0627\u0621.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0623\u0639\u0645\u0627\u0642 \u0648\u0627\u0644\u0645\u062D\u064A\u0637\u0627\u062A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0637\u0648\u0644 \u0633\u0644\u0633\u0644\u0629 \u062C\u0628\u0627\u0644 \u0642\u0627\u0631\u064A\u0629 \u0645\u062A\u0635\u0644\u0629 \u0641\u0648\u0642 \u0633\u0637\u062D \u0627\u0644\u0623\u0631\u0636 \u0648\u062A\u0645\u062A\u062F \u0641\u064A \u063A\u0631\u0628 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629\u061F", correctAnswer: "\u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0646\u062F\u064A\u0632 (Andes)", explanation: "\u062A\u0645\u062A\u062F \u062C\u0628\u0627\u0644 \u0627\u0644\u0623\u0646\u062F\u064A\u0632 \u0644\u0623\u0643\u062B\u0631 \u0645\u0646 7000 \u0643\u064A\u0644\u0648\u0645\u062A\u0631 \u0639\u0628\u0631 7 \u062F\u0648\u0644 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629.", source: "\u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0627 \u0648\u0627\u0644\u062A\u0636\u0627\u0631\u064A\u0633 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0644\u0649 \u0634\u0644\u0627\u0644\u0627\u062A \u0645\u064A\u0627\u0647 \u0637\u0628\u064A\u0639\u064A\u0629 \u0645\u062A\u0633\u0627\u0642\u0637\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062A\u0642\u0639 \u0641\u064A \u0641\u0646\u0632\u0648\u064A\u0644\u0627\u061F", correctAnswer: "\u0634\u0644\u0627\u0644\u0627\u062A \u0622\u0646\u062C\u0644 (Angel Falls)", explanation: "\u062A\u0633\u0642\u0637 \u0645\u064A\u0627\u0647 \u0634\u0644\u0627\u0644\u0627\u062A \u0622\u0646\u062C\u0644 \u0645\u0646 \u062C\u0628\u0644 \u0623\u064A\u0648\u064A\u0627\u0646\u062A\u064A\u0628\u0648\u064A \u0628\u0627\u0631\u062A\u0641\u0627\u0639 979 \u0645\u062A\u0631\u0627\u064B \u062F\u0648\u0646 \u0627\u0646\u0642\u0637\u0627\u0639.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0645\u0642 \u0628\u062D\u064A\u0631\u0629 \u0645\u064A\u0627\u0647 \u0639\u0630\u0628\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u062E\u0645\u0633 \u0645\u064A\u0627\u0647 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0639\u0630\u0628\u0629 \u063A\u064A\u0631 \u0627\u0644\u0645\u062A\u062C\u0645\u062F\u0629\u061F", correctAnswer: "\u0628\u062D\u064A\u0631\u0629 \u0628\u0627\u064A\u0643\u0627\u0644 \u0641\u064A \u0631\u0648\u0633\u064A\u0627 (Lake Baikal)", explanation: "\u064A\u0635\u0644 \u0639\u0645\u0642 \u0628\u062D\u064A\u0631\u0629 \u0628\u0627\u064A\u0643\u0627\u0644 \u0641\u064A \u0633\u064A\u0628\u064A\u0631\u064A\u0627 \u0625\u0644\u0649 1642 \u0645\u062A\u0631\u0627\u064B \u0648\u062A\u0639\u062F \u0623\u0642\u062F\u0645 \u0628\u062D\u064A\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0627\u0644\u0647\u064A\u062F\u0631\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0639\u0630\u0628\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u062E\u0637 \u0627\u0644\u0637\u0648\u0644 \u0627\u0644\u0648\u0647\u0645\u064A \u0627\u0644\u0630\u064A \u064A\u0645\u062B\u0644 \u062E\u0637 \u0627\u0644\u0632\u0648\u0627\u0644 \u0627\u0644\u0635\u0641\u0631\u064A \u0648\u062A\u064F\u062D\u0633\u0628 \u0627\u0644\u062A\u0648\u0642\u064A\u062A\u0627\u062A \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0625\u0644\u064A\u0647\u061F", correctAnswer: "\u062E\u0637 \u063A\u0631\u064A\u0646\u062A\u0634 (Prime Meridian)", explanation: "\u064A\u0645\u0631 \u062E\u0637 \u063A\u0631\u064A\u0646\u062A\u0634 \u0628\u0645\u0631\u0635\u062F \u063A\u0631\u064A\u0646\u062A\u0634 \u0627\u0644\u0645\u0644\u0643\u064A \u0641\u064A \u0644\u0646\u062F\u0646 \u0648\u064A\u0642\u0633\u0645 \u0627\u0644\u0623\u0631\u0636 \u0644\u0634\u0631\u0642 \u0648\u063A\u0631\u0628.", source: "\u0639\u0644\u0645 \u0627\u0644\u0641\u0644\u0643 \u0648\u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u062C\u0632\u064A\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0645\u0646 \u062D\u064A\u062B \u0627\u0644\u0645\u0633\u0627\u062D\u0629 \u0648\u0644\u0627 \u062A\u064F\u0639\u062A\u0628\u0631 \u0642\u0627\u0631\u0629 \u0628\u062D\u062F \u0630\u0627\u062A\u0647\u0627\u061F", correctAnswer: "\u062C\u0632\u064A\u0631\u0629 \u063A\u0631\u064A\u0644\u0627\u0646\u062F (Greenland)", explanation: "\u062A\u0628\u0644\u063A \u0645\u0633\u0627\u062D\u0629 \u063A\u0631\u064A\u0646\u0644\u0627\u0646\u062F \u0623\u0643\u062B\u0631 \u0645\u0646 2.16 \u0645\u0644\u064A\u0648\u0646 \u0643\u0645\xB2 \u0648\u062A\u062A\u0628\u0639 \u0644\u0644\u062F\u0646\u0645\u0627\u0631\u0643 \u0630\u0627\u062A\u064A\u0627\u064B.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u062C\u0632\u0631 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0635\u062D\u0631\u0627\u0621 \u063A\u064A\u0631 \u0627\u0644\u0642\u0637\u0628\u064A\u0629 \u0627\u0644\u0623\u0643\u062B\u0631 \u062C\u0641\u0627\u0641\u0627\u064B \u0648\u0642\u062D\u0637\u0627\u064B \u0639\u0644\u0649 \u0648\u062C\u0647 \u0627\u0644\u0623\u0631\u0636 \u0641\u064A \u0634\u0645\u0627\u0644 \u062A\u0634\u064A\u0644\u064A\u061F", correctAnswer: "\u0635\u062D\u0631\u0627\u0621 \u0623\u062A\u0627\u0643\u0627\u0645\u0627 (Atacama Desert)", explanation: "\u062A\u0633\u062C\u0644 \u0635\u062D\u0631\u0627\u0621 \u0623\u062A\u0627\u0643\u0627\u0645\u0627 \u0623\u0642\u0644 \u0645\u0639\u062F\u0644 \u0647\u0637\u0648\u0644 \u0623\u0645\u0637\u0627\u0631 \u0648\u0628\u0639\u0636 \u0645\u0646\u0627\u0637\u0642\u0647\u0627 \u0644\u0645 \u064A\u0634\u0647\u062F \u0642\u0637\u0631\u0629 \u0645\u0637\u0631 \u0644\u0645\u0626\u0627\u062A \u0627\u0644\u0633\u0646\u064A\u0646.", source: "\u0627\u0644\u0645\u0646\u0627\u062E \u0627\u0644\u0639\u0627\u0644\u0645\u064A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0636\u064A\u0642 \u0627\u0644\u0645\u0627\u0626\u064A \u0627\u0644\u0630\u064A \u064A\u0641\u0635\u0644 \u0628\u064A\u0646 \u0623\u0642\u0635\u0649 \u0634\u0631\u0642 \u0642\u0627\u0631\u0629 \u0622\u0633\u064A\u0627 (\u0631\u0648\u0633\u064A\u0627) \u0648\u0623\u0642\u0635\u0649 \u063A\u0631\u0628 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629 (\u0623\u0644\u0627\u0633\u0643\u0627)\u061F", correctAnswer: "\u0645\u0636\u064A\u0642 \u0628\u064A\u0631\u0646\u063A (Bering Strait)", explanation: "\u064A\u0628\u0644\u063A \u0639\u0631\u0636 \u0645\u0636\u064A\u0642 \u0628\u064A\u0631\u0646\u063A \u062D\u0648\u0627\u0644\u064A 82 \u0643\u064A\u0644\u0648\u0645\u062A\u0631\u0627\u064B \u0641\u064A \u0623\u0636\u064A\u0642 \u0646\u0642\u0627\u0637\u0647 \u0648\u064A\u0631\u0628\u0637 \u0628\u064A\u0646 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0645\u062A\u062C\u0645\u062F \u0627\u0644\u0647\u0627\u062F\u0626 \u0648\u0627\u0644\u0634\u0645\u0627\u0644\u064A.", source: "\u0627\u0644\u0645\u0645\u0631\u0627\u062A \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u0628\u062D\u064A\u0631\u0629 \u0645\u0646 \u062D\u064A\u062B \u0627\u0644\u0645\u0633\u0627\u062D\u0629 \u0641\u064A \u0642\u0627\u0631\u0629 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0645\u0646\u0628\u0639 \u0627\u0644\u0646\u064A\u0644 \u0627\u0644\u0623\u0628\u064A\u0636 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u061F", correctAnswer: "\u0628\u062D\u064A\u0631\u0629 \u0641\u064A\u0643\u062A\u0648\u0631\u064A\u0627", explanation: "\u062A\u062A\u0642\u0627\u0633\u0645 \u0643\u064A\u0646\u064A\u0627 \u0648\u062A\u0646\u0632\u0627\u0646\u064A\u0627 \u0648\u0623\u0648\u063A\u0646\u062F\u0627 \u0628\u062D\u064A\u0631\u0629 \u0641\u064A\u0643\u062A\u0648\u0631\u064A\u0627 \u0627\u0644\u062A\u064A \u062A\u0639\u062F \u0623\u0643\u0628\u0631 \u0628\u062D\u064A\u0631\u0629 \u0627\u0633\u062A\u0648\u0627\u0626\u064A\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0623\u0637\u0644\u0633 \u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0625\u0641\u0631\u064A\u0642\u064A\u0627" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0645\u0646\u0627\u062E\u064A\u0629 \u0627\u0644\u062F\u0648\u0631\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0624\u062F\u064A \u0644\u062F\u0641\u0621 \u063A\u064A\u0631 \u0645\u0639\u062A\u0627\u062F \u0641\u064A \u0645\u064A\u0627\u0647 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0626\u064A \u0648\u062A\u063A\u064A\u0631 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u0637\u0642\u0633 \u0639\u0627\u0644\u0645\u064A\u0627\u064B\u061F", correctAnswer: "\u0638\u0627\u0647\u0631\u0629 \u0625\u0644 \u0646\u064A\u0646\u064A\u0648 (El Ni\xF1o)", explanation: "\u0625\u0644 \u0646\u064A\u0646\u064A\u0648 \u0647\u064A \u0638\u0627\u0647\u0631\u0629 \u062A\u0642\u0644\u0628 \u0645\u0646\u0627\u062E\u064A \u062A\u0631\u062A\u0628\u0637 \u0628\u0627\u0631\u062A\u0641\u0627\u0639 \u062F\u0631\u062C\u0627\u062A \u062D\u0631\u0627\u0631\u0629 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631 \u0641\u064A \u0634\u0631\u0642 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626.", source: "\u0627\u0644\u0645\u0646\u0638\u0645\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0644\u0644\u0623\u0631\u0635\u0627\u062F \u0627\u0644\u062C\u0648\u064A\u0629 WMO" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0628\u0631\u0643\u0627\u0646 \u0627\u0644\u0630\u064A \u064A\u064F\u0639\u062F \u0627\u0644\u0623\u0628\u0639\u062F \u0642\u0645\u0629 \u0639\u0646 \u0645\u0631\u0643\u0632 \u0643\u0648\u0643\u0628 \u0627\u0644\u0623\u0631\u0636 \u0628\u0633\u0628\u0628 \u0627\u0644\u062A\u062D\u062F\u0628 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0626\u064A \u0644\u0644\u0623\u0631\u0636\u061F", correctAnswer: "\u0628\u0631\u0643\u0627\u0646 \u0634\u064A\u0645\u0628\u0648\u0631\u0627\u0632\u0648 \u0641\u064A \u0627\u0644\u0625\u0643\u0648\u0627\u062F\u0648\u0631 (Chimborazo)", explanation: "\u0646\u0638\u0631\u0627\u064B \u0644\u0623\u0646 \u0627\u0644\u0623\u0631\u0636 \u0628\u064A\u0636\u0627\u0648\u064A\u0629 \u0648\u062A\u0646\u062A\u0641\u062E \u0639\u0646\u062F \u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621\u060C \u0641\u0625\u0646 \u0642\u0645\u0629 \u0634\u064A\u0645\u0628\u0648\u0631\u0627\u0632\u0648 \u0647\u064A \u0623\u0642\u0631\u0628 \u0646\u0642\u0637\u0629 \u0639\u0644\u0649 \u0633\u0637\u062D \u0627\u0644\u0623\u0631\u0636 \u0644\u0644\u0642\u0645\u0631 \u0648\u0627\u0644\u0634\u0645\u0633.", source: "\u0627\u0644\u062C\u064A\u0648\u062F\u064A\u0633\u064A\u0627 \u0648\u0627\u0644\u0645\u0633\u062D \u0627\u0644\u0641\u0636\u0627\u0626\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0636\u0645 \u0623\u0643\u0628\u0631 \u0639\u062F\u062F \u0645\u0646 \u0627\u0644\u062C\u0632\u0631 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0628\u0623\u0643\u062B\u0631 \u0645\u0646 260,000 \u062C\u0632\u064A\u0631\u0629\u061F", correctAnswer: "\u0627\u0644\u0633\u0648\u064A\u062F", explanation: "\u062A\u0645\u062A\u0644\u0643 \u0627\u0644\u0633\u0648\u064A\u062F \u0646\u062D\u0648 267,570 \u062C\u0632\u064A\u0631\u0629 \u0645\u0639\u0638\u0645\u0647\u0627 \u063A\u064A\u0631 \u0645\u0623\u0647\u0648\u0644 \u062A\u0644\u064A\u0647\u0627 \u0627\u0644\u0646\u0631\u0648\u064A\u062C \u0648\u0641\u0646\u0644\u0646\u062F\u0627.", source: "\u0625\u062D\u0635\u0627\u0621\u0627\u062A \u0627\u0644\u062C\u0632\u0631 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u062C\u0644 \u0623\u0639\u0644\u0649 \u062F\u0631\u062C\u0629 \u062D\u0631\u0627\u0631\u0629 \u0644\u0633\u0637\u062D \u0627\u0644\u0623\u0631\u0636 \u0631\u0633\u0645\u064A\u0627\u064B \u0628\u062D\u0633\u0628 \u0642\u064A\u0627\u0633\u0627\u062A \u0627\u0644\u0623\u0642\u0645\u0627\u0631 \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629 \u0644\u0646\u0627\u0633\u0627 \u0641\u064A \u0635\u062D\u0631\u0627\u0621 \u0644\u0648\u062A\u061F", correctAnswer: "\u0635\u062D\u0631\u0627\u0621 \u0644\u0648\u062A \u0641\u064A \u0625\u064A\u0631\u0627\u0646 (\u0633\u062C\u0644\u062A \u0623\u0643\u062B\u0631 \u0645\u0646 70 \u062F\u0631\u062C\u0629 \u0645\u0626\u0648\u064A\u0629 \u0644\u0644\u0633\u0637\u062D)", explanation: "\u0633\u062C\u0644\u062A \u0635\u062D\u0631\u0627\u0621 \u0644\u0648\u062A \u0623\u0639\u0644\u0649 \u062D\u0631\u0627\u0631\u0629 \u0625\u0634\u0639\u0627\u0639\u064A\u0629 \u0644\u0633\u0637\u062D \u0627\u0644\u0623\u0631\u0636 \u0639\u0628\u0631 \u062D\u0633\u0627\u0633\u0627\u062A \u0645\u0648\u062F\u064A\u0633 \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u0646\u0627\u0633\u0627.", source: "\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0643\u0627\u0644\u0629 \u0646\u0627\u0633\u0627 \u0644\u0644\u0623\u0642\u0645\u0627\u0631 \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0623\u0643\u0628\u0631 \u062D\u0648\u0636 \u062A\u0635\u0631\u064A\u0641 \u0646\u0647\u0631\u064A \u0645\u063A\u0644\u0642 (\u062F\u0627\u062E\u0644\u064A \u0644\u0627 \u064A\u0635\u0628 \u0641\u064A \u0623\u064A \u0645\u062D\u064A\u0637) \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u062D\u0648\u0636 \u0628\u062D\u0631 \u0642\u0632\u0648\u064A\u0646 \u0648\u0646\u0647\u0631 \u0627\u0644\u0641\u0648\u0644\u063A\u0627", explanation: "\u064A\u0635\u0631\u0641 \u062D\u0648\u0636 \u0628\u062D\u0631 \u0642\u0632\u0648\u064A\u0646 \u0645\u064A\u0627\u0647\u0647 \u062F\u0627\u062E\u0644\u064A\u0627\u064B \u062F\u0648\u0646 \u0623\u064A \u0627\u062A\u0635\u0627\u0644 \u0647\u064A\u062F\u0631\u0648\u0644\u0648\u062C\u064A \u0645\u0641\u062A\u0648\u062D \u0628\u0627\u0644\u0645\u062D\u064A\u0637\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629.", source: "\u0627\u0644\u0647\u064A\u062F\u0631\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0642\u0627\u0631\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u0623\u0637\u0648\u0644 \u0648\u0627\u062F\u064D \u0645\u062A\u0635\u062F\u0639 \u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0627\u064B \u0639\u0644\u0649 \u0627\u0644\u064A\u0627\u0628\u0633\u0629 \u064A\u0645\u062A\u062F \u0645\u0646 \u0634\u0645\u0627\u0644 \u0628\u0644\u0627\u062F \u0627\u0644\u0634\u0627\u0645 \u062D\u062A\u0649 \u0645\u0648\u0632\u0645\u0628\u064A\u0642\u061F", correctAnswer: "\u0627\u0644\u0648\u0627\u062F\u064A \u0627\u0644\u0645\u062A\u0635\u062F\u0639 \u0627\u0644\u0643\u0628\u064A\u0631 (\u0627\u0644\u0623\u062E\u062F\u0648\u062F \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A \u0627\u0644\u0639\u0638\u064A\u0645 / Great Rift Valley)", explanation: "\u064A\u0645\u062A\u062F \u0627\u0644\u0623\u062E\u062F\u0648\u062F \u0644\u0623\u0643\u062B\u0631 \u0645\u0646 6000 \u0643\u0645 \u0646\u0627\u062A\u062C\u0627\u064B \u0639\u0646 \u062A\u0628\u0627\u0639\u062F \u0627\u0644\u0635\u0641\u0627\u0626\u062D \u0627\u0644\u062A\u0643\u062A\u0648\u0646\u064A\u0629 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u0648\u0627\u0644\u0639\u0631\u0628\u064A\u0629.", source: "\u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0628\u0646\u064A\u0648\u064A\u0629" }
      ],
      "\u0627\u0644\u0639\u0631\u0628": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0641\u064A \u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u061F", correctAnswer: "22 \u062F\u0648\u0644\u0629", explanation: "\u062A\u0636\u0645 \u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 22 \u062F\u0648\u0644\u0629 \u062A\u0645\u062A\u062F \u0645\u0646 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0623\u0637\u0644\u0633\u064A \u063A\u0631\u0628\u0627\u064B \u0625\u0644\u0649 \u0628\u062D\u0631 \u0627\u0644\u0639\u0631\u0628 \u0634\u0631\u0642\u0627\u064B.", source: "\u0645\u064A\u062B\u0627\u0642 \u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0648\u0627\u0644\u0645\u0631\u0643\u0632 \u0627\u0644\u062D\u0636\u0627\u0631\u064A \u0627\u0644\u0630\u064A \u062A\u0623\u0633\u0633\u062A \u0641\u064A\u0647 \u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0639\u0627\u0645 1945\u061F", correctAnswer: "\u0627\u0644\u0642\u0627\u0647\u0631\u0629", explanation: "\u062A\u0623\u0633\u0633\u062A \u0627\u0644\u062C\u0627\u0645\u0639\u0629 \u0641\u064A \u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0641\u064A \u0645\u0627\u0631\u0633 1945 \u0648\u062A\u0636\u0645 \u0645\u0642\u0631 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0627\u0644\u062F\u0627\u0626\u0645.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u062F\u0648\u0644\u0629 \u0639\u0631\u0628\u064A\u0629 \u0645\u0646 \u062D\u064A\u062B \u0627\u0644\u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u062C\u0632\u0627\u0626\u0631", explanation: "\u062A\u0628\u0644\u063A \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u062C\u0632\u0627\u0626\u0631 \u0646\u062D\u0648 2.38 \u0645\u0644\u064A\u0648\u0646 \u0643\u0645\xB2 \u0644\u062A\u0635\u0628\u062D \u0627\u0644\u0623\u0648\u0644\u0649 \u0639\u0631\u0628\u064A\u0627\u064B \u0648\u0625\u0641\u0631\u064A\u0642\u064A\u0627\u064B.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0639\u0631\u0628\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u062B\u0631 \u062F\u0648\u0644\u0629 \u0639\u0631\u0628\u064A\u0629 \u0645\u0646 \u062D\u064A\u062B \u0639\u062F\u062F \u0627\u0644\u0633\u0643\u0627\u0646\u061F", correctAnswer: "\u0645\u0635\u0631", explanation: "\u064A\u062A\u062C\u0627\u0648\u0632 \u0639\u062F\u062F \u0633\u0643\u0627\u0646 \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0645\u0635\u0631 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 105 \u0645\u0644\u0627\u064A\u064A\u0646 \u0646\u0633\u0645\u0629.", source: "\u0627\u0644\u062C\u0647\u0627\u0632 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0644\u0644\u062A\u0639\u0628\u0626\u0629 \u0648\u0627\u0644\u0625\u062D\u0635\u0627\u0621" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0623\u0645\u0648\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0641\u064A \u0628\u0644\u0627\u062F \u0627\u0644\u0634\u0627\u0645\u061F", correctAnswer: "\u062F\u0645\u0634\u0642", explanation: "\u0643\u0627\u0646\u062A \u062F\u0645\u0634\u0642 \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u062E\u0644\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0648\u064A\u0629 \u0648\u0642\u0627\u0639\u062F\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0627\u0644\u0641\u062A\u0648\u062D\u0627\u062A \u063A\u0631\u0628\u0627\u064B \u0648\u0634\u0631\u0642\u0627\u064B.", source: "\u062A\u0627\u0631\u064A\u062E \u062F\u0645\u0634\u0642 \u0644\u0627\u0628\u0646 \u0639\u0633\u0627\u0643\u0631" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0639\u0628\u0627\u0633\u064A\u0629 \u0627\u0644\u062A\u064A \u0628\u0646\u0627\u0647\u0627 \u0627\u0644\u062E\u0644\u064A\u0641\u0629 \u0623\u0628\u0648 \u062C\u0639\u0641\u0631 \u0627\u0644\u0645\u0646\u0635\u0648\u0631 \u0648\u062A\u0644\u0642\u0628 \u0628\u062F\u0627\u0631 \u0627\u0644\u0633\u0644\u0627\u0645\u061F", correctAnswer: "\u0628\u063A\u062F\u0627\u062F (\u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0645\u062F\u0648\u0631\u0629)", explanation: "\u0628\u0646\u0649 \u0627\u0644\u0645\u0646\u0635\u0648\u0631 \u0628\u063A\u062F\u0627\u062F \u0639\u0627\u0645 762\u0645 \u0639\u0644\u0649 \u0646\u0647\u0631 \u062F\u062C\u0644\u0629 \u0644\u062A\u0635\u0628\u062D \u0645\u0646\u0627\u0631\u0629 \u0627\u0644\u0639\u0644\u0648\u0645 \u0648\u0627\u0644\u062D\u0636\u0627\u0631\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0628\u063A\u062F\u0627\u062F \u0644\u0644\u062E\u0637\u064A\u0628 \u0627\u0644\u0628\u063A\u062F\u0627\u062F\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0623\u062B\u0631\u064A\u0629 \u0627\u0644\u0635\u062E\u0631\u064A\u0629 \u0627\u0644\u0645\u0646\u062D\u0648\u062A\u0629 \u0641\u064A \u062C\u0646\u0648\u0628 \u0627\u0644\u0623\u0631\u062F\u0646 \u0648\u062A\u0639\u062F \u0645\u0646 \u0639\u062C\u0627\u0626\u0628 \u0627\u0644\u062F\u0646\u064A\u0627 \u0627\u0644\u0633\u0628\u0639 \u0627\u0644\u062C\u062F\u064A\u062F\u0629\u061F", correctAnswer: "\u0627\u0644\u0628\u062A\u0631\u0627\u0621 (\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0623\u0646\u0628\u0627\u0637 \u0627\u0644\u0648\u0631\u062F\u064A\u0629)", explanation: "\u0646\u062D\u062A \u0627\u0644\u0623\u0646\u0628\u0627\u0637 \u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0628\u062A\u0631\u0627\u0621 \u0641\u064A \u0635\u062E\u0648\u0631 \u0648\u0627\u062F\u064A \u0645\u0648\u0633\u0649 \u0627\u0644\u0648\u0631\u062F\u064A\u0629 \u0648\u0627\u0632\u062F\u0647\u0631\u062A \u0643\u0639\u0627\u0635\u0645\u0629 \u062A\u062C\u0627\u0631\u064A\u0629.", source: "\u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648 \u0644\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u0639\u0627\u0644\u0645\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0631\u062D\u0627\u0644\u0629 \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0634\u0647\u064A\u0631 \u0627\u0644\u0645\u0648\u0644\u0648\u062F \u0641\u064A \u0637\u0646\u062C\u0629 \u0648\u0644\u0642\u0628 \u0628\u0623\u0645\u064A\u0631 \u0627\u0644\u0631\u062D\u0627\u0644\u064A\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064A\u0646\u061F", correctAnswer: "\u0627\u0628\u0646 \u0628\u0637\u0648\u0637\u0629", explanation: "\u0637\u0627\u0641 \u0627\u0628\u0646 \u0628\u0637\u0648\u0637\u0629 \u0623\u0631\u062C\u0627\u0621 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u0648\u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0627\u0644\u0635\u064A\u0646 \u0648\u062F\u0648\u0651\u0646 \u0631\u062D\u0644\u062A\u0647 \xAB\u062A\u062D\u0641\u0629 \u0627\u0644\u0646\u0638\u0627\u0631\xBB.", source: "\u0631\u062D\u0644\u0629 \u0627\u0628\u0646 \u0628\u0637\u0648\u0637\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0636\u064A\u0642 \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A \u0627\u0644\u0630\u064A \u064A\u0631\u0628\u0637 \u0628\u064A\u0646 \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0623\u062D\u0645\u0631 \u0648\u062E\u0644\u064A\u062C \u0639\u062F\u0646\u061F", correctAnswer: "\u0645\u0636\u064A\u0642 \u0628\u0627\u0628 \u0627\u0644\u0645\u0646\u062F\u0628", explanation: "\u064A\u0641\u0635\u0644 \u0628\u0627\u0628 \u0627\u0644\u0645\u0646\u062F\u0628 \u0628\u064A\u0646 \u0634\u0628\u0647 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A \u0648\u064A\u062A\u062D\u0643\u0645 \u0641\u064A \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0625\u0644\u0649 \u0642\u0646\u0627\u0629 \u0627\u0644\u0633\u0648\u064A\u0633.", source: "\u0627\u0644\u0645\u0645\u0631\u0627\u062A \u0627\u0644\u0645\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062C\u0646\u0648\u0628 \u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0646\u062F\u064A\u061F", correctAnswer: "\u062C\u0632\u0631 \u0642\u0645\u0631 (\u0627\u0644\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u0642\u0645\u0631\u064A)", explanation: "\u062A\u0642\u0639 \u062C\u0632\u0631 \u0627\u0644\u0642\u0645\u0631 \u0641\u064A \u0642\u0646\u0627\u0629 \u0645\u0648\u0632\u0645\u0628\u064A\u0642 \u0628\u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0646\u062F\u064A \u062C\u0646\u0648\u0628 \u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0642\u0627\u0626\u062F \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0645\u0633\u0644\u0645 \u0627\u0644\u0630\u064A \u0641\u062A\u062D \u0628\u0644\u0627\u062F \u0627\u0644\u0623\u0646\u062F\u0644\u0633 \u0639\u0627\u0645 711\u0645 \u0648\u0633\u0645\u064A \u0627\u0644\u062C\u0628\u0644 \u0628\u0627\u0633\u0645\u0647\u061F", correctAnswer: "\u0637\u0627\u0631\u0642 \u0628\u0646 \u0632\u064A\u0627\u062F", explanation: "\u0639\u0628\u0631 \u0637\u0627\u0631\u0642 \u0628\u0646 \u0632\u064A\u0627\u062F \u0627\u0644\u0645\u0636\u064A\u0642 \u0628\u062C\u064A\u0634\u0647 \u0644\u062A\u0628\u062F\u0623 \u0627\u0644\u062D\u0636\u0627\u0631\u0629 \u0627\u0644\u0623\u0646\u062F\u0644\u0633\u064A\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629 \u0627\u0644\u062A\u064A \u062F\u0627\u0645\u062A \u0642\u0631\u0627\u0628\u0629 \u062B\u0645\u0627\u0646\u064A\u0629 \u0642\u0631\u0648\u0646.", source: "\u0646\u0641\u062D \u0627\u0644\u0637\u064A\u0628 \u0644\u0644\u0645\u0642\u0631\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u064A\u0631\u0645\u0648\u0643 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0648\u0642\u0639\u062A \u0639\u0627\u0645 636\u0645 \u0628\u0642\u064A\u0627\u062F\u0629 \u062E\u0627\u0644\u062F \u0628\u0646 \u0627\u0644\u0648\u0644\u064A\u062F \u0648\u0623\u0646\u0647\u062A \u0627\u0644\u0648\u062C\u0648\u062F \u0627\u0644\u0628\u064A\u0632\u0646\u0637\u064A \u0641\u064A \u0627\u0644\u0634\u0627\u0645\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u064A\u0631\u0645\u0648\u0643", explanation: "\u062D\u0633\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0628\u0642\u064A\u0627\u062F\u0629 \u0633\u064A\u0641 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0633\u0644\u0648\u0644 \u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u064A\u0631\u0645\u0648\u0643 \u0644\u0641\u062A\u062D \u0643\u0627\u0645\u0644 \u0628\u0644\u0627\u062F \u0627\u0644\u0634\u0627\u0645.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0631\u0633\u0644 \u0648\u0627\u0644\u0645\u0644\u0648\u0643 \u0644\u0644\u0637\u0628\u0631\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0642\u062F\u0645 \u062C\u0627\u0645\u0639\u0629 \u0639\u0627\u0645\u0644\u0629 \u0648\u0645\u0633\u062A\u0645\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u062D\u062A\u0649 \u0627\u0644\u064A\u0648\u0645 \u0628\u062D\u0633\u0628 \u063A\u064A\u0646\u064A\u0633 \u0648\u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648 \u0648\u062A\u0642\u0639 \u0641\u064A \u0641\u0627\u0633 \u0628\u0627\u0644\u0645\u063A\u0631\u0628\u061F", correctAnswer: "\u062C\u0627\u0645\u0639\u0629 \u0627\u0644\u0642\u0631\u0648\u064A\u064A\u0646", explanation: "\u0623\u0633\u0633\u062A\u0647\u0627 \u0627\u0644\u0633\u064A\u062F\u0629 \u0641\u0627\u0637\u0645\u0629 \u0627\u0644\u0641\u0647\u0631\u064A\u0629 \u0639\u0627\u0645 859\u0645 \u0641\u064A \u0645\u062F\u064A\u0646\u0629 \u0641\u0627\u0633 \u0627\u0644\u0645\u063A\u0631\u0628\u064A\u0629.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u063A\u064A\u0646\u064A\u0633 \u0644\u0644\u064A\u0648\u0646\u0633\u0643\u0648" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0641\u064A\u0644\u0633\u0648\u0641 \u0648\u0627\u0644\u0645\u0624\u0631\u062E \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0623\u0646\u062F\u0644\u0633\u064A \u0648\u0627\u0644\u062A\u0648\u0646\u0633\u064A \u0627\u0644\u0623\u0635\u0644 \u0648\u0645\u0624\u0633\u0633 \u0639\u0644\u0645 \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639 \u0648\u0641\u0644\u0633\u0641\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0648\u0635\u0627\u062D\u0628 \xAB\u0627\u0644\u0645\u0642\u062F\u0645\u0629\xBB\u061F", correctAnswer: "\u0639\u0628\u062F \u0627\u0644\u0631\u062D\u0645\u0646 \u0628\u0646 \u062E\u0644\u062F\u0648\u0646", explanation: "\u0648\u0636\u0639 \u0627\u0628\u0646 \u062E\u0644\u062F\u0648\u0646 \u0641\u064A \u0645\u0642\u062F\u0645\u062A\u0647 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0623\u0633\u0633 \u0639\u0644\u0645 \u0627\u0644\u0639\u0645\u0631\u0627\u0646 \u0627\u0644\u0628\u0634\u0631\u064A \u0648\u0642\u0648\u0627\u0646\u064A\u0646 \u062A\u0637\u0648\u0631 \u0627\u0644\u062F\u0648\u0644 \u0648\u0627\u0644\u0639\u0635\u0628\u064A\u0629.", source: "\u0645\u0642\u062F\u0645\u0629 \u0627\u0628\u0646 \u062E\u0644\u062F\u0648\u0646" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0648\u0644 \u0639\u0627\u0635\u0645\u0629 \u0625\u0633\u0644\u0627\u0645\u064A\u0629 \u0641\u064A \u0645\u0635\u0631 \u0628\u0646\u0627\u0647\u0627 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0628\u0639\u062F \u0627\u0644\u0641\u062A\u062D \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u061F", correctAnswer: "\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0641\u0633\u0637\u0627\u0637", explanation: "\u0628\u0646\u0649 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0627\u0644\u0641\u0633\u0637\u0627\u0637 \u0648\u0623\u0646\u0634\u0623 \u0628\u0647\u0627 \u0623\u0648\u0644 \u062C\u0627\u0645\u0639 \u0641\u064A \u0625\u0641\u0631\u064A\u0642\u064A\u0627 (\u062C\u0627\u0645\u0639 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635).", source: "\u0627\u0644\u062E\u0637\u0637 \u0627\u0644\u0645\u0642\u0631\u064A\u0632\u064A\u0629" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0644\u0627\u0644\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u062D\u0643\u0645\u062A \u0639\u0645\u0627\u0646 \u0648\u0632\u0646\u062C\u0628\u0627\u0631 \u0645\u0639\u0627\u064B \u0648\u062C\u0639\u0644\u062A \u0632\u0646\u062C\u0628\u0627\u0631 \u0639\u0627\u0635\u0645\u0629 \u0644\u0647\u0627 \u0641\u064A \u0639\u0647\u062F \u0627\u0644\u0633\u064A\u062F \u0633\u0639\u064A\u062F \u0628\u0646 \u0633\u0644\u0637\u0627\u0646\u061F", correctAnswer: "\u0633\u0644\u0627\u0644\u0629 \u0627\u0644\u0628\u0648\u0633\u0639\u064A\u062F (\u062F\u0648\u0644\u0629 \u0622\u0644 \u0628\u0648\u0633\u0639\u064A\u062F)", explanation: "\u0646\u0642\u0644 \u0627\u0644\u0633\u064A\u062F \u0633\u0639\u064A\u062F \u0628\u0646 \u0633\u0644\u0637\u0627\u0646 \u0639\u0627\u0635\u0645\u0629 \u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u064A\u062A\u0647 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0625\u0644\u0649 \u0632\u0646\u062C\u0628\u0627\u0631 \u0639\u0627\u0645 1840 \u0644\u0627\u0632\u062F\u0647\u0627\u0631 \u0627\u0644\u062A\u062C\u0627\u0631\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0639\u0645\u0627\u0646 \u0648\u0632\u0646\u062C\u0628\u0627\u0631" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0639\u0627\u0645 655\u0645 \u0627\u0644\u062A\u064A \u0627\u0646\u062A\u0635\u0631 \u0641\u064A\u0647\u0627 \u0627\u0644\u0623\u0633\u0637\u0648\u0644 \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u0637\u0648\u0644 \u0627\u0644\u0628\u064A\u0632\u0646\u0637\u064A\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0630\u0627\u062A \u0627\u0644\u0635\u0648\u0627\u0631\u064A", explanation: "\u0642\u0627\u062F \u0639\u0628\u062F \u0627\u0644\u0644\u0647 \u0628\u0646 \u0633\u0639\u062F \u0628\u0646 \u0623\u0628\u064A \u0627\u0644\u0633\u0631\u062D \u0627\u0644\u0623\u0633\u0637\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u0641\u064A \u0623\u0648\u0644 \u0645\u0639\u0631\u0643\u0629 \u0628\u062D\u0631\u064A\u0629 \u0643\u0628\u0631\u0649 \u0644\u0644\u0645\u0633\u0644\u0645\u064A\u0646.", source: "\u0627\u0644\u0628\u062F\u0627\u064A\u0629 \u0648\u0627\u0644\u0646\u0647\u0627\u064A\u0629 \u0644\u0627\u0628\u0646 \u0643\u062B\u064A\u0631" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0627\u0635\u0645\u0629 \u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u063A\u0633\u0627\u0633\u0646\u0629 \u0627\u0644\u0639\u0631\u0628 \u0641\u064A \u062C\u0646\u0648\u0628 \u0628\u0644\u0627\u062F \u0627\u0644\u0634\u0627\u0645 \u0642\u0628\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u061F", correctAnswer: "\u0627\u0644\u062C\u0627\u0628\u064A\u0629 (\u0641\u064A \u062D\u0648\u0631\u0627\u0646 / \u0627\u0644\u062C\u0648\u0644\u0627\u0646)", explanation: "\u0627\u062A\u062E\u0630 \u0627\u0644\u063A\u0633\u0627\u0633\u0646\u0629 \u0627\u0644\u062C\u0627\u0628\u064A\u0629 \u0639\u0627\u0635\u0645\u0629 \u0644\u062D\u0643\u0645\u0647\u0645 \u0648\u0623\u0642\u0627\u0645\u0648\u0627 \u0641\u064A\u0647\u0627 \u0642\u0635\u0648\u0631\u0647\u0645 \u0648\u0645\u062C\u0627\u0644\u0633\u0647\u0645.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0642\u062F\u064A\u0645" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0623\u0646\u0628\u0627\u0637 \u0648\u0639\u0627\u0635\u0645\u062A\u0647\u0645 \u0627\u0644\u062D\u062C\u0631 (\u0645\u062F\u0627\u0626\u0646 \u0635\u0627\u0644\u062D) \u0641\u064A \u0634\u0645\u0627\u0644 \u063A\u0631\u0628 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u061F", correctAnswer: "\u0645\u0645\u0644\u0643\u0629 \u062F\u0627\u062F\u0627\u0646 \u0648\u0644\u062D\u064A\u0627\u0646 \u062B\u0645 \u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0623\u0646\u0628\u0627\u0637 (\u0645\u062F\u0627\u0626\u0646 \u0635\u0627\u0644\u062D / \u0627\u0644\u062D\u062C\u0631)", explanation: "\u0627\u0644\u062D\u062C\u0631 \u0643\u0627\u0646\u062A \u0627\u0644\u0639\u0627\u0635\u0645\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0644\u0644\u0623\u0646\u0628\u0627\u0637 \u0648\u062A\u0639\u062A\u0628\u0631 \u0623\u0648\u0644 \u0645\u0648\u0642\u0639 \u0633\u0639\u0648\u062F\u064A \u064A\u0633\u062C\u0644 \u0641\u064A \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0622\u062B\u0627\u0631" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0639\u0628\u0627\u0633\u064A \u0627\u0644\u0630\u064A \u0627\u0628\u062A\u0643\u0631 \u0639\u0644\u0645 \u0627\u0644\u062C\u0628\u0631 \u0648\u0648\u0636\u0639 \u0646\u0638\u0627\u0645 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0635\u0641\u0631\u064A\u0629 \u0648\u0627\u0644\u062E\u0648\u0627\u0631\u0632\u0645\u064A\u0627\u062A\u061F", correctAnswer: "\u0645\u062D\u0645\u062F \u0628\u0646 \u0645\u0648\u0633\u0649 \u0627\u0644\u062E\u0648\u0627\u0631\u0632\u0645\u064A", explanation: "\u0623\u0644\u0641 \u0643\u062A\u0627\u0628 \xAB\u0627\u0644\u0645\u062E\u062A\u0635\u0631 \u0641\u064A \u062D\u0633\u0627\u0628 \u0627\u0644\u062C\u0628\u0631 \u0648\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629\xBB \u0641\u064A \u0628\u064A\u062A \u0627\u0644\u062D\u0643\u0645\u0629 \u0628\u0628\u063A\u062F\u0627\u062F \u0648\u0633\u0645\u064A\u062A \u0627\u0644\u062E\u0648\u0627\u0631\u0632\u0645\u064A\u0627\u062A \u0628\u0627\u0633\u0645\u0647.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0644\u0648\u0645 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u0641\u0627\u0635\u0644\u0629 \u0639\u0627\u0645 628\u0645 \u0628\u064A\u0646 \u0627\u0644\u0641\u0631\u0633 \u0648\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u062D\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0642\u0627\u0644 \u0641\u064A\u0647\u0627 \u0627\u0644\u0646\u0628\u064A \uFDFA: \xAB\u0647\u0630\u0627 \u0623\u0648\u0644 \u064A\u0648\u0645 \u0627\u0646\u062A\u0635\u0641\u062A \u0641\u064A\u0647 \u0627\u0644\u0639\u0631\u0628 \u0645\u0646 \u0627\u0644\u0639\u062C\u0645\xBB\u061F", correctAnswer: "\u064A\u0648\u0645 \u0630\u064A \u0642\u0627\u0631 (\u0645\u0639\u0631\u0643\u0629 \u0630\u064A \u0642\u0627\u0631)", explanation: "\u0627\u062A\u062D\u062F\u062A \u0642\u0628\u0627\u0626\u0644 \u0628\u0643\u0631 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0648\u0627\u0644\u0639\u0631\u0628 \u0648\u0647\u0632\u0645\u062A \u062C\u064A\u0634 \u0643\u0633\u0631\u0649 \u0648\u0627\u0644\u0641\u0631\u0633 \u0642\u0628\u0644 \u0638\u0647\u0648\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0628\u0642\u0644\u064A\u0644.", source: "\u0627\u0644\u0623\u063A\u0627\u0646\u064A \u0644\u0644\u0623\u0635\u0641\u0647\u0627\u0646\u064A \u0648\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0637\u0628\u0631\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0644\u0627\u0644\u0629 \u0627\u0644\u062D\u0627\u0643\u0645\u0629 \u0627\u0644\u062A\u064A \u0628\u0646\u062A \u0642\u0635\u0631 \u0627\u0644\u062D\u0645\u0631\u0627\u0621 \u0627\u0644\u0634\u0647\u064A\u0631 \u0641\u064A \u063A\u0631\u0646\u0627\u0637\u0629\u060C \u0622\u062E\u0631 \u0645\u0639\u0627\u0642\u0644 \u0627\u0644\u0645\u0633\u0644\u0645\u064A\u0646 \u0641\u064A \u0627\u0644\u0623\u0646\u062F\u0644\u0633\u061F", correctAnswer: "\u0628\u0646\u0648 \u0627\u0644\u0623\u062D\u0645\u0631 (\u0628\u0646\u0648 \u0646\u0635\u0631 / \u0627\u0644\u0646\u0635\u0631\u064A\u0648\u0646)", explanation: "\u062D\u0643\u0645 \u0627\u0644\u0646\u0635\u0631\u064A\u0648\u0646 \u0645\u0645\u0644\u0643\u0629 \u063A\u0631\u0646\u0627\u0637\u0629 \u0645\u0646 1238 \u062D\u062A\u0649 \u0633\u0642\u0648\u0637\u0647\u0627 \u0639\u0627\u0645 1492\u0645 \u0648\u0634\u064A\u062F\u0648\u0627 \u0642\u0635\u0631 \u0627\u0644\u062D\u0645\u0631\u0627\u0621 \u0627\u0644\u0628\u062F\u064A\u0639.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0623\u0646\u062F\u0644\u0633 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0642\u0627\u0626\u062F \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0630\u064A \u0623\u0633\u0633 \u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0642\u064A\u0631\u0648\u0627\u0646 \u0641\u064A \u062A\u0648\u0646\u0633 \u0639\u0627\u0645 50 \u0647\u0640 \u0648\u062C\u0639\u0644\u0647\u0627 \u0642\u0627\u0639\u062F\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0627\u0644\u0641\u062A\u0648\u062D\u0627\u062A \u0641\u064A \u0627\u0644\u0645\u063A\u0631\u0628\u061F", correctAnswer: "\u0639\u0642\u0628\u0629 \u0628\u0646 \u0646\u0627\u0641\u0639 \u0627\u0644\u0641\u0647\u0631\u064A", explanation: "\u062E\u0637 \u0639\u0642\u0628\u0629 \u0628\u0646 \u0646\u0627\u0641\u0639 \u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0642\u064A\u0631\u0648\u0627\u0646 \u0648\u0628\u0646\u0649 \u062C\u0627\u0645\u0639\u0647\u0627 \u0627\u0644\u0623\u0639\u0638\u0645 \u0644\u062A\u0643\u0648\u0646 \u0623\u0648\u0644 \u0639\u0627\u0635\u0645\u0629 \u0625\u0633\u0644\u0627\u0645\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u063A\u0631\u0628 \u0627\u0644\u0639\u0631\u0628\u064A.", source: "\u0627\u0644\u0628\u064A\u0627\u0646 \u0627\u0644\u0645\u063A\u0631\u0628 \u0644\u0627\u0628\u0646 \u0639\u0630\u0627\u0631\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0642\u062F\u064A\u0645 \u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0645\u0648\u0635\u0644 \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642 \u0642\u0628\u0644 \u0627\u0644\u0641\u062A\u062D \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u0648\u0644\u0645\u0627\u0630\u0627 \u0633\u0645\u064A\u062A \u0628\u0627\u0644\u0645\u0648\u0635\u0644\u061F", correctAnswer: "\u0627\u0644\u062D\u0635\u0646 \u0627\u0644\u0634\u0631\u0642\u064A (\u0627\u0644\u062D\u0635\u0646\u064A\u0646) \u0648\u0633\u064F\u0645\u064A\u062A \u0627\u0644\u0645\u0648\u0635\u0644 \u0644\u0623\u0646\u0647\u0627 \u0648\u0635\u0644\u062A \u0628\u064A\u0646 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0648\u0627\u0644\u0639\u0631\u0627\u0642 \u0648\u0627\u0644\u0634\u0627\u0645", explanation: "\u0623\u0637\u0644\u0642 \u0627\u0644\u0639\u0631\u0628 \u0639\u0644\u064A\u0647\u0627 \u0627\u0644\u0645\u0648\u0635\u0644 \u0644\u0623\u0646\u0647\u0627 \u0643\u0627\u0646\u062A \u0645\u0644\u062A\u0642\u0649 \u0648\u0645\u0641\u0631\u0642 \u0637\u0631\u0642 \u062A\u062C\u0627\u0631\u064A\u0629 \u062A\u0635\u0644 \u0628\u064A\u0646 \u0627\u0644\u0623\u0642\u0627\u0644\u064A\u0645 \u0627\u0644\u0645\u062C\u0627\u0648\u0631\u0629.", source: "\u0645\u0639\u062C\u0645 \u0627\u0644\u0628\u0644\u062F\u0627\u0646 \u0644\u064A\u0627\u0642\u0648\u062A \u0627\u0644\u062D\u0645\u0648\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0637\u0628\u064A\u0628 \u0648\u0627\u0644\u0635\u064A\u062F\u0644\u0627\u0646\u064A \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0645\u0644\u0642\u0628 \u0628\u0640 \xAB\u0623\u0645\u064A\u0631 \u0627\u0644\u0623\u0637\u0628\u0627\u0621\xBB \u0648\u0635\u0627\u062D\u0628 \u0643\u062A\u0627\u0628 \xAB\u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0641\u064A \u0627\u0644\u0637\u0628\xBB \u0627\u0644\u0630\u064A \u0638\u0644 \u0645\u0631\u062C\u0639\u0627\u064B \u0644\u0623\u0648\u0631\u0648\u0628\u0627 \u0644\u0642\u0631\u0648\u0646\u061F", correctAnswer: "\u0627\u0628\u0646 \u0633\u064A\u0646\u0627 (\u0623\u0628\u0648 \u0639\u0644\u064A \u0627\u0644\u062D\u0633\u064A\u0646 \u0628\u0646 \u0639\u0628\u062F \u0627\u0644\u0644\u0647 \u0628\u0646 \u0633\u064A\u0646\u0627)", explanation: "\u0648\u0636\u0639 \u0627\u0628\u0646 \u0633\u064A\u0646\u0627 \u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0641\u064A \u0627\u0644\u0637\u0628 \u0648\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u0634\u0641\u0627\u0621 \u0648\u064A\u0639\u062F \u0645\u0646 \u0623\u0639\u0638\u0645 \u0641\u0644\u0627\u0633\u0641\u0629 \u0648\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u062A\u0627\u0631\u064A\u062E.", source: "\u0639\u064A\u0648\u0646 \u0627\u0644\u0623\u0646\u0628\u0627\u0621 \u0641\u064A \u0637\u0628\u0642\u0627\u062A \u0627\u0644\u0623\u0637\u0628\u0627\u0621" }
      ],
      "\u0627\u0644\u062E\u0644\u064A\u062C": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0641\u064A \u0645\u062C\u0644\u0633 \u0627\u0644\u062A\u0639\u0627\u0648\u0646 \u0644\u062F\u0648\u0644 \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u061F", correctAnswer: "6 \u062F\u0648\u0644", explanation: "\u064A\u0636\u0645 \u0627\u0644\u0645\u062C\u0644\u0633: \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u060C \u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A\u060C \u0627\u0644\u0643\u0648\u064A\u062A\u060C \u0642\u0637\u0631\u060C \u0627\u0644\u0628\u062D\u0631\u064A\u0646\u060C \u0648\u0639\u0645\u0627\u0646.", source: "\u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0645\u062C\u0644\u0633 \u0627\u0644\u062A\u0639\u0627\u0648\u0646" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0641\u064A \u0623\u064A \u0645\u062F\u064A\u0646\u0629 \u0625\u0645\u0627\u0631\u0627\u062A\u064A\u0629 \u062A\u0623\u0633\u0633 \u0645\u062C\u0644\u0633 \u0627\u0644\u062A\u0639\u0627\u0648\u0646 \u0644\u062F\u0648\u0644 \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0631\u0633\u0645\u064A\u0627\u064B \u0639\u0627\u0645 1981\u061F", correctAnswer: "\u0623\u0628\u0648\u0638\u0628\u064A", explanation: "\u0639\u0642\u062F\u062A \u0627\u0644\u0642\u0645\u0629 \u0627\u0644\u062A\u0623\u0633\u064A\u0633\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0645\u062C\u0644\u0633 \u0627\u0644\u062A\u0639\u0627\u0648\u0646 \u0641\u064A \u0623\u0628\u0648\u0638\u0628\u064A \u0641\u064A 25 \u0645\u0627\u064A\u0648 1981.", source: "\u0648\u062B\u0627\u0626\u0642 \u062A\u0623\u0633\u064A\u0633 \u0645\u062C\u0644\u0633 \u0627\u0644\u062A\u0639\u0627\u0648\u0646" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0631\u064A\u0627\u0644 \u0627\u0644\u0633\u0639\u0648\u062F\u064A", explanation: "\u0627\u0644\u0631\u064A\u0627\u0644 \u0627\u0644\u0633\u0639\u0648\u062F\u064A \u0645\u0642\u0633\u0645 \u0625\u0644\u0649 100 \u0647\u0644\u0644\u0629 \u0648\u0645\u0631\u0628\u0648\u0637 \u0628\u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A \u0628\u0633\u0639\u0631 3.75 \u0631\u064A\u0627\u0644.", source: "\u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0627\u0644\u0633\u0639\u0648\u062F\u064A SAMA" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0628\u0631\u062C \u0627\u0644\u0623\u0637\u0648\u0644 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u064A\u0642\u0639 \u0641\u064A \u0645\u062F\u064A\u0646\u0629 \u062F\u0628\u064A\u061F", correctAnswer: "\u0628\u0631\u062C \u062E\u0644\u064A\u0641\u0629", explanation: "\u064A\u0628\u0644\u063A \u0627\u0631\u062A\u0641\u0627\u0639 \u0628\u0631\u062C \u062E\u0644\u064A\u0641\u0629 828 \u0645\u062A\u0631\u0627\u064B \u0648\u0627\u0641\u062A\u062A\u062D \u0631\u0633\u0645\u064A\u0627\u064B \u0639\u0627\u0645 2010.", source: "\u0645\u0648\u0633\u0648\u0639\u0629 \u063A\u064A\u0646\u064A\u0633 \u0644\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0642\u064A\u0627\u0633\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062A\u064A \u0627\u0633\u062A\u0636\u0627\u0641\u062A \u0646\u0647\u0627\u0626\u064A\u0627\u062A \u0643\u0623\u0633 \u0627\u0644\u0639\u0627\u0644\u0645 \u0644\u0643\u0631\u0629 \u0627\u0644\u0642\u062F\u0645 \u0639\u0627\u0645 2022\u061F", correctAnswer: "\u062F\u0648\u0644\u0629 \u0642\u0637\u0631", explanation: "\u0643\u0627\u0646\u062A \u0642\u0637\u0631 \u0623\u0648\u0644 \u062F\u0648\u0644\u0629 \u0639\u0631\u0628\u064A\u0629 \u0648\u0634\u0631\u0642 \u0623\u0648\u0633\u0637\u064A\u0629 \u062A\u062D\u062A\u0636\u0646 \u0627\u0644\u0645\u0648\u0646\u062F\u064A\u0627\u0644 \u0627\u0644\u0639\u0627\u0644\u0645\u064A.", source: "\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0641\u064A\u0641\u0627 FIFA" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062C\u0632\u0631\u064A\u0629 \u0627\u0644\u0645\u0631\u062A\u0628\u0637\u0629 \u0628\u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0639\u0628\u0631 \u062C\u0633\u0631 \u0627\u0644\u0645\u0644\u0643 \u0641\u0647\u062F\u061F", correctAnswer: "\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0646", explanation: "\u064A\u0631\u0628\u0637 \u062C\u0633\u0631 \u0627\u0644\u0645\u0644\u0643 \u0641\u0647\u062F \u0627\u0644\u0645\u0645\u062A\u062F \u0628\u0637\u0648\u0644 25 \u0643\u0645 \u0628\u064A\u0646 \u0627\u0644\u062E\u0628\u0631 \u0641\u064A \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0648\u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0623\u0645 \u0644\u0644\u0628\u062D\u0631\u064A\u0646.", source: "\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u062C\u0633\u0631 \u0627\u0644\u0645\u0644\u0643 \u0641\u0647\u062F" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0647\u0646\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u062A\u0631\u0627\u062B\u064A\u0629 \u0627\u0644\u0623\u0643\u062B\u0631 \u0634\u0647\u0631\u0629 \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A \u0642\u0628\u0644 \u0627\u0643\u062A\u0634\u0627\u0641 \u0627\u0644\u0646\u0641\u0637\u061F", correctAnswer: "\u0627\u0644\u063A\u0648\u0635 \u0639\u0644\u0649 \u0627\u0644\u0644\u0624\u0644\u0624 (\u0635\u064A\u062F \u0648\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u0644\u0624\u0644\u0624)", explanation: "\u0643\u0627\u0646 \u0645\u0648\u0633\u0645 \u0627\u0644\u063A\u0648\u0635 \u0639\u0644\u0649 \u0627\u0644\u0644\u0624\u0644\u0624 (\u0627\u0644\u063A\u0648\u0635 \u0627\u0644\u0643\u0628\u064A\u0631) \u064A\u0634\u0643\u0644 \u0639\u0635\u0628 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0648\u0627\u0644\u0645\u062C\u062A\u0645\u0639 \u0627\u0644\u062E\u0644\u064A\u062C\u064A \u0644\u0623\u062C\u064A\u0627\u0644.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0636\u064A\u0642 \u0627\u0644\u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0630\u064A \u062A\u0637\u0644 \u0639\u0644\u064A\u0647 \u0633\u0644\u0637\u0646\u0629 \u0639\u0645\u0627\u0646 \u0648\u0625\u064A\u0631\u0627\u0646 \u0648\u064A\u0645\u0631 \u0645\u0646\u0647 \u0646\u062D\u0648 \u062E\u0645\u0633 \u0646\u0641\u0637 \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0645\u0636\u064A\u0642 \u0647\u0631\u0645\u0632", explanation: "\u064A\u062A\u062D\u0643\u0645 \u0645\u0636\u064A\u0642 \u0647\u0631\u0645\u0632 \u0641\u064A \u062D\u0631\u0643\u0629 \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0646\u0641\u0637\u064A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0635\u0627\u062F\u0631\u0629 \u0645\u0646 \u0645\u0648\u0627\u0646\u0626 \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A.", source: "\u0625\u062F\u0627\u0631\u0629 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u062F\u0648\u0644\u064A\u0629 EIA" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0641\u064A \u0623\u064A \u0639\u0627\u0645 \u062A\u0645 \u062A\u0648\u062D\u064A\u062F \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0648\u0625\u0639\u0644\u0627\u0646 \u0627\u0633\u0645\u0647\u0627 \u0627\u0644\u062D\u0627\u0644\u064A \u0639\u0644\u0649 \u064A\u062F \u0627\u0644\u0645\u0644\u0643 \u0639\u0628\u062F \u0627\u0644\u0639\u0632\u064A\u0632 \u0622\u0644 \u0633\u0639\u0648\u062F\u061F", correctAnswer: "\u0639\u0627\u0645 1932\u0645 (1351\u0647\u0640)", explanation: "\u0635\u062F\u0631 \u0627\u0644\u0645\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u0644\u0643\u064A \u0628\u062A\u0648\u062D\u064A\u062F \u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u062D\u062C\u0627\u0632 \u0648\u0646\u062C\u062F \u0648\u0645\u0644\u062D\u0642\u0627\u062A\u0647\u0627 \u0628\u0627\u0633\u0645 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0641\u064A 23 \u0633\u0628\u062A\u0645\u0628\u0631 1932.", source: "\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0644\u0643 \u0639\u0628\u062F \u0627\u0644\u0639\u0632\u064A\u0632" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0644\u0649 \u0642\u0645\u0629 \u062C\u0628\u0644\u064A\u0629 \u0641\u064A \u0633\u0644\u0637\u0646\u0629 \u0639\u0645\u0627\u0646 \u0648\u0641\u064A \u0634\u0628\u0647 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0634\u0631\u0642\u064A\u0629\u061F", correctAnswer: "\u062C\u0628\u0644 \u0634\u0645\u0633 (\u0636\u0645\u0646 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062C\u0628\u0644 \u0627\u0644\u0623\u062E\u0636\u0631)", explanation: "\u064A\u0631\u062A\u0641\u0639 \u062C\u0628\u0644 \u0634\u0645\u0633 \u0644\u062D\u0648\u0627\u0644\u064A 3009 \u0623\u0645\u062A\u0627\u0631 \u0641\u0648\u0642 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631 \u0648\u064A\u0634\u062A\u0647\u0631 \u0628\u0648\u0627\u062F\u064A\u0647 \u0627\u0644\u0639\u0638\u064A\u0645 \u0627\u0644\u0645\u0644\u0642\u0628 \u0628\u062C\u0631\u0627\u0646\u062F \u0643\u0627\u0646\u064A\u0648\u0646 \u0639\u0645\u0627\u0646.", source: "\u062A\u0636\u0627\u0631\u064A\u0633 \u0633\u0644\u0637\u0646\u0629 \u0639\u0645\u0627\u0646" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062D\u0636\u0627\u0631\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0627\u0632\u062F\u0647\u0631\u062A \u0641\u064A \u062C\u0632\u0631 \u0627\u0644\u0628\u062D\u0631\u064A\u0646 \u0648\u0634\u0631\u0642 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0641\u064A \u0627\u0644\u0623\u0644\u0641\u064A\u0629 \u0627\u0644\u062B\u0627\u0644\u062B\u0629 \u0642\u0628\u0644 \u0627\u0644\u0645\u064A\u0644\u0627\u062F\u061F", correctAnswer: "\u062D\u0636\u0627\u0631\u0629 \u062F\u0644\u0645\u0648\u0646 (Dilmun)", explanation: "\u0627\u0634\u062A\u0647\u0631\u062A \u062F\u0644\u0645\u0648\u0646 \u0643\u0645\u0631\u0643\u0632 \u062A\u062C\u0627\u0631\u064A \u0645\u0627\u0626\u064A \u064A\u0631\u0628\u0637 \u0628\u064A\u0646 \u062D\u0636\u0627\u0631\u0627\u062A \u0628\u0644\u0627\u062F \u0627\u0644\u0631\u0627\u0641\u062F\u064A\u0646 \u0648\u0648\u0627\u062F\u064A \u0627\u0644\u0633\u0646\u062F.", source: "\u0622\u062B\u0627\u0631 \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u062F\u0646\u0649 \u0627\u0644\u0642\u062F\u064A\u0645" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0623\u0643\u0628\u0631 \u062D\u0642\u0644 \u0646\u0641\u0637\u064A \u0628\u0631\u064A \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0648\u064A\u0642\u0639 \u0641\u064A \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0634\u0631\u0642\u064A\u0629 \u0628\u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u061F", correctAnswer: "\u062D\u0642\u0644 \u0627\u0644\u063A\u0648\u0627\u0631 (Ghawar Field)", explanation: "\u062D\u0642\u0644 \u0627\u0644\u063A\u0648\u0627\u0631 \u0627\u0644\u062A\u0627\u0628\u0639 \u0644\u0623\u0631\u0627\u0645\u0643\u0648 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0647\u0648 \u0623\u0636\u062E\u0645 \u062D\u0642\u0644 \u0646\u0641\u0637 \u062A\u0642\u0644\u064A\u062F\u064A \u0628\u0631\u064A \u0641\u064A \u062A\u0627\u0631\u064A\u062E \u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0637\u0627\u0642\u0629.", source: "\u0623\u0631\u0627\u0645\u0643\u0648 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0641\u064A \u0623\u064A \u0639\u0627\u0645 \u062A\u0645 \u0627\u0643\u062A\u0634\u0627\u0641 \u0627\u0644\u0646\u0641\u0637 \u0628\u0643\u0645\u064A\u0627\u062A \u062A\u062C\u0627\u0631\u064A\u0629 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629 \u0641\u064A \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0641\u064A \u0628\u0626\u0631 \u0627\u0644\u062F\u0645\u0627\u0645 \u0631\u0642\u0645 7 (\u0628\u0626\u0631 \u0627\u0644\u062E\u064A\u0631)\u061F", correctAnswer: "\u0639\u0627\u0645 1938\u0645", explanation: "\u062A\u062F\u0641\u0642 \u0627\u0644\u0646\u0641\u0637 \u0645\u0646 \u0628\u0626\u0631 \u0627\u0644\u062E\u064A\u0631 \u0641\u064A \u0645\u0627\u0631\u0633 1938 \u0644\u062A\u0628\u062F\u0623 \u0627\u0644\u0646\u0647\u0636\u0629 \u0627\u0644\u0646\u0641\u0637\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u064A \u0627\u0644\u0645\u0645\u0644\u0643\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0646\u0641\u0637 \u0627\u0644\u0633\u0639\u0648\u062F\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0625\u0645\u0627\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u062A\u0648\u0644\u0649 \u0645\u0646\u0635\u0628 \u0631\u0626\u0627\u0633\u0629 \u062F\u0648\u0644\u0629 \u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u062F\u0633\u062A\u0648\u0631\u064A\u0627\u064B \u0648\u062A\u0642\u0644\u064A\u062F\u064A\u0627\u064B\u061F", correctAnswer: "\u0625\u0645\u0627\u0631\u0629 \u0623\u0628\u0648\u0638\u0628\u064A", explanation: "\u062D\u0627\u0643\u0645 \u0625\u0645\u0627\u0631\u0629 \u0623\u0628\u0648\u0638\u0628\u064A \u064A\u064F\u0646\u062A\u062E\u0628 \u0631\u0626\u064A\u0633\u0627\u064B \u0644\u0644\u0645\u062C\u0644\u0633 \u0627\u0644\u0623\u0639\u0644\u0649 \u0644\u0644\u0627\u062A\u062D\u0627\u062F \u0648\u062F\u0648\u0644\u0629 \u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A \u0648\u0641\u0642 \u0627\u0644\u062F\u0633\u062A\u0648\u0631.", source: "\u062F\u0633\u062A\u0648\u0631 \u062F\u0648\u0644\u0629 \u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0645\u062A\u062D\u062F\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0630\u064A \u0643\u0627\u0646 \u064A\u0637\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0628\u062D\u0631\u064A\u0646 \u0648\u062C\u0632\u0631\u0647\u0627 \u0641\u064A \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0625\u063A\u0631\u064A\u0642\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629\u061F", correctAnswer: "\u062A\u0627\u064A\u0644\u0648\u0633 (Tylos)", explanation: "\u0633\u0645\u0649 \u0627\u0644\u0625\u063A\u0631\u064A\u0642 \u0648\u0627\u0644\u0631\u0648\u0645\u0627\u0646 \u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0646 \u0628\u062A\u0627\u064A\u0644\u0648\u0633 \u0648\u0627\u0634\u062A\u0647\u0631\u062A \u0628\u0645\u063A\u0627\u0635\u0627\u062A \u0627\u0644\u0644\u0624\u0644\u0624 \u0648\u0642\u0637\u0646\u0647\u0627.", source: "\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0628\u0644\u064A\u0646\u064A\u0648\u0633 \u0627\u0644\u0623\u0643\u0628\u0631" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629 \u0627\u0644\u0633\u0627\u062D\u0644\u064A\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0641\u064A \u0633\u0644\u0637\u0646\u0629 \u0639\u0645\u0627\u0646 \u0627\u0644\u062A\u064A \u062A\u062A\u0645\u064A\u0632 \u0628\u0645\u0648\u0633\u0645 \u0627\u0644\u062E\u0631\u064A\u0641 \u0627\u0644\u0645\u0627\u0637\u0631 \u0648\u0627\u0644\u0636\u0628\u0627\u0628 \u0635\u064A\u0641\u0627\u064B\u061F", correctAnswer: "\u0645\u062D\u0627\u0641\u0638\u0629 \u0638\u0641\u0627\u0631 (\u0635\u0644\u0627\u0644\u0629)", explanation: "\u062A\u062A\u0623\u062B\u0631 \u0638\u0641\u0627\u0631 \u0628\u0627\u0644\u0631\u064A\u0627\u062D \u0627\u0644\u0645\u0648\u0633\u0645\u064A\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0627\u0644\u063A\u0631\u0628\u064A\u0629 \u0627\u0644\u0645\u062D\u0645\u0644\u0629 \u0628\u0627\u0644\u0623\u0645\u0637\u0627\u0631 \u0648\u0627\u0644\u0636\u0628\u0627\u0628 \u0628\u064A\u0646 \u0634\u0647\u0631\u064A \u064A\u0648\u0646\u064A\u0648 \u0648\u0633\u0628\u062A\u0645\u0628\u0631.", source: "\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u062A\u0631\u0627\u062B \u0648\u0627\u0644\u0633\u064A\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0627\u0646\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0636\u0645 \u0623\u0642\u062F\u0645 \u0628\u0631\u0644\u0645\u0627\u0646 \u0645\u0646\u062A\u062E\u0628 \u0648\u0645\u062C\u0644\u0633 \u0623\u0645\u0629 \u062A\u0623\u0633\u0633 \u0631\u0633\u0645\u064A\u0627\u064B \u0628\u0645\u0648\u062C\u0628 \u062F\u0633\u062A\u0648\u0631 \u0639\u0627\u0645 1962\u061F", correctAnswer: "\u062F\u0648\u0644\u0629 \u0627\u0644\u0643\u0648\u064A\u062A", explanation: "\u0623\u0635\u062F\u0631 \u0627\u0644\u0634\u064A\u062E \u0639\u0628\u062F \u0627\u0644\u0644\u0647 \u0627\u0644\u0633\u0627\u0644\u0645 \u0627\u0644\u0635\u0628\u0627\u062D \u062F\u0633\u062A\u0648\u0631 \u0627\u0644\u0643\u0648\u064A\u062A \u0639\u0627\u0645 1962 \u0648\u0627\u0646\u0637\u0644\u0642 \u0645\u062C\u0644\u0633 \u0627\u0644\u0623\u0645\u0629 \u0641\u064A \u064A\u0646\u0627\u064A\u0631 1963.", source: "\u0627\u0644\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u0648\u0637\u0646\u064A \u0627\u0644\u0643\u0648\u064A\u062A\u064A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u062D\u0642\u0644 \u0627\u0644\u063A\u0627\u0632 \u0627\u0644\u0645\u0634\u062A\u0631\u0643 \u0641\u064A \u0645\u064A\u0627\u0647 \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0630\u064A \u064A\u0639\u062F \u0623\u0636\u062E\u0645 \u062D\u0642\u0644 \u063A\u0627\u0632 \u0637\u0628\u064A\u0639\u064A \u063A\u064A\u0631 \u0645\u0635\u0627\u062D\u0628 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u062D\u0642\u0644 \u0627\u0644\u0634\u0645\u0627\u0644 \u0627\u0644\u0642\u0637\u0631\u064A (\u0648\u062D\u0642\u0644 \u0628\u0627\u0631\u0633 \u0627\u0644\u062C\u0646\u0648\u0628\u064A \u0627\u0644\u0625\u064A\u0631\u0627\u0646\u064A)", explanation: "\u064A\u0645\u062A\u0644\u0643 \u0627\u0644\u062D\u0642\u0644 \u0627\u0644\u0645\u0634\u062A\u0631\u0643 \u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A \u0647\u0627\u0626\u0644\u0629 \u062A\u0645\u062B\u0644 \u0646\u062D\u0648 19% \u0645\u0646 \u0625\u062C\u0645\u0627\u0644\u064A \u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A \u0627\u0644\u063A\u0627\u0632 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0623\u0648\u0628\u0643 \u0648\u0645\u0646\u0638\u0645\u0627\u062A \u0627\u0644\u0637\u0627\u0642\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0641\u064A\u0646\u0629 \u0627\u0644\u0634\u0631\u0627\u0639\u064A\u0629 \u0627\u0644\u062E\u0634\u0628\u064A\u0629 \u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062A\u0631\u0627\u062B\u064A\u0629 \u0627\u0644\u0645\u062E\u0635\u0635\u0629 \u0644\u0644\u0623\u0633\u0641\u0627\u0631 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0648\u0646\u0642\u0644 \u0627\u0644\u0628\u0636\u0627\u0626\u0639 \u0644\u0644\u0647\u0646\u062F \u0648\u0625\u0641\u0631\u064A\u0642\u064A\u0627\u061F", correctAnswer: "\u0627\u0644\u0628\u0648\u0645 (\u0623\u0648 \u0627\u0644\u0628\u063A\u0644\u0629)", explanation: "\u0627\u0644\u0628\u0648\u0645 \u0647\u064A \u0623\u0634\u0647\u0631 \u0633\u0641\u064A\u0646\u0629 \u0634\u0631\u0627\u0639\u064A\u0629 \u062E\u0644\u064A\u062C\u064A\u0629 \u0635\u0646\u0639\u062A \u0628\u0645\u0647\u0627\u0631\u0629 \u0641\u064A \u0645\u0648\u0627\u0646\u0626 \u0627\u0644\u0643\u0648\u064A\u062A \u0648\u0639\u0645\u0627\u0646 \u0648\u062F\u0628\u064A.", source: "\u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0633\u0641\u0646 \u0627\u0644\u062A\u0631\u0627\u062B\u064A\u0629 \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0642\u062F\u064A\u0645 \u0644\u0625\u0642\u0644\u064A\u0645 \u0633\u0644\u0637\u0646\u0629 \u0639\u0645\u0627\u0646 \u0627\u0644\u0630\u064A \u0627\u0634\u062A\u0647\u0631 \u0628\u0635\u0647\u0631 \u0648\u062A\u0635\u062F\u064A\u0631 \u0627\u0644\u0646\u062D\u0627\u0633 \u0625\u0644\u0649 \u0627\u0644\u0633\u0648\u0645\u0631\u064A\u064A\u0646\u061F", correctAnswer: "\u0645\u062C\u0627\u0646 (Magan)", explanation: "\u0648\u0631\u062F \u0627\u0633\u0645 \u0645\u062C\u0627\u0646 \u0641\u064A \u0627\u0644\u0623\u0644\u0648\u0627\u062D \u0627\u0644\u0645\u0633\u0645\u0627\u0631\u064A\u0629 \u0627\u0644\u0633\u0648\u0645\u0631\u064A\u0629 \u0648\u0627\u0644\u0623\u0643\u0627\u062F\u064A\u0629 \u0643\u0623\u0631\u0636 \u063A\u0646\u064A\u0629 \u0628\u0627\u0644\u0646\u062D\u0627\u0633 \u0648\u0627\u0644\u0623\u062D\u062C\u0627\u0631 \u0627\u0644\u0643\u0631\u064A\u0645\u0629.", source: "\u0623\u0644\u0648\u0627\u062D \u0628\u0644\u0627\u062F \u0627\u0644\u0631\u0627\u0641\u062F\u064A\u0646 \u0648\u0627\u0644\u0622\u062B\u0627\u0631 \u0627\u0644\u0639\u0645\u0627\u0646\u064A\u0629" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0627\u0647\u062F\u0629 \u0627\u0644\u062A\u064A \u0648\u0642\u0639\u062A\u0647\u0627 \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627 \u0645\u0639 \u0645\u0634\u064A\u062E\u0627\u062A \u0633\u0627\u062D\u0644 \u0639\u0645\u0627\u0646 \u0639\u0627\u0645 1820 \u0648\u0645\u062B\u0644\u062A \u0628\u062F\u0627\u064A\u0629 \u0627\u0644\u0646\u0641\u0648\u0630 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C\u061F", correctAnswer: "\u0627\u0644\u0645\u0639\u0627\u0647\u062F\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0644\u0633\u0644\u0627\u0645 (\u0645\u0639\u0627\u0647\u062F\u0629 1820)", explanation: "\u0648\u0642\u0639\u062A \u0627\u0644\u0645\u0639\u0627\u0647\u062F\u0629 \u0641\u064A \u0631\u0623\u0633 \u0627\u0644\u062E\u064A\u0645\u0629 \u0644\u062D\u0638\u0631 \u0627\u0644\u0642\u0631\u0635\u0646\u0629 \u0648\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u0631\u0642\u064A\u0642 \u0648\u062A\u062B\u0628\u064A\u062A \u0627\u0644\u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629.", source: "\u0633\u062C\u0644\u0627\u062A \u062D\u0643\u0648\u0645\u0629 \u0627\u0644\u0647\u0646\u062F \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0628\u062D\u0627\u0631 \u0648\u0627\u0644\u0645\u0644\u0627\u062D \u0627\u0644\u0639\u0645\u0627\u0646\u064A \u0648\u0627\u0644\u062E\u0644\u064A\u062C\u064A \u0627\u0644\u0634\u0647\u064A\u0631 \u0627\u0644\u0645\u0644\u0642\u0628 \u0628\u0640 \xAB\u0623\u0633\u062F \u0627\u0644\u0628\u062D\u0627\u0631\xBB \u0648\u0645\u0624\u0644\u0641 \u0643\u062A\u0627\u0628 \xAB\u0627\u0644\u0641\u0648\u0627\u0626\u062F \u0641\u064A \u0623\u0635\u0648\u0644 \u0639\u0644\u0645 \u0627\u0644\u0628\u062D\u0631 \u0648\u0627\u0644\u0642\u0648\u0627\u0639\u062F\xBB\u061F", correctAnswer: "\u0623\u062D\u0645\u062F \u0628\u0646 \u0645\u0627\u062C\u062F \u0627\u0644\u0633\u0639\u062F\u064A", explanation: "\u0627\u0628\u0646 \u0645\u0627\u062C\u062F \u0623\u0639\u0638\u0645 \u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0641\u0644\u0643\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0646\u062F\u064A \u0648\u0627\u0644\u062E\u0644\u064A\u062C \u0648\u0627\u0628\u062A\u0643\u0631 \u0628\u0648\u0635\u0644\u0629 \u0627\u0644\u0648\u0631\u062F\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0644\u0648\u0645 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0643\u0648\u064A\u062A\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u062A\u064A \u0639\u064F\u062B\u0631 \u0641\u064A\u0647\u0627 \u0639\u0644\u0649 \u0622\u062B\u0627\u0631 \u0648\u062D\u0635\u0648\u0646 \u0625\u063A\u0631\u064A\u0642\u064A\u0629 \u0648\u0645\u0639\u0628\u062F \u0627\u0644\u0625\u0644\u0647\u0629 \u0623\u0631\u062A\u0645\u064A\u0633 \u0648\u0623\u062E\u062A\u0627\u0645 \u062F\u0644\u0645\u0648\u0646\u064A\u0629\u061F", correctAnswer: "\u062C\u0632\u064A\u0631\u0629 \u0641\u064A\u0644\u0643\u0627 (Failaka / \u0625\u064A\u0643\u0627\u0631\u0648\u0633)", explanation: "\u0623\u0637\u0644\u0642 \u0627\u0644\u0625\u0633\u0643\u0646\u062F\u0631 \u0627\u0644\u0645\u0642\u062F\u0648\u0646\u064A \u0639\u0644\u0649 \u0641\u064A\u0644\u0643\u0627 \u0627\u0633\u0645 \u0625\u064A\u0643\u0627\u0631\u0648\u0633 \u0648\u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0645\u0633\u062A\u0648\u0637\u0646\u0627\u062A \u0623\u062B\u0631\u064A\u0629 \u0647\u0627\u0645\u0629 \u062A\u0639\u0648\u062F \u0644\u0644\u0639\u0635\u0631 \u0627\u0644\u0647\u0644\u0646\u0633\u062A\u064A.", source: "\u0627\u0644\u0622\u062B\u0627\u0631 \u0648\u0627\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u0643\u0648\u064A\u062A\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0641\u064A \u0623\u064A \u0639\u0627\u0645 \u0623\u0644\u063A\u062A \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627 \u062C\u0645\u064A\u0639 \u0645\u0639\u0627\u0647\u062F\u0627\u062A \u0627\u0644\u062D\u0645\u0627\u064A\u0629 \u0648\u0627\u0646\u0633\u062D\u0628\u062A \u0642\u0648\u0627\u062A\u0647\u0627 \u0645\u0646 \u0634\u0631\u0642 \u0627\u0644\u0633\u0648\u064A\u0633 \u0648\u0627\u0633\u062A\u0642\u0644\u062A \u062F\u0648\u0644 \u0627\u0644\u062E\u0644\u064A\u062C (\u0627\u0644\u0643\u0648\u064A\u062A 1961\u060C \u0648\u0627\u0644\u0628\u062D\u0631\u064A\u0646 \u0648\u0642\u0637\u0631 \u0648\u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A 1971)\u061F", correctAnswer: "\u0639\u0627\u0645 1971\u0645 (\u0644\u0644\u0628\u062D\u0631\u064A\u0646 \u0648\u0642\u0637\u0631 \u0648\u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A)", explanation: "\u0623\u0639\u0644\u0646\u062A \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627 \u0633\u062D\u0628 \u0642\u0648\u0627\u062A\u0647\u0627 \u0646\u0647\u0627\u064A\u0629 1971 \u0644\u062A\u0639\u0644\u0646 \u0627\u0644\u0625\u0645\u0627\u0631\u0627\u062A \u0642\u064A\u0627\u0645 \u0627\u0644\u0627\u062A\u062D\u0627\u062F \u0648\u0627\u0644\u0628\u062D\u0631\u064A\u0646 \u0648\u0642\u0637\u0631 \u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u0627\u0644\u0643\u0627\u0645\u0644.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u0648\u0633\u0637 \u0627\u0644\u062D\u062F\u064A\u062B" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0648\u0627\u062D\u0629 \u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0634\u0631\u0642\u064A\u0629 \u0648\u0627\u0644\u062A\u064A \u062A\u0639\u062A\u0628\u0631 \u0623\u0643\u0628\u0631 \u0648\u0627\u062D\u0629 \u0646\u062E\u064A\u0644 \u0637\u0628\u064A\u0639\u064A\u0629 \u0645\u0633\u062C\u0644\u0629 \u0641\u064A \u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648\u061F", correctAnswer: "\u0648\u0627\u062D\u0629 \u0627\u0644\u0623\u062D\u0633\u0627\u0621", explanation: "\u062A\u0636\u0645 \u0648\u0627\u062D\u0629 \u0627\u0644\u0623\u062D\u0633\u0627\u0621 \u0623\u0643\u062B\u0631 \u0645\u0646 2.5 \u0645\u0644\u064A\u0648\u0646 \u0646\u062E\u0644\u0629 \u062A\u063A\u0630\u064A\u0647\u0627 \u0639\u064A\u0648\u0646 \u0627\u0644\u0645\u064A\u0627\u0647 \u0627\u0644\u062C\u0648\u0641\u064A\u0629 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629.", source: "\u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648 \u0644\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064A" }
      ],
      "\u0644\u063A\u0627\u062A \u0648\u0644\u0647\u062C\u0627\u062A": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0623\u062D\u0631\u0641 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0647\u062C\u0627\u0626\u064A\u0629\u061F", correctAnswer: "28 \u062D\u0631\u0641\u0627\u064B", explanation: "\u062A\u062A\u0643\u0648\u0646 \u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0647\u062C\u0627\u0626\u064A\u0629 \u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0645\u0646 \u062B\u0645\u0627\u0646\u064A\u0629 \u0648\u0639\u0634\u0631\u064A\u0646 \u062D\u0631\u0641\u0627\u064B \u062A\u0628\u062F\u0623 \u0628\u0627\u0644\u0623\u0644\u0641 \u0648\u062A\u0646\u062A\u0647\u064A \u0628\u0627\u0644\u064A\u0627\u0621.", source: "\u0645\u0639\u0627\u062C\u0645 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u0631\u0641 \u0627\u0644\u0641\u0631\u064A\u062F \u0627\u0644\u0630\u064A \u062A\u0634\u062A\u0647\u0631 \u0628\u0647 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u062A\u0644\u0642\u0628 \u0628\u0644\u063A\u062A\u0647 \u0644\u0639\u062F\u0645 \u0648\u062C\u0648\u062F\u0647 \u0641\u064A \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649\u061F", correctAnswer: "\u062D\u0631\u0641 \u0627\u0644\u0636\u0627\u062F (\u0644\u063A\u0629 \u0627\u0644\u0636\u0627\u062F)", explanation: "\u062A\u0644\u0642\u0628 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0628\u0644\u063A\u0629 \u0627\u0644\u0636\u0627\u062F \u0644\u0635\u0639\u0648\u0628\u0629 \u0646\u0637\u0642 \u0647\u0630\u0627 \u0627\u0644\u0635\u0648\u062A \u0648\u062A\u0645\u064A\u0632 \u0645\u062E\u0627\u0631\u062C\u0647.", source: "\u0641\u0642\u0647 \u0627\u0644\u0644\u063A\u0629 \u0644\u0644\u062B\u0639\u0627\u0644\u0628\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0627\u0644\u0623\u0643\u062B\u0631 \u062A\u062D\u062F\u062B\u0627\u064B \u0641\u064A \u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0628\u0631\u062A\u063A\u0627\u0644\u064A\u0629", explanation: "\u0627\u0644\u0628\u0631\u0627\u0632\u064A\u0644 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u062A\u064A\u0646 \u0627\u0644\u062A\u064A \u062A\u062A\u062D\u062F\u062B \u0627\u0644\u0628\u0631\u062A\u063A\u0627\u0644\u064A\u0629 \u0643\u0644\u063A\u0629 \u0631\u0633\u0645\u064A\u0629.", source: "\u0623\u0637\u0644\u0633 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0623\u0645 \u0627\u0644\u062A\u064A \u064A\u0646\u062D\u062F\u0631 \u0645\u0646\u0647\u0627 \u0623\u0643\u0628\u0631 \u0639\u062F\u062F \u0645\u0646 \u0627\u0644\u0645\u062A\u062D\u062F\u062B\u064A\u0646 \u0627\u0644\u0623\u0635\u0644\u064A\u064A\u0646 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 (\u0627\u0644\u0645\u0646\u062F\u0631\u064A\u0646 / Mandarin)", explanation: "\u064A\u062A\u062D\u062F\u062B \u0644\u063A\u0629 \u0627\u0644\u0645\u0646\u062F\u0631\u064A\u0646 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0623\u0643\u062B\u0631 \u0645\u0646 900 \u0645\u0644\u064A\u0648\u0646 \u0645\u062A\u062D\u062F\u062B \u0623\u0635\u0644\u064A \u0643\u0623\u0648\u0644 \u0644\u063A\u0629.", source: "\u0625\u062B\u0646\u0648\u0644\u0648\u062C \u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645 (Ethnologue)" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0641\u064A \u0623\u064A \u0627\u062A\u062C\u0627\u0647 \u062A\u064F\u0643\u062A\u0628 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0628\u0631\u064A\u0629 \u0648\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0641\u0627\u0631\u0633\u064A\u0629\u061F", correctAnswer: "\u0645\u0646 \u0627\u0644\u064A\u0645\u064A\u0646 \u0625\u0644\u0649 \u0627\u0644\u064A\u0633\u0627\u0631 (RTL)", explanation: "\u062A\u0643\u062A\u0628 \u0647\u0630\u0647 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0633\u0627\u0645\u064A\u0629 \u0648\u0627\u0644\u0625\u064A\u0631\u0627\u0646\u064A\u0629 \u0627\u0644\u0645\u0634\u062A\u0642\u0629 \u0623\u0628\u062C\u062F\u064A\u0627\u064B \u0645\u0646 \u0627\u0644\u064A\u0645\u064A\u0646 \u0646\u062D\u0648 \u0627\u0644\u064A\u0633\u0627\u0631.", source: "\u062A\u0627\u0631\u064A\u062E \u0646\u0638\u0645 \u0627\u0644\u0643\u062A\u0627\u0628\u0629" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u062F \u0623\u0645 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0631\u0648\u0645\u0627\u0646\u0633\u064A\u0629 (\u0627\u0644\u0641\u0631\u0646\u0633\u064A\u0629\u060C \u0627\u0644\u0625\u064A\u0637\u0627\u0644\u064A\u0629\u060C \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629\u060C \u0627\u0644\u0628\u0631\u062A\u063A\u0627\u0644\u064A\u0629)\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629", explanation: "\u062A\u0637\u0648\u0631\u062A \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0631\u0648\u0645\u0627\u0646\u0633\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0645\u0646 \u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629 \u0627\u0644\u0634\u0639\u0628\u064A\u0629 \u0641\u064A \u0627\u0644\u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u064A\u0629 \u0627\u0644\u0631\u0648\u0645\u0627\u0646\u064A\u0629.", source: "\u0639\u0644\u0645 \u0627\u0644\u0644\u063A\u0648\u064A\u0627\u062A \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u064A \u0628\u0644\u0627\u062F \u0627\u0644\u0645\u063A\u0631\u0628 \u0627\u0644\u0639\u0631\u0628\u064A \u0648\u062A\u062A\u0645\u064A\u0632 \u0628\u0645\u0632\u062C \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0632\u064A\u063A\u064A\u0629 \u0648\u0627\u0644\u0641\u0631\u0646\u0633\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u062F\u0627\u0631\u062C\u0629 (\u0627\u0644\u062F\u0627\u0631\u062C\u0629 \u0627\u0644\u0645\u063A\u0627\u0631\u0628\u064A\u0629)", explanation: "\u0627\u0644\u062F\u0627\u0631\u062C\u0629 \u0647\u064A \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u064A\u0648\u0645\u064A\u0629 \u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0645\u063A\u0631\u0628 \u0648\u0627\u0644\u062C\u0632\u0627\u0626\u0631 \u0648\u062A\u0648\u0646\u0633.", source: "\u0627\u0644\u0644\u0647\u062C\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0645\u0639\u0627\u0635\u0631\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0641\u064A \u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u0646\u0645\u0633\u0627\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629", explanation: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0644\u0644\u0646\u0645\u0633\u0627\u060C \u0645\u0639 \u0648\u062C\u0648\u062F \u0644\u0647\u062C\u0627\u062A \u0646\u0645\u0633\u0627\u0648\u064A\u0629 \u0645\u062D\u0644\u064A\u0629.", source: "\u062F\u0633\u062A\u0648\u0631 \u0627\u0644\u0646\u0645\u0633\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0633\u0627\u0645\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u0643\u0627\u0646 \u064A\u062A\u062D\u062F\u062B \u0628\u0647\u0627 \u0627\u0644\u0645\u0633\u064A\u062D \u0639\u064A\u0633\u0649 \u0639\u0644\u064A\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u064A \u0627\u0644\u062C\u0644\u064A\u0644 \u0648\u0641\u0644\u0633\u0637\u064A\u0646\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0622\u0631\u0627\u0645\u064A\u0629 (\u0627\u0644\u0633\u0631\u064A\u0627\u0646\u064A\u0629)", explanation: "\u0643\u0627\u0646\u062A \u0627\u0644\u0622\u0631\u0627\u0645\u064A\u0629 \u0647\u064A \u0644\u063A\u0629 \u0627\u0644\u062A\u062E\u0627\u0637\u0628 \u0627\u0644\u064A\u0648\u0645\u064A \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u064A \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u062F\u0646\u0649 \u0627\u0644\u0642\u062F\u064A\u0645 \u0641\u064A \u062A\u0644\u0643 \u0627\u0644\u062D\u0642\u0628\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0633\u0627\u0645\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627\u0630\u0627 \u062A\u0639\u0646\u064A \u0643\u0644\u0645\u0629 \xAB\u0648\u0627\u062E\u0627\xBB \u0641\u064A \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u0645\u063A\u0631\u0628\u064A\u0629 \u0627\u0644\u062F\u0627\u0631\u062C\u0629\u061F", correctAnswer: "\u062D\u0633\u0646\u0627\u064B / \u0645\u0648\u0627\u0641\u0642 (\u0637\u064A\u0628)", explanation: "\u062A\u0633\u062A\u062E\u062F\u0645 \u0643\u0644\u0645\u0629 \u0648\u0627\u062E\u0627 \u0641\u064A \u0627\u0644\u0645\u063A\u0631\u0628 \u0643\u0645\u0631\u0627\u062F\u0641 \u0644\u0643\u0644\u0645\u0629 \u062A\u0645\u0627\u0645\u0627\u064B \u0623\u0648 \u062D\u0633\u0646\u0627\u064B \u0648\u062A\u0639\u0648\u062F \u0644\u0623\u0635\u0644 \xAB\u0648\u0625\u0646 \u062E\u0627\u0621\xBB.", source: "\u0645\u0639\u062C\u0645 \u0627\u0644\u062F\u0627\u0631\u062C\u0629 \u0627\u0644\u0645\u063A\u0631\u0628\u064A\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0644\u063A\u0648\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0627\u0644\u062A\u064A \u062A\u0646\u062A\u0645\u064A \u0625\u0644\u064A\u0647\u0627 \u0627\u0644\u0644\u063A\u0627\u062A: \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u060C \u0648\u0627\u0644\u0639\u0628\u0631\u064A\u0629\u060C \u0648\u0627\u0644\u0623\u0645\u0647\u0631\u064A\u0629\u060C \u0648\u0627\u0644\u0622\u0631\u0627\u0645\u064A\u0629\u061F", correctAnswer: "\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0623\u0641\u0631\u0648\u0622\u0633\u064A\u0648\u064A\u0629 (\u0627\u0644\u0641\u0631\u0639 \u0627\u0644\u0633\u0627\u0645\u064A)", explanation: "\u062A\u0646\u062A\u0645\u064A \u0647\u0630\u0647 \u0627\u0644\u0644\u063A\u0627\u062A \u0625\u0644\u0649 \u0641\u0631\u0639 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0633\u0627\u0645\u064A\u0629 \u0636\u0645\u0646 \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0623\u0641\u0631\u0648\u0622\u0633\u064A\u0648\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649.", source: "\u062A\u0635\u0646\u064A\u0641 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0641\u064A \u0625\u064A\u0631\u0627\u0646 \u0648\u0627\u0644\u062A\u064A \u062A\u0646\u062A\u0645\u064A \u0625\u0644\u0649 \u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0647\u0646\u062F\u0648-\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0648\u062A\u0643\u062A\u0628 \u0628\u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0641\u0627\u0631\u0633\u064A\u0629 (Farsi)", explanation: "\u0627\u0644\u0641\u0627\u0631\u0633\u064A\u0629 \u0644\u063A\u0629 \u0647\u0646\u062F\u0648-\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u063A\u0646\u064A\u0629 \u0628\u0627\u0644\u0645\u0641\u0631\u062F\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u062A\u0643\u062A\u0628 \u0628\u062D\u0631\u0648\u0641 \u0645\u0634\u062A\u0642\u0629 \u0645\u0646 \u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629.", source: "\u0639\u0644\u0645 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0645\u0642\u0627\u0631\u0646" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0635\u0648\u062A\u064A\u0629 \u0641\u064A \u0628\u0639\u0636 \u0627\u0644\u0644\u0647\u062C\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0648\u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0628\u062F\u0644 \u0627\u0644\u062C\u064A\u0645 \u064A\u0627\u0621\u064B (\u0645\u062B\u0644: \u062F\u062C\u0627\u062C \u062A\u0635\u0628\u062D \u062F\u064A\u0627\u064A)\u061F", correctAnswer: "\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0639\u062C\u0639\u062C\u0629 (\u0623\u0648 \u0627\u0644\u062C\u064A\u0645 \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0637\u0634\u0629 \u0648\u062A\u062D\u0648\u0644\u0647\u0627 \u0644\u064A\u0627\u0621)", explanation: "\u0625\u0628\u062F\u0627\u0644 \u0627\u0644\u062C\u064A\u0645 \u064A\u0627\u0621\u064B \u0644\u0647\u062C\u0629 \u0639\u0631\u0628\u064A\u0629 \u0642\u062F\u064A\u0645\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0641\u064A \u0628\u0646\u064A \u062A\u0645\u064A\u0645 \u0648\u0628\u0639\u0636 \u0628\u0637\u0648\u0646 \u0642\u0636\u0627\u0639\u0629 \u0648\u0645\u0627 \u0632\u0627\u0644\u062A \u062D\u064A\u0629 \u0641\u064A \u0627\u0644\u062E\u0644\u064A\u062C.", source: "\u0627\u0644\u062E\u0635\u0627\u0626\u0635 \u0644\u0627\u0628\u0646 \u062C\u0646\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0643\u0644\u0627\u0633\u064A\u0643\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0644\u0644\u0647\u0646\u062F \u0627\u0644\u062A\u064A \u0643\u064F\u062A\u0628\u062A \u0628\u0647\u0627 \u0646\u0635\u0648\u0635 \u0627\u0644\u0641\u064A\u062F\u0627 \u0648\u062A\u0645\u0627\u062B\u0644 \u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629 \u0641\u064A \u0623\u0648\u0631\u0648\u0628\u0627\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0633\u0646\u0633\u0643\u0631\u064A\u062A\u064A\u0629 (Sanskrit)", explanation: "\u0627\u0644\u0633\u0646\u0633\u0643\u0631\u064A\u062A\u064A\u0629 \u0644\u063A\u0629 \u0647\u0646\u062F\u0648-\u0622\u0631\u064A\u0629 \u0645\u0642\u062F\u0633\u0629 \u0648\u0647\u064A \u0623\u0633\u0627\u0633 \u0645\u0639\u0638\u0645 \u0644\u063A\u0627\u062A \u0634\u0645\u0627\u0644 \u0627\u0644\u0647\u0646\u062F \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0643\u0627\u0644\u0647\u0646\u062F\u064A\u0629 \u0648\u0627\u0644\u0628\u0646\u062C\u0627\u0628\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0644\u063A\u0627\u062A \u0627\u0644\u0647\u0646\u062F" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627\u0630\u0627 \u062A\u0639\u0646\u064A \u0643\u0644\u0645\u0629 \xAB\u0634\u0643\u0648 \u0645\u0627\u0643\u0648\xBB \u0641\u064A \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629\u061F", correctAnswer: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0623\u062E\u0628\u0627\u0631\u061F / \u0645\u0627\u0630\u0627 \u064A\u062D\u062F\u062B\u061F (\u0645\u0627 \u0627\u0644\u062C\u062F\u064A\u062F\u061F)", explanation: "\u062A\u0633\u062A\u062E\u062F\u0645 \u0634\u0643\u0648 \u0645\u0627\u0643\u0648 \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642 \u0643\u062A\u062D\u064A\u0629 \u0648\u0633\u0624\u0627\u0644 \u0639\u0646 \u0627\u0644\u0623\u062E\u0628\u0627\u0631 \u0648\u0623\u0635\u0644\u0647\u0627 \xAB\u0623\u064A \u0634\u064A\u0621 \u0643\u0627\u0626\u0646 \u0648\u0645\u0627 \u0644\u064A\u0633 \u0628\u0643\u0627\u0626\u0646\xBB.", source: "\u0645\u0639\u062C\u0645 \u0627\u0644\u0639\u0627\u0645\u064A\u0629 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0627\u0644\u0645\u0639\u0632\u0648\u0644\u0629 \u062C\u064A\u0646\u064A\u0627\u064B (\u0644\u0627 \u062A\u0646\u062A\u0645\u064A \u0644\u0623\u064A \u0639\u0627\u0626\u0644\u0629 \u0644\u063A\u0648\u064A\u0629 \u0645\u0639\u0631\u0648\u0641\u0629) \u0648\u064A\u062A\u062D\u062F\u062B \u0628\u0647\u0627 \u0633\u0643\u0627\u0646 \u0641\u064A \u0634\u0645\u0627\u0644 \u0625\u0633\u0628\u0627\u0646\u064A\u0627 \u0648\u062C\u0646\u0648\u0628 \u0641\u0631\u0646\u0633\u0627\u061F", correctAnswer: "\u0644\u063A\u0629 \u0627\u0644\u0628\u0627\u0633\u0643 (Euskara)", explanation: "\u062A\u0639\u062A\u0628\u0631 \u0644\u063A\u0629 \u0627\u0644\u0628\u0627\u0633\u0643 \u0627\u0644\u0644\u063A\u0632 \u0627\u0644\u0644\u063A\u0648\u064A \u0627\u0644\u0623\u0643\u0628\u0631 \u0641\u064A \u0623\u0648\u0631\u0648\u0628\u0627 \u0644\u0643\u0648\u0646\u0647\u0627 \u0644\u063A\u0629 \u0645\u0639\u0632\u0648\u0644\u0629 \u0633\u0628\u0642\u062A \u0648\u0635\u0648\u0644 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0647\u0646\u062F\u0648-\u0623\u0648\u0631\u0648\u0628\u064A\u0629.", source: "\u0639\u0644\u0645 \u0627\u0644\u0644\u063A\u0648\u064A\u0627\u062A \u0627\u0644\u0645\u0642\u0627\u0631\u0646" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u0647\u062C\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u064A\u0645\u0646\u064A\u0629 \u0648\u0627\u0644\u0639\u0645\u0627\u0646\u064A\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u063A\u064A\u0631 \u0627\u0644\u0645\u0643\u062A\u0648\u0628\u0629 \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0632\u0627\u0644 \u062A\u064F\u0646\u0637\u0642 \u0641\u064A \u0645\u062D\u0627\u0641\u0638\u0629 \u0627\u0644\u0645\u0647\u0631\u0629 \u0648\u0633\u0642\u0637\u0631\u0649\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0645\u0647\u0631\u064A\u0629 (\u0648\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0633\u0642\u0637\u0631\u064A\u0629)", explanation: "\u0627\u0644\u0645\u0647\u0631\u064A\u0629 \u0648\u0627\u0644\u0633\u0642\u0637\u0631\u064A\u0629 \u0644\u063A\u0627\u062A \u0633\u0627\u0645\u064A\u0629 \u062C\u0646\u0648\u0628\u064A\u0629 \u0642\u062F\u064A\u0645\u0629 \u062D\u064A\u0629 \u062A\u062E\u062A\u0644\u0641 \u0639\u0646 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0641\u0635\u062D\u0649.", source: "\u062F\u0631\u0627\u0633\u0627\u062A \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0633\u0627\u0645\u064A\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u0647\u062C\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0644\u0628 \u0643\u0627\u0641 \u0627\u0644\u062E\u0637\u0627\u0628 \u0644\u0644\u0645\u0624\u0646\u062B \u0634\u064A\u0646\u0627\u064B (\u0645\u062B\u0644: \u0643\u062A\u0627\u0628\u0634 \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0643\u062A\u0627\u0628\u0643\u0650)\u061F", correctAnswer: "\u0627\u0644\u0643\u0634\u0643\u0634\u0629", explanation: "\u0627\u0644\u0643\u0634\u0643\u0634\u0629 \u0644\u063A\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0641\u064A \u0631\u0628\u064A\u0639\u0629 \u0648\u0645\u0636\u0631 \u0648\u062A\u0645\u064A\u0645 \u0648\u0644\u0627 \u062A\u0632\u0627\u0644 \u0633\u0627\u0626\u062F\u0629 \u0641\u064A \u0628\u0639\u0636 \u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062E\u0644\u064A\u062C \u0648\u0627\u0644\u064A\u0645\u0646 \u0648\u0646\u062C\u062F.", source: "\u0645\u0639\u0627\u062C\u0645 \u0641\u0642\u0647 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0631\u0648\u0633\u064A\u0629\u060C \u0648\u0627\u0644\u0635\u0631\u0628\u064A\u0629\u060C \u0648\u0627\u0644\u0628\u0644\u063A\u0627\u0631\u064A\u0629 \u0648\u062A\u0646\u0633\u0628 \u0644\u0644\u0642\u062F\u064A\u0633\u064A\u0646 \u0633\u064A\u0631\u064A\u0644 \u0648\u0645\u064A\u062B\u0648\u062F\u064A\u0648\u0633\u061F", correctAnswer: "\u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0633\u064A\u0631\u064A\u0644\u064A\u0629 (Cyrillic script)", explanation: "\u0637\u0648\u0631\u0647\u0627 \u062A\u0644\u0627\u0645\u0630\u0629 \u0627\u0644\u0642\u062F\u064A\u0633 \u0633\u064A\u0631\u064A\u0644 \u0641\u064A \u0627\u0644\u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u064A\u0629 \u0627\u0644\u0628\u0644\u063A\u0627\u0631\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0633\u0644\u0627\u0641\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0627\u062A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u0627\u0644\u0647\u062C\u064A\u0646\u0629 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u0629 \u0641\u064A \u0634\u0631\u0642 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0627\u0644\u062A\u064A \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0646\u0633\u0628\u0629 \u0647\u0627\u0626\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0641\u0631\u062F\u0627\u062A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u062A\u0643\u062A\u0628 \u0628\u0627\u0644\u0644\u0627\u062A\u064A\u0646\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0633\u0648\u0627\u062D\u064A\u0644\u064A\u0629 (Kiswahili)", explanation: "\u0646\u0634\u0623\u062A \u0627\u0644\u0633\u0648\u0627\u062D\u064A\u0644\u064A\u0629 \u0645\u0646 \u062A\u0645\u0627\u0632\u062C \u0644\u063A\u0627\u062A \u0627\u0644\u0628\u0627\u0646\u062A\u0648 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u0645\u0639 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0639\u0628\u0631 \u0642\u0631\u0648\u0646 \u0645\u0646 \u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629.", source: "\u0623\u0635\u0648\u0644 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u062A\u0645\u062A\u0644\u0643 \u0623\u0643\u0628\u0631 \u062A\u0646\u0648\u0639 \u0644\u063A\u0648\u064A \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u0628\u0623\u0643\u062B\u0631 \u0645\u0646 800 \u0644\u063A\u0629 \u062D\u064A\u0629 \u0645\u0646\u0637\u0648\u0642\u0629\u061F", correctAnswer: "\u0628\u0627\u0628\u0648\u0627 \u063A\u064A\u0646\u064A\u0627 \u0627\u0644\u062C\u062F\u064A\u062F\u0629 (Papua New Guinea)", explanation: "\u062A\u0636\u0627\u0631\u064A\u0633 \u0628\u0627\u0628\u0648\u0627 \u063A\u064A\u0646\u064A\u0627 \u0627\u0644\u0648\u0639\u0631\u0629 \u0639\u0632\u0644\u062A \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0644\u0623\u0644\u0648\u0641 \u0627\u0644\u0633\u0646\u064A\u0646 \u0645\u0645\u0627 \u0623\u0648\u062C\u062F \u0623\u0643\u062B\u0631 \u0645\u0646 840 \u0644\u063A\u0629 \u0645\u0633\u062A\u0642\u0644\u0629.", source: "\u0645\u0624\u0633\u0633\u0629 \u0625\u062B\u0646\u0648\u0644\u0648\u062C \u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062E\u0637 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0627\u0644\u0642\u062F\u064A\u0645 \u0627\u0644\u0630\u064A \u0643\u064F\u062A\u0628\u062A \u0628\u0647 \u0646\u0642\u0648\u0634 \u0627\u0644\u062D\u0636\u0627\u0631\u0627\u062A \u0627\u0644\u064A\u0645\u0646\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 (\u0633\u0628\u0623 \u0648\u062D\u0645\u064A\u0631 \u0648\u0642\u062A\u0628\u0627\u0646)\u061F", correctAnswer: "\u062E\u0637 \u0627\u0644\u0645\u0633\u0646\u062F (\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0645\u0633\u0646\u062F)", explanation: "\u0627\u0644\u0645\u0633\u0646\u062F \u0647\u0648 \u062E\u0637 \u0639\u0631\u0628\u064A \u062C\u0646\u0648\u0628\u064A \u0642\u062F\u064A\u0645 \u0645\u062A\u0641\u0631\u0639 \u0645\u0646 \u0627\u0644\u0623\u0628\u062C\u062F\u064A\u0629 \u0627\u0644\u0633\u064A\u0646\u0627\u0626\u064A\u0629 \u0648\u0644\u0647 29 \u062D\u0631\u0641\u0627\u064B \u0635\u0627\u0645\u062A\u0627\u064B.", source: "\u0627\u0644\u0646\u0642\u0648\u0634 \u0648\u0627\u0644\u0622\u062B\u0627\u0631 \u0627\u0644\u0633\u0627\u0645\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0644\u063A\u0629 \u0627\u0644\u0635\u0641\u064A\u0631 \u0627\u0644\u0646\u0627\u062F\u0631\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0639\u0628\u0631 \u0627\u0644\u0648\u062F\u064A\u0627\u0646 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0641\u064A \u062C\u0632\u064A\u0631\u0629 \u0644\u0627 \u063A\u0648\u0645\u064A\u0631\u0627 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0628\u062C\u0632\u0631 \u0627\u0644\u0643\u0646\u0627\u0631\u064A \u0648\u0627\u0644\u0645\u062D\u0645\u064A\u0629 \u0645\u0646 \u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648\u061F", correctAnswer: "\u0644\u063A\u0629 \u0627\u0644\u0633\u064A\u0644\u0628\u0648 \u063A\u0648\u0645\u064A\u0631\u0648 (Silbo Gomero)", explanation: "\u064A\u062D\u0627\u0643\u064A \u0635\u0641\u064A\u0631 \u0627\u0644\u0633\u064A\u0644\u0628\u0648 \u0645\u0642\u0627\u0637\u0639 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0644\u062A\u0645\u0643\u064A\u0646 \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0639\u0628\u0631 \u0627\u0644\u0648\u062F\u064A\u0627\u0646 \u0644\u0639\u062F\u0629 \u0643\u064A\u0644\u0648\u0645\u062A\u0631\u0627\u062A.", source: "\u0627\u0644\u064A\u0648\u0646\u0633\u0643\u0648 \u0644\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u062B\u0642\u0627\u0641\u064A \u0627\u0644\u0644\u0627\u0645\u0627\u062F\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u0647\u062C\u064A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0642\u0644\u0628 \u0627\u0644\u0639\u064A\u0646 \u0646\u0648\u0646\u0627\u064B \u0639\u0646\u062F \u0648\u0642\u0648\u0639\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0628\u0639\u062F \u0647\u0645\u0632\u0629 \u0643\u0642\u0648\u0644\u0647\u0645 \xAB\u0623\u0646\u0637\u0649\xBB \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \xAB\u0623\u0639\u0637\u0649\xBB\u061F", correctAnswer: "\u0627\u0644\u0627\u0633\u062A\u0646\u0637\u0627\u0621", explanation: "\u0627\u0644\u0627\u0633\u062A\u0646\u0637\u0627\u0621 \u0644\u063A\u0629 \u0633\u0639\u062F \u0628\u0646 \u0628\u0643\u0631 \u0648\u0647\u0630\u064A\u0644 \u0648\u0642\u064A\u0633 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060C \u0648\u0642\u0631\u0623 \u0628\u0647\u0627 \u0628\u0639\u0636 \u0627\u0644\u0642\u0631\u0627\u0621: (\u0625\u0646\u0627 \u0623\u0646\u0637\u064A\u0646\u0627\u0643 \u0627\u0644\u0643\u0648\u062B\u0631).", source: "\u0627\u0644\u0644\u0633\u0627\u0646 \u0648\u0627\u0644\u0645\u0632\u0647\u0631 \u0644\u0644\u0633\u064A\u0648\u0637\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0645\u0635\u0637\u0646\u0639\u0629 \u0627\u0644\u062A\u064A \u0627\u0628\u062A\u0643\u0631\u0647\u0627 \u0644\u0648\u062F\u0641\u064A\u0643 \u0632\u0627\u0645\u0646\u0647\u0648\u0641 \u0639\u0627\u0645 1887 \u0644\u062A\u0643\u0648\u0646 \u0644\u063A\u0629 \u062A\u0648\u0627\u0635\u0644 \u062B\u0627\u0646\u064A\u0629 \u0633\u0647\u0644\u0629 \u0648\u0645\u062D\u0627\u064A\u062F\u0629 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0628\u0634\u0631\u061F", correctAnswer: "\u0644\u063A\u0629 \u0627\u0644\u0625\u0633\u0628\u0631\u0627\u0646\u062A\u0648 (Esperanto)", explanation: "\u0635\u0645\u0645 \u0632\u0627\u0645\u0646\u0647\u0648\u0641 \u0627\u0644\u0625\u0633\u0628\u0631\u0627\u0646\u062A\u0648 \u0628\u0642\u0648\u0627\u0639\u062F \u0645\u0628\u0633\u0637\u0629 \u0644\u0644\u063A\u0627\u064A\u0629 \u0648\u062C\u0630\u0648\u0631 \u0645\u0634\u062A\u0631\u0643\u0629 \u0644\u062A\u0633\u0647\u064A\u0644 \u0627\u0644\u062A\u0641\u0627\u0647\u0645 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0628\u064A\u0646 \u0627\u0644\u0634\u0639\u0648\u0628.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0645\u0635\u0637\u0646\u0639\u0629" }
      ],
      "\u062E\u0631\u0627\u0626\u0637": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u062A\u062C\u0627\u0647 \u0627\u0644\u0623\u0633\u0627\u0633\u064A \u0627\u0644\u0630\u064A \u064A\u0634\u064A\u0631 \u0625\u0644\u064A\u0647 \u0631\u0623\u0633 \u0627\u0644\u0633\u0647\u0645 \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A \u0641\u064A \u0645\u0639\u0638\u0645 \u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0627\u062A\u062C\u0627\u0647 \u0627\u0644\u0634\u0645\u0627\u0644 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A", explanation: "\u062A\u0648\u062C\u0647 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u062A\u0642\u0644\u064A\u062F\u064A\u0627\u064B \u0628\u062D\u064A\u062B \u064A\u0643\u0648\u0646 \u0627\u0644\u0634\u0645\u0627\u0644 \u0641\u064A \u0627\u0644\u0623\u0639\u0644\u0649 \u0648\u0627\u0644\u062C\u0646\u0648\u0628 \u0641\u064A \u0627\u0644\u0623\u0633\u0641\u0644.", source: "\u0623\u0633\u0633 \u0627\u0644\u0643\u0627\u0631\u062A\u0648\u063A\u0631\u0627\u0641\u064A\u0627" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062E\u0637 \u0627\u0644\u0648\u0647\u0645\u064A \u0627\u0644\u0623\u0641\u0642\u064A \u0627\u0644\u0630\u064A \u064A\u0642\u0633\u0645 \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0623\u0631\u0636\u064A\u0629 \u0625\u0644\u0649 \u0646\u0635\u0641\u064A\u0646 \u0634\u0645\u0627\u0644\u064A \u0648\u062C\u0646\u0648\u0628\u064A \u0648\u062F\u0631\u062C\u062A\u0647 \u0635\u0641\u0631\u061F", correctAnswer: "\u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621 (Equator)", explanation: "\u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621 \u0647\u0648 \u062F\u0627\u0626\u0631\u0629 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u0648\u062A\u0642\u0639 \u0639\u0646\u062F \u062E\u0637 \u0639\u0631\u0636 \u0635\u0641\u0631 \u062F\u0631\u062C\u0629.", source: "\u0645\u0628\u0627\u062F\u0626 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627\u0630\u0627 \u064A\u0633\u0645\u0649 \u0627\u0644\u0631\u0645\u0632 \u0623\u0648 \u0627\u0644\u0635\u0646\u062F\u0648\u0642 \u0627\u0644\u062A\u0648\u0636\u064A\u062D\u064A \u0627\u0644\u0630\u064A \u064A\u0641\u0633\u0631 \u0645\u0639\u0627\u0646\u064A \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0641\u064A \u0627\u0644\u062E\u0631\u064A\u0637\u0629\u061F", correctAnswer: "\u0645\u0641\u062A\u0627\u062D \u0627\u0644\u062E\u0631\u064A\u0637\u0629 (\u062F\u0644\u064A\u0644 \u0627\u0644\u062E\u0631\u064A\u0637\u0629 / Legend)", explanation: "\u064A\u0648\u0636\u062D \u0645\u0641\u062A\u0627\u062D \u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0644\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u062F\u0644\u0627\u0644\u0627\u062A \u0627\u0644\u062E\u0637\u0648\u0637 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0646\u0642\u0627\u0637 \u0627\u0644\u0645\u0631\u0633\u0648\u0645\u0629.", source: "\u0639\u0644\u0645 \u0627\u0644\u062E\u0631\u0627\u0626\u0637" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627\u0630\u0627 \u062A\u0633\u0645\u0649 \u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0631\u064A\u0627\u0636\u064A\u0629 \u0628\u064A\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0627\u0633\u0629 \u0639\u0644\u0649 \u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u062D\u0642\u064A\u0642\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u0637\u0628\u064A\u0639\u0629\u061F", correctAnswer: "\u0645\u0642\u064A\u0627\u0633 \u0627\u0644\u0631\u0633\u0645 (Scale)", explanation: "\u0645\u0642\u064A\u0627\u0633 \u0627\u0644\u0631\u0633\u0645 \u064A\u062D\u062F\u062F \u0646\u0633\u0628\u0629 \u0627\u0644\u062A\u0635\u063A\u064A\u0631 \u0645\u062B\u0644 1:50,000 \u0633\u0645.", source: "\u0627\u0644\u0645\u0633\u0627\u062D\u0629 \u0648\u0627\u0644\u062E\u0631\u0627\u0626\u0637" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0623\u064A \u0644\u0648\u0646 \u064A\u0645\u062B\u0644 \u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u0633\u0637\u062D\u0627\u062A \u0627\u0644\u0645\u0627\u0626\u064A\u0629 (\u0627\u0644\u0628\u062D\u0627\u0631 \u0648\u0627\u0644\u0645\u062D\u064A\u0637\u0627\u062A \u0648\u0627\u0644\u0623\u0646\u0647\u0627\u0631) \u0639\u0644\u0649 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u0632\u0631\u0642", explanation: "\u064A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u0632\u0631\u0642 \u0628\u062A\u062F\u0631\u062C\u0627\u062A\u0647 \u0644\u062A\u0645\u062B\u064A\u0644 \u0639\u0645\u0642 \u0648\u0627\u0645\u062A\u062F\u0627\u062F \u0627\u0644\u0645\u0633\u0637\u062D\u0627\u062A \u0627\u0644\u0645\u0627\u0626\u064A\u0629 \u0627\u0635\u0637\u0644\u0627\u062D\u0627\u064B.", source: "\u0627\u0635\u0637\u0644\u0627\u062D\u0627\u062A \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u062F\u0648\u0644\u064A\u0629" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u0623\u0634\u0647\u0631 \u0645\u0633\u0642\u0637 \u062E\u0631\u0627\u0626\u0637\u064A \u0623\u0633\u0637\u0648\u0627\u0646\u064A \u0627\u0628\u062A\u0643\u0631\u0647 \u062C\u064A\u0631\u0627\u0631\u062F\u0648\u0633 \u0645\u064A\u0631\u0643\u0627\u062A\u0648\u0631 \u0639\u0627\u0645 1569 \u0648\u064A\u0633\u062A\u062E\u062F\u0645 \u0644\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629\u061F", correctAnswer: "\u0645\u0633\u0642\u0637 \u0645\u064A\u0631\u0643\u0627\u062A\u0648\u0631 (Mercator Projection)", explanation: "\u064A\u062D\u0627\u0641\u0638 \u0645\u0633\u0642\u0637 \u0645\u064A\u0631\u0643\u0627\u062A\u0648\u0631 \u0639\u0644\u0649 \u0635\u062D\u0629 \u0627\u0644\u0632\u0648\u0627\u064A\u0627 \u0648\u0627\u0644\u0627\u062A\u062C\u0627\u0647\u0627\u062A \u0648\u0644\u0643\u0646\u0647 \u064A\u0636\u062E\u0645 \u0645\u0633\u0627\u062D\u0627\u062A \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0642\u0637\u0628\u064A\u0629 \u0643\u063A\u0631\u064A\u0646\u0644\u0627\u0646\u062F.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0643\u0627\u0631\u062A\u0648\u063A\u0631\u0627\u0641\u064A\u0627" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627\u0630\u0627 \u062A\u0633\u0645\u0649 \u0627\u0644\u062E\u0637\u0648\u0637 \u0627\u0644\u0648\u0647\u0645\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0637\u0628\u0648\u063A\u0631\u0627\u0641\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u0628\u0637 \u0628\u064A\u0646 \u0627\u0644\u0646\u0642\u0627\u0637 \u0627\u0644\u0645\u062A\u0633\u0627\u0648\u064A\u0629 \u0641\u064A \u0627\u0644\u0627\u0631\u062A\u0641\u0627\u0639 \u0639\u0646 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631\u061F", correctAnswer: "\u062E\u0637\u0648\u0637 \u0627\u0644\u0643\u0646\u062A\u0648\u0631 (Contour lines)", explanation: "\u062A\u0642\u0627\u0631\u0628 \u062E\u0637\u0648\u0637 \u0627\u0644\u0643\u0646\u062A\u0648\u0631 \u064A\u0639\u0628\u0631 \u0639\u0646 \u0627\u0644\u0627\u0646\u062D\u062F\u0627\u0631 \u0627\u0644\u0634\u062F\u064A\u062F \u0648\u062A\u0628\u0627\u0639\u062F\u0647\u0627 \u064A\u0639\u0628\u0631 \u0639\u0646 \u062A\u0636\u0627\u0631\u064A\u0633 \u0645\u0646\u0628\u0633\u0637\u0629.", source: "\u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0637\u0628\u0648\u063A\u0631\u0627\u0641\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0645\u062E\u062A\u0635\u0631 \u0644\u0646\u0638\u0627\u0645 \u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0639\u0627\u0644\u0645\u064A \u0639\u0628\u0631 \u0627\u0644\u0623\u0642\u0645\u0627\u0631 \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0641\u064A \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0630\u0643\u064A\u0629\u061F", correctAnswer: "GPS (Global Positioning System)", explanation: "\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0641\u0636\u0627\u0626\u064A \u0627\u0644\u0630\u064A \u0637\u0648\u0631\u062A\u0647 \u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u062F\u0641\u0627\u0639 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0648\u0623\u0635\u0628\u062D \u0645\u062A\u0627\u062D\u0627\u064B \u0644\u0644\u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0645\u062F\u0646\u064A\u0629.", source: "\u0646\u0638\u0645 \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0641\u0636\u0627\u0626\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u0627\u0644\u0645\u062F\u0627\u0631 \u0627\u0644\u0648\u0647\u0645\u064A \u0627\u0644\u0648\u0627\u0642\u0639 \u0639\u0646\u062F \u062F\u0627\u0626\u0631\u0629 \u0639\u0631\u0636 23.5 \u062F\u0631\u062C\u0629 \u0634\u0645\u0627\u0644 \u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621\u061F", correctAnswer: "\u0645\u062F\u0627\u0631 \u0627\u0644\u0633\u0631\u0637\u0627\u0646 (Tropic of Cancer)", explanation: "\u0645\u062F\u0627\u0631 \u0627\u0644\u0633\u0631\u0637\u0627\u0646 \u064A\u0645\u0631 \u0639\u0628\u0631 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0645\u0635\u0631 \u0648\u0627\u0644\u0647\u0646\u062F \u0648\u0647\u0648 \u0623\u0642\u0635\u0649 \u0646\u0642\u0637\u0629 \u0634\u0645\u0627\u0644\u064A\u0629 \u062A\u062A\u0639\u0627\u0645\u062F \u0639\u0644\u064A\u0647\u0627 \u0627\u0644\u0634\u0645\u0633.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0641\u0644\u0643\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u0627\u0644\u0645\u062F\u0627\u0631 \u0627\u0644\u0648\u0647\u0645\u064A \u0627\u0644\u0648\u0627\u0642\u0639 \u0639\u0646\u062F \u062F\u0627\u0626\u0631\u0629 \u0639\u0631\u0636 23.5 \u062F\u0631\u062C\u0629 \u062C\u0646\u0648\u0628 \u062E\u0637 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0621\u061F", correctAnswer: "\u0645\u062F\u0627\u0631 \u0627\u0644\u062C\u062F\u064A (Tropic of Capricorn)", explanation: "\u0645\u062F\u0627\u0631 \u0627\u0644\u062C\u062F\u064A \u0647\u0648 \u0623\u0642\u0635\u0649 \u0646\u0642\u0637\u0629 \u062C\u0646\u0648\u0628\u064A\u0629 \u062A\u062A\u0639\u0627\u0645\u062F \u0639\u0644\u064A\u0647\u0627 \u0623\u0634\u0639\u0629 \u0627\u0644\u0634\u0645\u0633 \u062E\u0644\u0627\u0644 \u0627\u0644\u0627\u0646\u0642\u0644\u0627\u0628 \u0627\u0644\u0634\u062A\u0648\u064A \u0627\u0644\u0634\u0645\u0627\u0644\u064A.", source: "\u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0641\u0644\u0643\u064A\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0645\u0633\u0644\u0645 \u0627\u0644\u0630\u064A \u0631\u0633\u0645 \u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0644\u0644\u0645\u0644\u0643 \u0631\u0648\u062C\u0631 \u0627\u0644\u062B\u0627\u0646\u064A \u0627\u0644\u0635\u0642\u0644\u064A \u0648\u0648\u0636\u0639 \u0627\u0644\u062C\u0646\u0648\u0628 \u0641\u064A \u0627\u0644\u0623\u0639\u0644\u0649\u061F", correctAnswer: "\u0627\u0644\u0634\u0631\u064A\u0641 \u0627\u0644\u0625\u062F\u0631\u064A\u0633\u064A", explanation: "\u0631\u0633\u0645 \u0627\u0644\u0625\u062F\u0631\u064A\u0633\u064A \u0643\u062A\u0627\u0628 \xAB\u0646\u0632\u0647\u0629 \u0627\u0644\u0645\u0634\u062A\u0627\u0642 \u0641\u064A \u0627\u062E\u062A\u0631\u0627\u0642 \u0627\u0644\u0622\u0641\u0627\u0642\xBB \u0648\u0642\u062F\u0645 \u0623\u062F\u0642 \u062E\u0631\u064A\u0637\u0629 \u0643\u0631\u0648\u064A\u0629 \u0644\u0644\u0639\u0627\u0644\u0645 \u0641\u064A \u0627\u0644\u0639\u0635\u0648\u0631 \u0627\u0644\u0648\u0633\u0637\u0649.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0627 \u0639\u0646\u062F \u0627\u0644\u0645\u0633\u0644\u0645\u064A\u0646" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u062E\u0637 \u0627\u0644\u0637\u0648\u0644 \u0627\u0644\u0648\u0647\u0645\u064A (180 \u062F\u0631\u062C\u0629) \u0627\u0644\u0630\u064A \u064A\u062A\u063A\u064A\u0631 \u0639\u0646\u062F\u0647 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062A\u0642\u0648\u064A\u0645\u064A \u0628\u0645\u0642\u062F\u0627\u0631 \u064A\u0648\u0645 \u0643\u0627\u0645\u0644 \u0639\u0646\u062F \u062A\u062C\u0627\u0648\u0632\u0647\u061F", correctAnswer: "\u062E\u0637 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062F\u0648\u0644\u064A (International Date Line)", explanation: "\u064A\u0645\u0631 \u062E\u0637 \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062F\u0648\u0644\u064A \u0639\u0628\u0631 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0648\u064A\u062A\u0639\u0631\u062C \u0644\u062A\u0641\u0627\u062F\u064A \u062A\u0642\u0633\u064A\u0645 \u0627\u0644\u0623\u064A\u0627\u0645 \u062F\u0627\u062E\u0644 \u0627\u0644\u062F\u0648\u0644.", source: "\u0627\u0644\u0645\u0648\u0627\u0642\u064A\u062A \u0648\u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u062E\u062A\u0635\u0627\u0631 \u0627\u0644\u0634\u0627\u0626\u0639 \u0644\u0646\u0638\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u0627\u0644\u062C \u0648\u062A\u062D\u0644\u0644 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0643\u0627\u0646\u064A\u0629 \u0628\u0627\u0644\u062D\u0627\u0633\u0648\u0628\u061F", correctAnswer: "GIS (Geographic Information Systems)", explanation: "\u062A\u0642\u0646\u064A\u0629 \u062D\u0627\u0633\u0648\u0628\u064A\u0629 \u0644\u0631\u0628\u0637 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0648\u0635\u0641\u064A\u0629 \u0628\u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0631\u0642\u0645\u064A\u0629.", source: "\u0639\u0644\u0648\u0645 \u0646\u0638\u0645 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u0631\u0636 \u0627\u0644\u062D\u062F\u0648\u062F \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 \u0628\u064A\u0646 \u0627\u0644\u062F\u0648\u0644\u060C \u0648\u0627\u0644\u0639\u0648\u0627\u0635\u0645\u060C \u0648\u0627\u0644\u0645\u062F\u0646 \u0627\u0644\u0643\u0628\u0631\u0649\u061F", correctAnswer: "\u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 (Political Map)", explanation: "\u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0633\u064A\u0627\u0633\u064A\u0629 \u062A\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u062D\u062F\u0648\u062F \u0627\u0644\u0625\u062F\u0627\u0631\u064A\u0629 \u0648\u0627\u0644\u0633\u064A\u0627\u062F\u064A\u0629 \u0628\u062E\u0644\u0627\u0641 \u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629 \u0627\u0644\u062A\u0636\u0627\u0631\u064A\u0633\u064A\u0629.", source: "\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062E\u0631\u0627\u0626\u0637" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0633\u0642\u0637 \u0627\u0644\u062E\u0631\u0627\u0626\u0637\u064A \u0627\u0644\u0628\u062F\u064A\u0644 \u0627\u0644\u0630\u064A \u0627\u0628\u062A\u0643\u0631\u0647 \u0623\u0631\u0646\u0648 \u0628\u064A\u062A\u0631\u0632 \u0644\u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0645\u0633\u0627\u062D\u0627\u062A \u0627\u0644\u0646\u0633\u0628\u064A\u0629 \u0627\u0644\u062D\u0642\u064A\u0642\u064A\u0629 \u0644\u0644\u0642\u0627\u0631\u0627\u062A \u0628\u062F\u0648\u0646 \u062A\u0636\u062E\u064A\u0645 \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u0634\u0645\u0627\u0644\u064A\u0629\u061F", correctAnswer: "\u0645\u0633\u0642\u0637 \u063A\u0627\u0644-\u0628\u064A\u062A\u0631\u0632 (Gall-Peters projection)", explanation: "\u064A\u062D\u0627\u0641\u0638 \u0645\u0633\u0642\u0637 \u063A\u0627\u0644-\u0628\u064A\u062A\u0631\u0632 \u0639\u0644\u0649 \u062A\u0643\u0627\u0641\u0624 \u0627\u0644\u0645\u0633\u0627\u062D\u0627\u062A \u0648\u064A\u0639\u0637\u064A \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0623\u0628\u0639\u0627\u062F\u0647\u0627 \u0627\u0644\u062D\u0642\u064A\u0642\u064A\u0629.", source: "\u0645\u0633\u0627\u0642\u0637 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u062D\u062F\u064A\u062B\u0629" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0642\u0628\u0637\u0627\u0646 \u0648\u0627\u0644\u0628\u062D\u0627\u0631 \u0627\u0644\u0639\u062B\u0645\u0627\u0646\u064A \u0627\u0644\u0630\u064A \u0631\u0633\u0645 \u062E\u0631\u064A\u0637\u0629 \u062F\u0642\u064A\u0642\u0629 \u0645\u062F\u0647\u0634\u0629 \u0644\u0633\u0648\u0627\u062D\u0644 \u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0648\u0627\u0644\u0642\u0627\u0631\u0629 \u0627\u0644\u0642\u0637\u0628\u064A\u0629 \u0639\u0627\u0645 1513\u061F", correctAnswer: "\u0628\u064A\u0631\u064A \u0631\u064A\u0633 (Piri Reis)", explanation: "\u062E\u0631\u064A\u0637\u0629 \u0628\u064A\u0631\u064A \u0631\u064A\u0633 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0639\u062B\u0631 \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0642\u0635\u0631 \u062A\u0648\u0628\u0643\u0627\u0628\u064A \u0639\u0627\u0645 1929 \u0648\u062A\u0639\u062F \u062A\u062D\u0641\u0629 \u0645\u0644\u0627\u062D\u064A\u0629 \u0643\u0627\u0631\u062A\u0648\u063A\u0631\u0627\u0641\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0639\u062B\u0645\u0627\u0646\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0635\u0637\u0644\u062D \u0627\u0644\u0630\u064A \u064A\u064F\u0637\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0625\u062D\u0635\u0627\u0626\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u062A\u062E\u062F\u0645 \u062A\u062F\u0631\u062C\u0627\u062A \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0623\u0648 \u0627\u0644\u062A\u0638\u0644\u064A\u0644 \u0644\u0644\u062A\u0639\u0628\u064A\u0631 \u0639\u0646 \u0643\u062B\u0627\u0641\u0629 \u0645\u0639\u064A\u0646\u0629 (\u0643\u0627\u0644\u0641\u0642\u0631 \u0623\u0648 \u0627\u0644\u0633\u0643\u0627\u0646)\u061F", correctAnswer: "\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0643\u0648\u0631\u0648\u0628\u0644\u064A\u062B (Choropleth Map)", explanation: "\u062A\u0633\u062A\u062E\u062F\u0645 \u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0643\u0648\u0631\u0648\u0628\u0644\u064A\u062B \u0645\u0646\u0627\u0637\u0642 \u0645\u062D\u062F\u062F\u0629 \u0625\u062D\u0635\u0627\u0626\u064A\u0627\u064B \u0648\u062A\u0644\u0648\u0646\u0647\u0627 \u0648\u0641\u0642 \u062A\u062F\u0631\u062C \u0639\u062F\u062F\u064A \u0645\u062A\u0646\u0627\u0633\u0628.", source: "\u0627\u0644\u0643\u0627\u0631\u062A\u0648\u063A\u0631\u0627\u0641\u064A\u0627 \u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0646\u0638\u0631\u064A\u0629 \u0627\u0644\u062C\u063A\u0631\u0627\u0641\u064A\u0629 \u0648\u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0629 \u0627\u0644\u062A\u064A \u0642\u062F\u0645\u0647\u0627 \u0623\u0644\u0641\u0631\u064A\u062F \u0641\u064A\u062C\u0646\u0631 \u0639\u0627\u0645 1912 \u0644\u062A\u0641\u0633\u064A\u0631 \u062A\u0637\u0627\u0628\u0642 \u0633\u0648\u0627\u062D\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629\u061F", correctAnswer: "\u0646\u0638\u0631\u064A\u0629 \u0627\u0644\u0627\u0646\u062C\u0631\u0627\u0641 \u0627\u0644\u0642\u0627\u0631\u064A (\u0632\u062D\u0632\u062D\u0629 \u0627\u0644\u0642\u0627\u0631\u0627\u062A / Continental Drift)", explanation: "\u0627\u0641\u062A\u0631\u0636 \u0641\u064A\u062C\u0646\u0631 \u0623\u0646 \u0627\u0644\u0642\u0627\u0631\u0627\u062A \u0643\u0627\u0646\u062A \u0643\u062A\u0644\u0629 \u0648\u0627\u062D\u062F\u0629 \u0639\u0645\u0644\u0627\u0642\u0629 \u062A\u0633\u0645\u0649 \xAB\u0628\u0627\u0646\u062C\u064A\u0627\xBB \u062B\u0645 \u0627\u0646\u0641\u0635\u0644\u062A \u062A\u062F\u0631\u064A\u062C\u064A\u0627\u064B.", source: "\u062A\u0627\u0631\u064A\u062E \u0639\u0644\u0648\u0645 \u0627\u0644\u0623\u0631\u0636" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0642\u062F\u0645 \u062E\u0631\u064A\u0637\u0629 \u062C\u063A\u0631\u0627\u0641\u064A\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0628\u0634\u0631\u064A \u0645\u0646\u0642\u0648\u0634\u0629 \u0639\u0644\u0649 \u0644\u0648\u062D \u0645\u0646 \u0627\u0644\u0637\u064A\u0646 \u0648\u0639\u062B\u0631 \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0628\u0627\u0628\u0644\u061F", correctAnswer: "\u062E\u0631\u064A\u0637\u0629 \u0628\u0627\u0628\u0644 \u0644\u0644\u0639\u0627\u0644\u0645 (Imago Mundi)", explanation: "\u0644\u0648\u062D \u0637\u064A\u0646\u064A \u0628\u0627\u0628\u0644\u064A \u064A\u0639\u0648\u062F \u0644\u0644\u0642\u0631\u0646 \u0627\u0644\u0633\u0627\u062F\u0633 \u0642\u0628\u0644 \u0627\u0644\u0645\u064A\u0644\u0627\u062F \u064A\u0645\u062B\u0644 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0645\u062D\u0627\u0637\u0627\u064B \u0628\u0646\u0647\u0631 \u0645\u0627\u0644\u062D \u062F\u0627\u0626\u0631\u064A.", source: "\u0627\u0644\u0645\u062A\u062D\u0641 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u062C\u064A\u0648\u062F\u064A\u0633\u064A \u0627\u0644\u0645\u0631\u062C\u0639\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u064A \u0627\u0644\u0645\u0639\u062A\u0645\u062F \u0643\u0645\u0639\u064A\u0627\u0631 \u0625\u062D\u062F\u0627\u062B\u064A\u0627\u062A \u0644\u0645\u0639\u0638\u0645 \u0628\u0631\u0627\u0645\u062C \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0648\u0627\u0644\u0640 GPS\u061F", correctAnswer: "WGS 84 (World Geodetic System 1984)", explanation: "WGS 84 \u0647\u0648 \u0627\u0644\u0625\u0647\u0644\u064A\u0644\u062C \u0627\u0644\u0645\u0631\u062C\u0639\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u064A \u0644\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u062B\u0644\u0627\u062B\u064A\u0629 \u0627\u0644\u0623\u0628\u0639\u0627\u062F \u0639\u0644\u0649 \u0633\u0637\u062D \u0627\u0644\u0623\u0631\u0636 \u0628\u062F\u0642\u0629.", source: "\u0627\u0644\u0645\u0633\u062D \u0627\u0644\u062C\u064A\u0648\u062F\u064A\u0633\u064A \u0627\u0644\u062F\u0648\u0644\u064A" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0646\u0638\u0631\u064A\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0641\u064A \u0639\u0644\u0645 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0648\u0627\u0644\u0631\u064A\u0627\u0636\u064A\u0627\u062A \u0627\u0644\u062A\u064A \u062A\u0645 \u0625\u062B\u0628\u0627\u062A\u0647\u0627 \u062D\u0627\u0633\u0648\u0628\u064A\u0627\u064B \u0639\u0627\u0645 1976\u061F", correctAnswer: "\u0645\u0628\u0631\u0647\u0646\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 (Four Color Theorem)", explanation: "\u062A\u0646\u0635 \u0627\u0644\u0645\u0628\u0631\u0647\u0646\u0629 \u0639\u0644\u0649 \u0623\u0646 \u0623\u0631\u0628\u0639\u0629 \u0623\u0644\u0648\u0627\u0646 \u0641\u0642\u0637 \u062A\u0643\u0641\u064A \u0644\u062A\u0644\u0648\u064A\u0646 \u0623\u064A \u062E\u0631\u064A\u0637\u0629 \u0628\u062D\u064A\u062B \u0644\u0627 \u062A\u062A\u062C\u0627\u0648\u0631 \u0645\u0646\u0637\u0642\u062A\u0627\u0646 \u0628\u0646\u0641\u0633 \u0627\u0644\u0644\u0648\u0646.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0631\u064A\u0627\u0636\u064A\u0627\u062A \u0648\u0627\u0644\u0643\u0627\u0631\u062A\u0648\u063A\u0631\u0627\u0641\u064A\u0627" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0646\u0648\u0639 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u062A\u064A \u0627\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0628\u062D\u0627\u0631\u0629 \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0641\u064A \u0627\u0644\u0642\u0631\u0648\u0646 \u0627\u0644\u0648\u0633\u0637\u0649 \u0648\u0627\u0644\u0645\u0632\u064A\u0646\u0629 \u0628\u062E\u0637\u0648\u0637 \u0627\u0644\u0631\u064A\u0627\u062D \u0648\u062A\u0633\u0645\u0649 Portolan Charts\u061F", correctAnswer: "\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0628\u0648\u0631\u062A\u0648\u0644\u0627\u0646 (\u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0645\u0648\u0627\u0646\u0626 \u0627\u0644\u0645\u0644\u0627\u062D\u064A\u0629)", explanation: "\u062A\u0645\u064A\u0632\u062A \u062E\u0631\u0627\u0626\u0637 \u0627\u0644\u0628\u0648\u0631\u062A\u0648\u0644\u0627\u0646 \u0628\u0634\u0628\u0643\u0629 \u062E\u0637\u0648\u0637 \u0627\u0644\u0628\u0648\u0635\u0644\u0629 (Rhumb lines) \u0644\u062A\u0648\u062C\u064A\u0647 \u0627\u0644\u0633\u0641\u0646 \u0628\u064A\u0646 \u0627\u0644\u0645\u0648\u0627\u0646\u0626.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u0644\u0627\u062D\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u0627\u0644\u0646\u0645\u0648\u0630\u062C \u0627\u0644\u0633\u0637\u062D\u064A \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A \u0644\u0644\u0623\u0631\u0636 \u0627\u0644\u0630\u064A \u064A\u062A\u0637\u0627\u0628\u0642 \u062A\u0645\u0627\u0645\u0627\u064B \u0645\u0639 \u0633\u0637\u062D \u0627\u0644\u0628\u062D\u0631 \u0641\u064A \u062D\u0627\u0644\u0629 \u0627\u0644\u0633\u0643\u0648\u0646 \u0648\u064A\u062A\u0623\u062B\u0631 \u0628\u0627\u0644\u062C\u0627\u0630\u0628\u064A\u0629 \u0641\u0642\u0637\u061F", correctAnswer: "\u0627\u0644\u062C\u064A\u0648\u062F (Geoid)", explanation: "\u0627\u0644\u062C\u064A\u0648\u062F \u0647\u0648 \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u0641\u064A\u0632\u064A\u0627\u0626\u064A \u0627\u0644\u062D\u0642\u064A\u0642\u064A \u0644\u0645\u062C\u0627\u0644 \u062C\u0627\u0630\u0628\u064A\u0629 \u0627\u0644\u0623\u0631\u0636 \u0648\u062A\u0639\u062A\u0645\u062F \u0639\u0644\u064A\u0647 \u0627\u0644\u0627\u0631\u062A\u0641\u0627\u0639\u0627\u062A \u0627\u0644\u0645\u0637\u0644\u0642\u0629.", source: "\u0627\u0644\u062C\u064A\u0648\u062F\u064A\u0633\u064A\u0627 \u0627\u0644\u0641\u064A\u0632\u064A\u0627\u0626\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0644\u0644\u0642\u0627\u0631\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0642\u0629 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0627\u0644\u062A\u064A \u0636\u0645\u062A \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0648\u0623\u0645\u0631\u064A\u0643\u0627 \u0627\u0644\u062C\u0646\u0648\u0628\u064A\u0629 \u0648\u0623\u0633\u062A\u0631\u0627\u0644\u064A\u0627 \u0648\u0627\u0644\u0647\u0646\u062F \u0648\u0627\u0644\u0642\u0627\u0631\u0629 \u0627\u0644\u0642\u0637\u0628\u064A\u0629 \u0628\u0639\u062F \u0627\u0646\u0642\u0633\u0627\u0645 \u0628\u0627\u0646\u062C\u064A\u0627\u061F", correctAnswer: "\u0642\u0627\u0631\u0629 \u063A\u0646\u062F\u0648\u0627\u0646\u0627 (Gondwana)", explanation: "\u0627\u0646\u0642\u0633\u0645\u062A \u0628\u0627\u0646\u062C\u064A\u0627 \u0625\u0644\u0649 \u0644\u0648\u0631\u0627\u0633\u064A\u0627 \u0641\u064A \u0627\u0644\u0634\u0645\u0627\u0644 \u0648\u063A\u0646\u062F\u0648\u0627\u0646\u0627 \u0641\u064A \u0627\u0644\u062C\u0646\u0648\u0628 \u0641\u064A \u0627\u0644\u062D\u0642\u0628\u0629 \u0627\u0644\u0648\u0633\u0637\u0649 \u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0629.", source: "\u0627\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0631\u0648\u0645\u0627\u0646\u064A\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u0628\u0627\u0642\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0635\u0648\u0631 \u0634\u0628\u0643\u0629 \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0639\u0633\u0643\u0631\u064A\u0629 \u0641\u064A \u0627\u0644\u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u064A\u0629 \u0628\u0637\u0648\u0644 6.75 \u0645\u062A\u0631\u061F", correctAnswer: "\u0644\u0648\u062D\u0629 \u0628\u0648\u064A\u062A\u064A\u0646\u063A\u0631 (Tabula Peutingeriana)", explanation: "\u0645\u062E\u0637\u0648\u0637\u0629 \u0645\u0646 \u0627\u0644\u0639\u0635\u0648\u0631 \u0627\u0644\u0648\u0633\u0637\u0649 \u0645\u0646\u0633\u0648\u062E\u0629 \u0639\u0646 \u062E\u0631\u064A\u0637\u0629 \u0631\u0648\u0645\u0627\u0646\u064A\u0629 \u062A\u0639\u0648\u062F \u0644\u0644\u0642\u0631\u0646 \u0627\u0644\u0631\u0627\u0628\u0639 \u0627\u0644\u0645\u064A\u0644\u0627\u062F\u064A \u062A\u0628\u0631\u0632 \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0645\u062D\u0637\u0627\u062A.", source: "\u0627\u0644\u0645\u0643\u062A\u0628\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0627\u0644\u0646\u0645\u0633\u0627\u0648\u064A\u0629" }
      ],
      "\u0639\u0645\u0644\u0627\u062A": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0627\u0644\u0645\u0648\u062D\u062F\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0641\u064A \u0645\u0639\u0638\u0645 \u062F\u0648\u0644 \u0627\u0644\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u061F", correctAnswer: "\u0627\u0644\u064A\u0648\u0631\u0648 (Euro)", explanation: "\u0627\u0639\u062A\u0645\u062F \u0627\u0644\u064A\u0648\u0631\u0648 \u0643\u0639\u0645\u0644\u0629 \u0645\u0635\u0631\u0641\u064A\u0629 \u0639\u0627\u0645 1999 \u0648\u0628\u062F\u0623 \u062A\u062F\u0627\u0648\u0644 \u0623\u0648\u0631\u0627\u0642\u0647 \u0648\u0646\u0642\u0648\u062F\u0647 \u0627\u0644\u0645\u0639\u062F\u0646\u064A\u0629 \u0639\u0627\u0645 2002.", source: "\u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A ECB" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0648\u062A\u0639\u062A\u0628\u0631 \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A (US Dollar)", explanation: "\u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A \u0647\u0648 \u0623\u0643\u062B\u0631 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u062A\u062F\u0627\u0648\u0644\u0627\u064B \u0641\u064A \u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0648\u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A \u0627\u0644\u062F\u0648\u0644\u064A\u0629.", source: "\u0645\u062C\u0644\u0633 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0641\u064A \u0627\u0644\u064A\u0627\u0628\u0627\u0646 \u0648\u0631\u0645\u0632\u0647\u0627 \xA5\u061F", correctAnswer: "\u0627\u0644\u064A\u0646 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u064A (Japanese Yen)", explanation: "\u0627\u0644\u064A\u0646 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u064A \u0647\u0648 \u062B\u0627\u0644\u062B \u0623\u0643\u062B\u0631 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u062A\u062F\u0627\u0648\u0644\u0627\u064B \u0641\u064A \u0633\u0648\u0642 \u0627\u0644\u0641\u0648\u0631\u0643\u0633 \u0627\u0644\u0639\u0627\u0644\u0645\u064A.", source: "\u0628\u0646\u0643 \u0627\u0644\u064A\u0627\u0628\u0627\u0646 \u0627\u0644\u0645\u0631\u0643\u0632\u064A" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 (\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627)\u061F", correctAnswer: "\u0627\u0644\u062C\u0646\u064A\u0647 \u0627\u0644\u0625\u0633\u062A\u0631\u0644\u064A\u0646\u064A (Pound Sterling)", explanation: "\u0627\u0644\u062C\u0646\u064A\u0647 \u0627\u0644\u0625\u0633\u062A\u0631\u0644\u064A\u0646\u064A \u0647\u0648 \u0623\u0642\u062F\u0645 \u0639\u0645\u0644\u0629 \u0644\u0627 \u062A\u0632\u0627\u0644 \u0645\u0633\u062A\u062E\u062F\u0645\u0629 \u0628\u0634\u0643\u0644 \u0645\u062A\u0648\u0627\u0635\u0644 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645.", source: "\u0628\u0646\u0643 \u0625\u0646\u062C\u0644\u062A\u0631\u0627" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0631\u0642\u0645\u064A\u0629 \u0627\u0644\u0645\u0634\u0641\u0631\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u062A\u064A \u0623\u0646\u0634\u0623\u0647\u0627 \u0634\u062E\u0635 \u0645\u062C\u0647\u0648\u0644 \u0628\u0627\u0633\u0645 \u0633\u0627\u062A\u0648\u0634\u064A \u0646\u0627\u0643\u0627\u0645\u0648\u062A\u0648\u061F", correctAnswer: "\u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 (Bitcoin / BTC)", explanation: "\u0623\u0637\u0644\u0642\u062A \u0639\u0645\u0644\u0629 \u0627\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646 \u0639\u0627\u0645 2009 \u0643\u0623\u0648\u0644 \u0639\u0645\u0644\u0629 \u0631\u0642\u0645\u064A\u0629 \u0644\u0627 \u0645\u0631\u0643\u0632\u064A\u0629 \u062A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u0628\u0644\u0648\u0643\u0634\u064A\u0646.", source: "\u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0628\u064A\u0636\u0627\u0621 \u0644\u0644\u0628\u064A\u062A\u0643\u0648\u064A\u0646" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0644\u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u0635\u064A\u0646 \u0627\u0644\u0634\u0639\u0628\u064A\u0629 \u0648\u062A\u0639\u0631\u0641 \u0623\u064A\u0636\u0627\u064B \u0628\u0627\u0644\u064A\u0648\u0627\u0646\u061F", correctAnswer: "\u0627\u0644\u0631\u0646\u0645\u064A\u0646\u0628\u064A (\u0627\u0644\u064A\u0648\u0627\u0646 \u0627\u0644\u0635\u064A\u0646\u064A / Renminbi - Yuan)", explanation: "\u0627\u0644\u0631\u0646\u0645\u064A\u0646\u0628\u064A \u062A\u0639\u0646\u064A \u062D\u0631\u0641\u064A\u0627\u064B \u0639\u0645\u0644\u0629 \u0627\u0644\u0634\u0639\u0628\u060C \u0648\u062A\u0639\u062F \u0648\u062D\u062F\u0629 \u0627\u0644\u062D\u0633\u0627\u0628 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0647\u064A \u0627\u0644\u064A\u0648\u0627\u0646.", source: "\u0628\u0646\u0643 \u0627\u0644\u0634\u0639\u0628 \u0627\u0644\u0635\u064A\u0646\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0644\u0631\u0648\u0633\u064A\u0627 \u0627\u0644\u0627\u062A\u062D\u0627\u062F\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u0631\u0648\u0628\u0644 \u0627\u0644\u0631\u0648\u0633\u064A (Russian Ruble)", explanation: "\u0627\u0644\u0631\u0648\u0628\u0644 \u0645\u0633\u062A\u062E\u062F\u0645 \u0643\u0639\u0645\u0644\u0629 \u0631\u0648\u0633\u064A\u0629 \u0645\u0646\u0630 \u0642\u0631\u0648\u0646 \u0637\u0648\u064A\u0644\u0629 \u0648\u0645\u0642\u0633\u0645 \u0625\u0644\u0649 100 \u0643\u0648\u0628\u064A\u0643.", source: "\u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0627\u0644\u0631\u0648\u0633\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0644\u0649 \u0641\u0626\u0629 \u0648\u0631\u0642\u064A\u0629 \u0646\u0642\u062F\u064A\u0629 \u0645\u062A\u062F\u0627\u0648\u0644\u0629 \u0645\u0637\u0628\u0648\u0639\u0629 \u062D\u0627\u0644\u064A\u0627\u064B \u0641\u064A \u0639\u0645\u0644\u0629 \u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u061F", correctAnswer: "\u0641\u0626\u0629 100 \u062F\u0648\u0644\u0627\u0631 \u0623\u0645\u0631\u064A\u0643\u064A", explanation: "\u062A\u062D\u0645\u0644 \u0648\u0631\u0642\u0629 \u0627\u0644\u0640 100 \u062F\u0648\u0644\u0627\u0631 \u0635\u0648\u0631\u0629 \u0628\u0646\u062C\u0627\u0645\u064A\u0646 \u0641\u0631\u0627\u0646\u0643\u0644\u064A\u0646\u060C \u0648\u0623\u0648\u0642\u0641\u062A \u0627\u0644\u0641\u0626\u0627\u062A \u0627\u0644\u0623\u0643\u0628\u0631 \u0631\u0633\u0645\u064A\u0627\u064B \u0639\u0627\u0645 1969.", source: "\u0645\u0643\u062A\u0628 \u0627\u0644\u0646\u0642\u0634 \u0648\u0627\u0644\u0637\u0628\u0627\u0639\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u062E\u0644\u064A\u062C\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u062A\u0628\u0631 \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0623\u0639\u0644\u0649 \u0642\u064A\u0645\u0629 \u0648\u0633\u0639\u0631\u0627\u064B \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0627\u0644\u0643\u0648\u064A\u062A\u064A (KWD)", explanation: "\u064A\u0633\u0627\u0648\u064A \u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0627\u0644\u0643\u0648\u064A\u062A\u064A \u0627\u0644\u0648\u0627\u062D\u062F \u0645\u0627 \u064A\u0642\u0627\u0631\u0628 3.25 \u062F\u0648\u0644\u0627\u0631 \u0623\u0645\u0631\u064A\u0643\u064A \u0646\u0638\u0631\u0627\u064B \u0644\u0642\u0648\u0629 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0648\u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0627\u062A.", source: "\u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u062A\u064A \u064A\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0627\u0644\u0633\u0648\u064A\u0633\u0631\u064A\u0648\u0646 \u0648\u062A\u0639\u062F \u0645\u0644\u0627\u0630\u0627\u064B \u0622\u0645\u0646\u0627\u064B \u0644\u0644\u0645\u0633\u062A\u062B\u0645\u0631\u064A\u0646 \u0641\u064A \u0627\u0644\u0623\u0632\u0645\u0627\u062A\u061F", correctAnswer: "\u0627\u0644\u0641\u0631\u0646\u0643 \u0627\u0644\u0633\u0648\u064A\u0633\u0631\u064A (Swiss Franc / CHF)", explanation: "\u0627\u0644\u0641\u0631\u0646\u0643 \u0627\u0644\u0633\u0648\u064A\u0633\u0631\u064A \u064A\u062D\u0638\u0649 \u0628\u062B\u0642\u0629 \u062F\u0648\u0644\u064A\u0629 \u0639\u0627\u0644\u064A\u0629 \u0628\u0641\u0636\u0644 \u0627\u0644\u0627\u0633\u062A\u0642\u0631\u0627\u0631 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A \u0648\u0627\u0644\u0645\u0627\u0644\u064A \u0644\u0633\u0648\u064A\u0633\u0631\u0627.", source: "\u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0648\u0637\u0646\u064A \u0627\u0644\u0633\u0648\u064A\u0633\u0631\u064A SNB" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0639\u062F\u0646 \u0627\u0644\u0646\u0641\u064A\u0633 \u0627\u0644\u0630\u064A \u0643\u0627\u0646 \u0645\u0639\u064A\u0627\u0631\u0627\u064B \u062B\u0627\u0628\u062A\u0627\u064B \u0644\u062A\u0642\u064A\u064A\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0648\u0631\u0642\u064A\u0629 \u062D\u062A\u0649 \u0625\u0644\u063A\u0627\u0626\u0647 \u0641\u064A \u0633\u0628\u0639\u064A\u0646\u064A\u0627\u062A \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0639\u0634\u0631\u064A\u0646\u061F", correctAnswer: "\u0627\u0644\u0630\u0647\u0628 (\u0645\u0639\u064A\u0627\u0631 \u0627\u0644\u0630\u0647\u0628 / Gold Standard)", explanation: "\u0643\u0627\u0646\u062A \u0627\u0644\u062F\u0648\u0644 \u0645\u0644\u0632\u0645\u0629 \u0628\u062A\u062D\u0648\u064A\u0644 \u0646\u0642\u0648\u062F\u0647\u0627 \u0644\u0648\u0632\u0646 \u062B\u0627\u0628\u062A \u0645\u0646 \u0627\u0644\u0630\u0647\u0628 \u0642\u0628\u0644 \u0625\u0646\u0647\u0627\u0621 \u0646\u0638\u0627\u0645 \u0628\u0631\u064A\u062A\u0648\u0646 \u0648\u0648\u062F\u0632 \u0639\u0627\u0645 1971.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0627\u0644\u0646\u0642\u062F\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0642\u0631\u0627\u0631 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A \u0627\u0644\u0630\u064A \u0627\u062A\u062E\u0630\u0647 \u0627\u0644\u0631\u0626\u064A\u0633 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A \u0631\u064A\u062A\u0634\u0627\u0631\u062F \u0646\u064A\u0643\u0633\u0648\u0646 \u0639\u0627\u0645 1971 \u0648\u0641\u0635\u0644 \u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0639\u0646 \u0627\u0644\u0630\u0647\u0628\u061F", correctAnswer: "\u0635\u062F\u0645\u0629 \u0646\u064A\u0643\u0633\u0648\u0646 (Nixon Shock)", explanation: "\u0623\u0639\u0644\u0646 \u0646\u064A\u0643\u0633\u0648\u0646 \u0641\u064A \u0623\u063A\u0633\u0637\u0633 1971 \u062A\u0639\u0644\u064A\u0642 \u0627\u0644\u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0644\u0644\u062F\u0648\u0644\u0627\u0631 \u0625\u0644\u0649 \u0630\u0647\u0628 \u0645\u0646\u0647\u064A\u0627\u064B \u0646\u0638\u0627\u0645 \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u062B\u0627\u0628\u062A.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0641\u064A\u062F\u0631\u0627\u0644\u064A \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u062E\u0644\u064A\u0641\u0629 \u0627\u0644\u0623\u0645\u0648\u064A \u0627\u0644\u0630\u064A \u0642\u0627\u0645 \u0628\u0623\u0648\u0644 \u062A\u0639\u0631\u064A\u0628 \u0634\u0627\u0645\u0644 \u0644\u0644\u0646\u0642\u0648\u062F \u0648\u0635\u0643 \u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u0627\u0644\u062E\u0627\u0644\u0635 \u0639\u0627\u0645 77 \u0647\u0640\u061F", correctAnswer: "\u0639\u0628\u062F \u0627\u0644\u0645\u0644\u0643 \u0628\u0646 \u0645\u0631\u0648\u0627\u0646", explanation: "\u0627\u0633\u062A\u0628\u062F\u0644 \u0639\u0628\u062F \u0627\u0644\u0645\u0644\u0643 \u0628\u0646 \u0645\u0631\u0648\u0627\u0646 \u0627\u0644\u062F\u0646\u0627\u0646\u064A\u0631 \u0627\u0644\u0628\u064A\u0632\u0646\u0637\u064A\u0629 \u0648\u0627\u0644\u0643\u0633\u0631\u0648\u064A\u0629 \u0628\u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0627\u0644\u0630\u0647\u0628\u064A \u0627\u0644\u0639\u0631\u0628\u064A \u0627\u0644\u0645\u0646\u0642\u0648\u0634 \u0628\u0622\u064A\u0627\u062A \u0627\u0644\u0642\u0631\u0622\u0646.", source: "\u0634\u0630\u0648\u0631 \u0627\u0644\u0639\u0642\u0648\u062F \u0641\u064A \u0630\u0643\u0631 \u0627\u0644\u0646\u0642\u0648\u062F \u0644\u0644\u0645\u0642\u0631\u064A\u0632\u064A" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0644\u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u0647\u0646\u062F \u0648\u062A\u062A\u0634\u0627\u0631\u0643 \u0627\u0633\u0645\u0647\u0627 \u0645\u0639 \u062F\u0648\u0644 \u0645\u062B\u0644 \u0628\u0627\u0643\u0633\u062A\u0627\u0646 \u0648\u0646\u064A\u0628\u0627\u0644\u061F", correctAnswer: "\u0627\u0644\u0631\u0648\u0628\u064A\u0629 \u0627\u0644\u0647\u0646\u062F\u064A\u0629 (Indian Rupee)", explanation: "\u0627\u0644\u0631\u0648\u0628\u064A\u0629 \u0645\u0634\u062A\u0642\u0629 \u0645\u0646 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u0633\u0646\u0633\u0643\u0631\u064A\u062A\u064A\u0629 \xAB\u0631\u0648\u0628\u064A\u0627\xBB \u0627\u0644\u062A\u064A \u062A\u0639\u0646\u064A \u0627\u0644\u0641\u0636\u0629 \u0627\u0644\u0645\u0634\u063A\u0648\u0644\u0629.", source: "\u0628\u0646\u0643 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A \u0627\u0644\u0647\u0646\u062F\u064A RBI" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0639\u062F\u0646 \u0627\u0644\u0630\u064A \u0635\u0646\u0639\u062A \u0645\u0646\u0647 \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0641\u0636\u064A\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629 \u0628\u0627\u0644\u062F\u0631\u0647\u0645\u061F", correctAnswer: "\u0627\u0644\u0641\u0636\u0629", explanation: "\u0643\u0627\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0646\u0642\u062F\u064A \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A \u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0645\u0639\u062F\u0646: \u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0645\u0646 \u0627\u0644\u0630\u0647\u0628 \u0648\u0627\u0644\u062F\u0631\u0647\u0645 \u0645\u0646 \u0627\u0644\u0641\u0636\u0629 \u0648\u0627\u0644\u0641\u0644\u0648\u0633 \u0645\u0646 \u0627\u0644\u0646\u062D\u0627\u0633.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u0633\u0643\u0648\u0643\u0627\u062A \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062D\u0636\u0627\u0631\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0641\u064A \u0622\u0633\u064A\u0627 \u0627\u0644\u0635\u063A\u0631\u0649 (\u062A\u0631\u0643\u064A\u0627 \u0627\u0644\u062D\u0627\u0644\u064A\u0629) \u0627\u0644\u062A\u064A \u0627\u0628\u062A\u0643\u0631\u062A \u0623\u0648\u0644 \u0639\u0645\u0644\u0629 \u0645\u0639\u062F\u0646\u064A\u0629 \u0645\u0633\u0643\u0648\u0643\u0629 \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0641\u064A \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0633\u0627\u0628\u0639 \u0642.\u0645\u061F", correctAnswer: "\u0645\u0645\u0644\u0643\u0629 \u0644\u064A\u062F\u064A\u0627 (Lydia)", explanation: "\u0633\u0643 \u0627\u0644\u0644\u064A\u062F\u064A\u0648\u0646 \u0641\u064A \u0639\u0647\u062F \u0627\u0644\u0645\u0644\u0643 \u0623\u0644\u064A\u0627\u062A\u0633 \u0642\u0637\u0639\u0627\u064B \u0646\u0642\u062F\u064A\u0629 \u0645\u0646 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0645 (\u062E\u0644\u064A\u0637 \u0637\u0628\u064A\u0639\u064A \u0645\u0646 \u0627\u0644\u0630\u0647\u0628 \u0648\u0627\u0644\u0641\u0636\u0629).", source: "\u0627\u0644\u0645\u062A\u062D\u0641 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A \u0648\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0645\u0633\u0643\u0648\u0643\u0627\u062A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644\u0629 \u0627\u0644\u062A\u064A \u0627\u062E\u062A\u0631\u0639\u062A \u0623\u0648\u0644 \u0646\u0642\u0648\u062F \u0648\u0631\u0642\u064A\u0629 \u0645\u062A\u062F\u0627\u0648\u0644\u0629 \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0628\u0634\u0631\u064A \u0641\u064A \u0639\u0647\u062F \u0633\u0644\u0627\u0644\u0629 \u0633\u0648\u0646\u063A \u0648\u062A\u0639\u0631\u0641 \u0628\u0640 \xAB\u062C\u064A\u0627\u0648\u0632\u064A\xBB\u061F", correctAnswer: "\u0627\u0644\u0635\u064A\u0646", explanation: "\u0638\u0647\u0631\u062A \u0623\u0648\u0631\u0627\u0642 \u0627\u0644\u062C\u064A\u0627\u0648\u0632\u064A \u0627\u0644\u0646\u0642\u062F\u064A\u0629 \u0641\u064A \u0645\u0642\u0627\u0637\u0639\u0629 \u0633\u064A\u062A\u0634\u0648\u0627\u0646 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u062D\u0627\u062F\u064A \u0639\u0634\u0631 \u0643\u0628\u062F\u064A\u0644 \u0644\u062B\u0642\u0644 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u062D\u062F\u064A\u062F\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0646\u0642\u0648\u062F \u0641\u064A \u0622\u0633\u064A\u0627" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A\u0629 \u0627\u0644\u0641\u0636\u064A\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0639\u0631\u0641\u062A \u0628\u0640 \xAB\u0642\u0637\u0639\u0629 \u0627\u0644\u062B\u0645\u0627\u0646\u064A\u0629\xBB (Real de a 8) \u0648\u0643\u0627\u0646\u062A \u0623\u0648\u0644 \u0639\u0645\u0644\u0629 \u0639\u0627\u0644\u0645\u064A\u0629\u061F", correctAnswer: "\u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A (\u0631\u064A\u0627\u0644 \u0627\u0644\u062B\u0645\u0627\u0646\u064A\u0629 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A)", explanation: "\u0633\u064F\u0643 \u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0625\u0633\u0628\u0627\u0646\u064A \u0645\u0646 \u0641\u0636\u0629 \u0628\u0648\u0644\u064A\u0641\u064A\u0627 \u0648\u0627\u0644\u0645\u0643\u0633\u064A\u0643 \u0648\u0627\u0633\u062A\u062E\u062F\u0645 \u0643\u0639\u0645\u0644\u0629 \u062A\u062C\u0627\u0631\u064A\u0629 \u0639\u0627\u0644\u0645\u064A\u0629 \u0648\u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0641\u064A \u0623\u0645\u0631\u064A\u0643\u0627 \u062D\u062A\u0649 1857.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0642\u062F\u0645 \u062F\u0627\u0631 \u0633\u0643 \u0639\u0645\u0644\u0629 \u0645\u0633\u062A\u0645\u0631\u0629 \u0641\u064A \u0627\u0644\u0639\u0645\u0644 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645 \u062D\u062A\u0649 \u0627\u0644\u064A\u0648\u0645 \u0648\u062A\u0642\u0639 \u0641\u064A \u0627\u0644\u0646\u0645\u0633\u0627 \u0648\u062A\u0623\u0633\u0633\u062A \u0639\u0627\u0645 1194\u061F", correctAnswer: "\u062F\u0627\u0631 \u0633\u0643 \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0646\u0645\u0633\u0627\u0648\u064A\u0629 (M\xFCnze \xD6sterreich)", explanation: "\u062A\u0623\u0633\u0633\u062A \u0645\u0646 \u0641\u062F\u064A\u0629 \u0631\u064A\u062A\u0634\u0627\u0631\u062F \u0642\u0644\u0628 \u0627\u0644\u0623\u0633\u062F \u0648\u062A\u0635\u0646\u0639 \u0639\u0645\u0644\u0629 \u0627\u0644\u0641\u064A\u0644\u0647\u0627\u0631\u0645\u0648\u0646\u064A\u0643 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0648\u0633\u0627\u0626\u0631 \u0627\u0644\u0645\u0633\u0643\u0648\u0643\u0627\u062A \u0627\u0644\u0646\u0645\u0633\u0627\u0648\u064A\u0629.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u0645\u0633\u0643\u0648\u0643\u0627\u062A \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0645\u0635\u0637\u0644\u062D \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0627\u0644\u0630\u064A \u064A\u0635\u0641 \u0627\u0644\u0646\u0642\u0648\u062F \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0633\u0646\u062F\u0647\u0627 \u0633\u0644\u0639\u0629 \u0645\u0627\u062F\u064A\u0629 \u0643\u0627\u0644\u0630\u0647\u0628 \u0648\u0644\u0643\u0646 \u062A\u0633\u062A\u0645\u062F \u0642\u064A\u0645\u062A\u0647\u0627 \u0645\u0646 \u0627\u0644\u062B\u0642\u0629 \u0648\u0642\u0648\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u062D\u0643\u0648\u0645\u064A\u061F", correctAnswer: "\u0627\u0644\u0646\u0642\u0648\u062F \u0627\u0644\u0625\u0644\u0632\u0627\u0645\u064A\u0629 (Fiat Money / \u0627\u0644\u0646\u0642\u0648\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629)", explanation: "\u062C\u0645\u064A\u0639 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0648\u0631\u0642\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0627\u0644\u064A\u0648\u0645 \u0647\u064A \u0646\u0642\u0648\u062F \u0625\u0644\u0632\u0627\u0645\u064A\u0629 \u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0642\u064A\u0645\u062A\u0647\u0627 \u0633\u0644\u0639\u0629 \u0639\u064A\u0646\u064A\u0629.", source: "\u0645\u0628\u0627\u062F\u0626 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0627\u0644\u0643\u0644\u064A" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0645\u064A\u0643\u0631\u0648\u0646\u064A\u0632\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0627\u0644\u062A\u064A \u0627\u0634\u062A\u0647\u0631\u062A \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062D\u062C\u0627\u0631\u0629 \u0627\u0644\u062D\u062C\u0631 \u0627\u0644\u062C\u064A\u0631\u064A \u0627\u0644\u0639\u0645\u0644\u0627\u0642\u0629 \u0627\u0644\u0645\u062B\u0642\u0648\u0628\u0629 \xAB\u062D\u062C\u0627\u0631\u0629 \u0631\u0627\u064A\xBB \u0643\u0646\u0642\u0648\u062F\u061F", correctAnswer: "\u062C\u0632\u064A\u0631\u0629 \u064A\u0627\u0628 (Yap Island)", explanation: "\u0627\u0633\u062A\u062E\u062F\u0645 \u0633\u0643\u0627\u0646 \u064A\u0627\u0628 \u0623\u0642\u0631\u0627\u0635\u0627\u064B \u062D\u062C\u0631\u064A\u0629 \u0636\u062E\u0645\u0629 \u0628\u0642\u0637\u0631 \u064A\u0635\u0644 \u0644\u0639\u062F\u0629 \u0623\u0645\u062A\u0627\u0631 \u0643\u0646\u0638\u0627\u0645 \u0646\u0642\u062F\u064A \u0645\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u0627\u0644\u0633\u062C\u0644 \u0627\u0644\u0634\u0641\u0648\u064A \u0644\u0644\u0645\u0644\u0643\u064A\u0629.", source: "\u0627\u0644\u0623\u0646\u062B\u0631\u0648\u0628\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0625\u0641\u0631\u064A\u0642\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u0631\u0636\u062A \u0644\u0623\u0634\u0647\u0631 \u062A\u0636\u062E\u0645 \u062C\u0627\u0645\u062D \u0641\u064A \u0627\u0644\u0639\u0635\u0631 \u0627\u0644\u062D\u062F\u064A\u062B \u0648\u0637\u0628\u0639\u062A \u0648\u0631\u0642\u0629 \u0646\u0642\u062F\u064A\u0629 \u0628\u0642\u064A\u0645\u0629 100 \u062A\u0631\u064A\u0644\u064A\u0648\u0646 \u0641\u064A \u0639\u0627\u0645 2008\u061F", correctAnswer: "\u062F\u0648\u0644\u0627\u0631 \u0632\u064A\u0645\u0628\u0627\u0628\u0648\u064A", explanation: "\u0648\u0635\u0644 \u0645\u0639\u062F\u0644 \u0627\u0644\u062A\u0636\u062E\u0645 \u0644\u0623\u0631\u0642\u0627\u0645 \u0641\u0644\u0643\u064A\u0629 \u062F\u0641\u0639\u062A \u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0644\u0637\u0628\u0627\u0639\u0629 \u0641\u0626\u0629 100,000,000,000,000 \u062F\u0648\u0644\u0627\u0631 \u0642\u0628\u0644 \u0627\u0644\u062A\u062E\u0644\u064A \u0639\u0646 \u0627\u0644\u0639\u0645\u0644\u0629.", source: "\u062F\u0631\u0627\u0633\u0627\u062A \u0627\u0644\u062A\u0636\u062E\u0645 \u0627\u0644\u062C\u0627\u0645\u062D \u0644\u0644\u0628\u0646\u0643 \u0627\u0644\u062F\u0648\u0644\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u062E\u0628\u064A\u0631 \u0627\u0644\u0645\u0627\u0644\u064A \u0627\u0644\u0625\u0633\u0643\u062A\u0644\u0646\u062F\u064A \u0627\u0644\u0630\u064A \u062A\u0633\u0628\u0628 \u0641\u064A \u0641\u0642\u0627\u0639\u0629 \u0627\u0644\u0645\u0633\u064A\u0633\u064A\u0628\u064A \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u064A \u0641\u0631\u0646\u0633\u0627 \u0639\u0627\u0645 1720 \u0628\u0633\u0628\u0628 \u0627\u0644\u062A\u0648\u0633\u0639 \u0627\u0644\u0645\u0641\u0631\u0637 \u0641\u064A \u0627\u0644\u0646\u0642\u0648\u062F \u0627\u0644\u0648\u0631\u0642\u064A\u0629\u061F", correctAnswer: "\u062C\u0648\u0646 \u0644\u0648 (John Law)", explanation: "\u0623\u0646\u0634\u0623 \u062C\u0648\u0646 \u0644\u0648 \u0628\u0646\u0643 \u0631\u0648\u064A\u0627\u0644 \u0648\u0623\u0635\u062F\u0631 \u0623\u0648\u0631\u0627\u0642\u0627\u064B \u0646\u0642\u062F\u064A\u0629 \u0623\u062F\u062A \u0644\u0627\u0646\u0647\u064A\u0627\u0631 \u0645\u0627\u0644\u064A \u0645\u0631\u0648\u0639 \u0644\u0644\u0627\u0642\u062A\u0635\u0627\u062F \u0627\u0644\u0641\u0631\u0646\u0633\u064A.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0623\u0632\u0645\u0627\u062A \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0623\u0635\u0644\u064A \u0644\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0641\u0636\u064A\u0629 \u0627\u0644\u062A\u064A \u0633\u064F\u0643\u062A \u0641\u064A \u0628\u0648\u0647\u064A\u0645\u064A\u0627 \u0628\u0627\u0633\u0645 \xAB\u064A\u0648\u0627\u062E\u064A\u0645\u0633\u062A\u0627\u0644\u0631\xBB \u0648\u0627\u0634\u062A\u0642 \u0645\u0646\u0647\u0627 \u0627\u0633\u0645 \xAB\u0627\u0644\u062F\u0648\u0644\u0627\u0631\xBB\u061F", correctAnswer: "\u0627\u0644\u062A\u0627\u0644\u0631 (Thaler)", explanation: "\u0633\u064F\u0643\u062A \u0627\u0644\u062A\u0627\u0644\u0631 \u0645\u0646 \u0645\u0646\u0627\u062C\u0645 \u064A\u0648\u0627\u062E\u064A\u0645\u0633\u062A\u0627\u0644 \u0648\u0627\u062E\u062A\u0635\u0631\u062A \u0644\u062A\u0627\u0644\u0631\u060C \u0648\u062A\u062D\u0648\u0644\u062A \u0628\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0644\u062F\u0648\u0644\u0627\u0631 \u0648\u0628\u0627\u0644\u0647\u0648\u0644\u0646\u062F\u064A\u0629 \u0644\u062F\u0627\u064A\u0644\u062F\u0631.", source: "\u062A\u0623\u062B\u064A\u0644 \u0623\u0635\u0648\u0644 \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0646\u0642\u062F\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u062A\u0630\u0643\u0627\u0631\u064A\u0629 \u0627\u0644\u0646\u0645\u0633\u0627\u0648\u064A\u0629 \u0627\u0644\u0641\u0636\u064A\u0629 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0627\u0633\u062A\u0645\u0631\u062A \u0627\u0644\u0646\u0645\u0633\u0627 \u0641\u064A \u0633\u0643\u0647\u0627 \u0628\u0646\u0641\u0633 \u062A\u0627\u0631\u064A\u062E \u0648\u0641\u0627\u0629 \u0627\u0644\u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631\u0629 (1780) \u0644\u062A\u062F\u0627\u0648\u0644\u0647\u0627 \u0641\u064A \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u0648\u0633\u0637 \u0648\u0625\u0641\u0631\u064A\u0642\u064A\u0627\u061F", correctAnswer: "\u062A\u064A\u0644\u0631 \u0645\u0627\u0631\u064A\u0627 \u062A\u064A\u0631\u064A\u0632\u0627 (\u0627\u0644\u0631\u064A\u0627\u0644 \u0627\u0644\u0641\u0631\u0627\u0646\u0633\u064A / \u0623\u0628\u0648 \u0637\u064A\u0631)", explanation: "\u0627\u0646\u062A\u0634\u0631 \u0631\u064A\u0627\u0644 \u0645\u0627\u0631\u064A\u0627 \u062A\u064A\u0631\u064A\u0632\u0627 \u0643\u0639\u0645\u0644\u0629 \u062A\u062C\u0627\u0631\u064A\u0629 \u0645\u0641\u0636\u0644\u0629 \u0648\u0645\u0648\u062B\u0648\u0642\u0629 \u0644\u0641\u0636\u062A\u0647\u0627 \u0641\u064A \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u064A\u0645\u0646 \u0648\u0625\u062B\u064A\u0648\u0628\u064A\u0627.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0641\u064A \u0634\u0628\u0647 \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629" }
      ],
      "\u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629": [
        // 100
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0641\u064A \u0623\u064A \u0639\u0627\u0645 \u0627\u0646\u062F\u0644\u0639\u062A \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0631\u0633\u0645\u064A\u0627\u064B\u061F", correctAnswer: "\u0639\u0627\u0645 1914\u0645", explanation: "\u0627\u0646\u062F\u0644\u0639\u062A \u0627\u0644\u062D\u0631\u0628 \u0641\u064A 28 \u064A\u0648\u0644\u064A\u0648 1914 \u0641\u064A \u0623\u0648\u0631\u0648\u0628\u0627 \u0625\u062B\u0631 \u0623\u0632\u0645\u0629 \u0633\u0631\u0627\u064A\u064A\u0641\u0648.", source: "\u0627\u0644\u0645\u0648\u0633\u0648\u0639\u0629 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0641\u064A \u0623\u064A \u0639\u0627\u0645 \u0627\u0646\u062A\u0647\u062A \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0628\u0627\u0633\u062A\u0633\u0644\u0627\u0645 \u0627\u0644\u064A\u0627\u0628\u0627\u0646 \u063A\u064A\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0637\u061F", correctAnswer: "\u0639\u0627\u0645 1945\u0645", explanation: "\u0627\u0646\u062A\u0647\u062A \u0627\u0644\u062D\u0631\u0628 \u0641\u064A 2 \u0633\u0628\u062A\u0645\u0628\u0631 1945 \u0628\u062A\u0648\u0642\u064A\u0639 \u0648\u062B\u064A\u0642\u0629 \u0627\u0644\u0627\u0633\u062A\u0633\u0644\u0627\u0645 \u0639\u0644\u0649 \u0645\u062A\u0646 \u0627\u0644\u0628\u0627\u0631\u062C\u0629 \u0645\u064A\u0633\u0648\u0631\u064A.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0646 \u0647\u0648 \u0632\u0639\u064A\u0645 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0627\u0644\u0646\u0627\u0632\u064A\u0629 \u0627\u0644\u0630\u064A \u062A\u0633\u0628\u0628 \u0641\u064A \u0625\u0634\u0639\u0627\u0644 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0628\u063A\u0632\u0648\u0647 \u0644\u0628\u0648\u0644\u0646\u062F\u0627\u061F", correctAnswer: "\u0623\u062F\u0648\u0644\u0641 \u0647\u062A\u0644\u0631", explanation: "\u0642\u0627\u062F \u0647\u062A\u0644\u0631 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0648\u0627\u0644\u062D\u0632\u0628 \u0627\u0644\u0646\u0627\u0632\u064A \u0644\u063A\u0632\u0648 \u0628\u0648\u0644\u0646\u062F\u0627 \u0641\u064A 1 \u0633\u0628\u062A\u0645\u0628\u0631 1939 \u0645\u0645\u0627 \u0641\u062C\u0631 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u0639\u0634\u0631\u064A\u0646" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u0645\u0627 \u0627\u0644\u0645\u062F\u064A\u0646\u062A\u0627\u0646 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u064A\u062A\u0627\u0646 \u0627\u0644\u0644\u062A\u0627\u0646 \u0623\u0644\u0642\u064A\u062A \u0639\u0644\u064A\u0647\u0645\u0627 \u0627\u0644\u0642\u0646\u0628\u0644\u062A\u0627\u0646 \u0627\u0644\u0630\u0631\u064A\u062A\u0627\u0646 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u062A\u0627\u0646 \u0641\u064A \u0623\u063A\u0633\u0637\u0633 1945\u061F", correctAnswer: "\u0647\u064A\u0631\u0648\u0634\u064A\u0645\u0627 \u0648\u0646\u0627\u063A\u0627\u0632\u0627\u0643\u064A", explanation: "\u0623\u0644\u0642\u062A \u0627\u0644\u0642\u0627\u0630\u0641\u0627\u062A \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0627\u0644\u0642\u0646\u0628\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0639\u0644\u0649 \u0647\u064A\u0631\u0648\u0634\u064A\u0645\u0627 \u0641\u064A 6 \u0623\u063A\u0633\u0637\u0633 \u062B\u0645 \u0646\u0627\u063A\u0627\u0632\u0627\u0643\u064A \u0641\u064A 9 \u0623\u063A\u0633\u0637\u0633 1945.", source: "\u0645\u062A\u062D\u0641 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u064A \u0647\u064A\u0631\u0648\u0634\u064A\u0645\u0627" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u062B\u0644\u0627\u062B \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u0627\u0644\u062A\u064A \u0634\u0643\u0644\u062A \u062D\u0644\u0641 \u062F\u0648\u0644 \u0627\u0644\u0645\u062D\u0648\u0631 \u0641\u064A \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629\u061F", correctAnswer: "\u0623\u0644\u0645\u0627\u0646\u064A\u0627\u060C \u0648\u0625\u064A\u0637\u0627\u0644\u064A\u0627\u060C \u0648\u0627\u0644\u064A\u0627\u0628\u0627\u0646", explanation: "\u0648\u0642\u0639\u062A \u0627\u0644\u062F\u0648\u0644 \u0627\u0644\u062B\u0644\u0627\u062B \u062D\u0644\u0641\u0627\u064B \u0639\u0633\u0643\u0631\u064A\u0627\u064B \u062B\u0644\u0627\u062B\u064A\u0627\u064B \u0639\u0631\u0641 \u0628\u062F\u0648\u0644 \u0627\u0644\u0645\u062D\u0648\u0631 \u0641\u064A \u0645\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u062D\u0644\u0641\u0627\u0621.", source: "\u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0633\u0643\u0631\u064A" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u062F\u062B \u0648\u0627\u0644\u0634\u0631\u0627\u0631\u0629 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0627\u0644\u062A\u064A \u0623\u0634\u0639\u0644\u062A \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064A \u0645\u062F\u064A\u0646\u0629 \u0633\u0631\u0627\u064A\u064A\u0641\u0648 \u0639\u0627\u0645 1914\u061F", correctAnswer: "\u0627\u063A\u062A\u064A\u0627\u0644 \u0648\u0644\u064A \u0639\u0647\u062F \u0627\u0644\u0646\u0645\u0633\u0627 \u0627\u0644\u0623\u0631\u0634\u064A\u062F\u0648\u0642 \u0641\u0631\u0627\u0646\u0632 \u0641\u0631\u062F\u064A\u0646\u0627\u0646\u062F", explanation: "\u0627\u063A\u062A\u0627\u0644 \u0627\u0644\u0637\u0627\u0644\u0628 \u0627\u0644\u0635\u0631\u0628\u064A \u063A\u0627\u0641\u0631\u064A\u0644\u0648 \u0628\u0631\u064A\u0646\u0633\u064A\u0628 \u0648\u0644\u064A \u0639\u0647\u062F \u0627\u0644\u0646\u0645\u0633\u0627 \u0648\u0632\u0648\u062C\u062A\u0647 \u0645\u0645\u0627 \u0641\u062C\u0631 \u0627\u0644\u062A\u062D\u0627\u0644\u0641\u0627\u062A \u0627\u0644\u062F\u0648\u0644\u064A\u0629.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0641\u064A \u0647\u0627\u0648\u0627\u064A \u0627\u0644\u062A\u064A \u0647\u0627\u062C\u0645\u0647\u0627 \u0627\u0644\u0637\u064A\u0631\u0627\u0646 \u0627\u0644\u064A\u0627\u0628\u0627\u0646\u064A \u0645\u0641\u0627\u062C\u0623\u0629 \u0641\u064A 7 \u062F\u064A\u0633\u0645\u0628\u0631 1941\u061F", correctAnswer: "\u0628\u064A\u0631\u0644 \u0647\u0627\u0631\u0628\u0631 (Pearl Harbor)", explanation: "\u062F\u0641\u0639 \u0627\u0644\u0647\u062C\u0648\u0645 \u0627\u0644\u0645\u0628\u0627\u063A\u062A \u0639\u0644\u0649 \u0628\u064A\u0631\u0644 \u0647\u0627\u0631\u0628\u0631 \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0644\u0644\u062F\u062E\u0648\u0644 \u0631\u0633\u0645\u064A\u0627\u064B \u0641\u064A \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0646 \u0647\u0648 \u0631\u0626\u064A\u0633 \u0648\u0632\u0631\u0627\u0621 \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627 \u0627\u0644\u0634\u0647\u064A\u0631 \u062E\u0644\u0627\u0644 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0648\u0635\u0627\u062D\u0628 \u062E\u0637\u0627\u0628 \xAB\u0627\u0644\u062F\u0645 \u0648\u0627\u0644\u062F\u0645\u0648\u0639 \u0648\u0627\u0644\u0639\u0631\u0642\xBB\u061F", correctAnswer: "\u0648\u0646\u0633\u062A\u0648\u0646 \u062A\u0634\u0631\u0634\u0644 (Winston Churchill)", explanation: "\u0642\u0627\u062F \u0648\u0646\u0633\u062A\u0648\u0646 \u062A\u0634\u0631\u0634\u0644 \u062D\u0643\u0648\u0645\u0629 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629 \u0648\u0635\u0645\u062F \u0623\u0645\u0627\u0645 \u0627\u0644\u063A\u0627\u0631\u0627\u062A \u0627\u0644\u062C\u0648\u064A\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629.", source: "\u0645\u0630\u0643\u0631\u0627\u062A \u0648\u0646\u0633\u062A\u0648\u0646 \u062A\u0634\u0631\u0634\u0644" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0633\u0648\u0641\u064A\u062A\u064A\u0629 \u0627\u0644\u0645\u0644\u062D\u0645\u064A\u0629 \u0627\u0644\u062A\u064A \u0645\u062B\u0644\u062A \u0646\u0642\u0637\u0629 \u0627\u0644\u062A\u062D\u0648\u0644 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u064A \u0647\u0632\u064A\u0645\u0629 \u0627\u0644\u062C\u064A\u0634 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u0639\u0644\u0649 \u0627\u0644\u062C\u0628\u0647\u0629 \u0627\u0644\u0634\u0631\u0642\u064A\u0629\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0633\u062A\u0627\u0644\u064A\u0646\u063A\u0631\u0627\u062F (Stalingrad)", explanation: "\u0627\u0633\u062A\u0633\u0644\u0645 \u0627\u0644\u062C\u064A\u0634 \u0627\u0644\u0633\u0627\u062F\u0633 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u0628\u0642\u064A\u0627\u062F\u0629 \u0628\u0627\u0648\u0644\u0648\u0633 \u0641\u064A \u0633\u062A\u0627\u0644\u064A\u0646\u063A\u0631\u0627\u062F \u0641\u064A \u0641\u0628\u0631\u0627\u064A\u0631 1943 \u0628\u0639\u062F \u062E\u0633\u0627\u0626\u0631 \u0628\u0634\u0631\u064A\u0629 \u0647\u0627\u0626\u0644\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062C\u0628\u0647\u0629 \u0627\u0644\u0634\u0631\u0642\u064A\u0629" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0646\u0638\u0645\u0629 \u0627\u0644\u062F\u0648\u0644\u064A\u0629 \u0627\u0644\u062A\u064A \u062A\u0623\u0633\u0633\u062A \u0628\u0639\u062F \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0644\u0645\u0646\u0639 \u0627\u0644\u062D\u0631\u0648\u0628 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0648\u062D\u0644\u062A \u0645\u062D\u0644 \u0639\u0635\u0628\u0629 \u0627\u0644\u0623\u0645\u0645\u061F", correctAnswer: "\u0645\u0646\u0638\u0645\u0629 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 (UN)", explanation: "\u062A\u0623\u0633\u0633\u062A \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0641\u064A \u0633\u0627\u0646 \u0641\u0631\u0627\u0646\u0633\u064A\u0633\u0643\u0648 \u0641\u064A \u0623\u0643\u062A\u0648\u0628\u0631 1945 \u0628\u0645\u0634\u0627\u0631\u0643\u0629 51 \u062F\u0648\u0644\u0629.", source: "\u0645\u064A\u062B\u0627\u0642 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u062A\u062D\u062F\u0629" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0631\u0645\u0632\u064A \u0644\u0644\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0628\u0631\u0645\u0627\u0626\u064A \u0627\u0644\u0636\u062E\u0645 \u0644\u0642\u0648\u0627\u062A \u0627\u0644\u062D\u0644\u0641\u0627\u0621 \u0639\u0644\u0649 \u0634\u0648\u0627\u0637\u0626 \u0646\u0648\u0631\u0645\u0627\u0646\u062F\u064A \u0641\u064A \u0641\u0631\u0646\u0633\u0627 \u0641\u064A 6 \u064A\u0648\u0646\u064A\u0648 1944 (D-Day)\u061F", correctAnswer: "\u0639\u0645\u0644\u064A\u0629 \u0623\u0648\u0641\u0631\u0644\u0648\u0631\u062F (Operation Overlord)", explanation: "\u0634\u0643\u0644 \u0625\u0646\u0632\u0627\u0644 \u0646\u0648\u0631\u0645\u0627\u0646\u062F\u064A \u0623\u0643\u0628\u0631 \u0625\u0646\u0632\u0627\u0644 \u0628\u062D\u0631\u064A \u0639\u0633\u0643\u0631\u064A \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0648\u0641\u062A\u062D \u0627\u0644\u062C\u0628\u0647\u0629 \u0627\u0644\u063A\u0631\u0628\u064A\u0629 \u0644\u062A\u062D\u0631\u064A\u0631 \u0641\u0631\u0646\u0633\u0627.", source: "\u0633\u062C\u0644\u0627\u062A \u0642\u064A\u0627\u062F\u0629 \u0627\u0644\u062D\u0644\u0641\u0627\u0621 \u0627\u0644\u0639\u0644\u064A\u0627" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0645\u0639\u0627\u0647\u062F\u0629 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0634\u0647\u064A\u0631\u0629 \u0627\u0644\u062A\u064A \u0641\u0631\u0636\u062A \u0634\u0631\u0648\u0637\u0627\u064B \u0642\u0627\u0633\u064A\u0629 \u0648\u063A\u0631\u0627\u0645\u0627\u062A \u0628\u0627\u0647\u0638\u0629 \u0639\u0644\u0649 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0639\u0627\u0645 1919 \u0648\u0645\u0647\u062F\u062A \u0644\u0635\u0639\u0648\u062F \u0627\u0644\u0646\u0627\u0632\u064A\u0629\u061F", correctAnswer: "\u0645\u0639\u0627\u0647\u062F\u0629 \u0641\u0631\u0633\u0627\u064A (Treaty of Versailles)", explanation: "\u0648\u0642\u0639\u062A \u0627\u0644\u0645\u0639\u0627\u0647\u062F\u0629 \u0641\u064A \u0642\u0627\u0639\u0629 \u0627\u0644\u0645\u0631\u0627\u064A\u0627 \u0628\u0641\u0631\u0633\u0627\u064A \u0648\u062C\u0631\u062F\u062A \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0645\u0646 \u0645\u0633\u062A\u0639\u0645\u0631\u0627\u062A\u0647\u0627 \u0648\u062D\u062F\u062A \u0645\u0646 \u062A\u0633\u0644\u064A\u062D\u0647\u0627.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062F\u0628\u0644\u0648\u0645\u0627\u0633\u064A\u0629 \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u0648 \u062A\u0643\u062A\u064A\u0643 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u062E\u0627\u0637\u0641\u0629 \u0627\u0644\u0633\u0631\u064A\u0639 \u0627\u0644\u0630\u064A \u0627\u0639\u062A\u0645\u062F\u062A\u0647 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0627\u0644\u0646\u0627\u0632\u064A\u0629 \u0641\u064A \u0627\u062C\u062A\u064A\u0627\u062D \u0623\u0648\u0631\u0648\u0628\u0627 \u0628\u0627\u0644\u062F\u0628\u0627\u0628\u0627\u062A \u0648\u0627\u0644\u0637\u064A\u0631\u0627\u0646 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u061F", correctAnswer: "\u0627\u0644\u0628\u0644\u064A\u062A\u0632\u0643\u0631\u064A\u063A (Blitzkrieg)", explanation: "\u0627\u0639\u062A\u0645\u062F \u0627\u0644\u062A\u0643\u062A\u064A\u0643 \u0639\u0644\u0649 \u0627\u0644\u0633\u0631\u0639\u0629 \u0648\u0627\u0644\u0645\u0628\u0627\u063A\u062A\u0629 \u0648\u0642\u0648\u0629 \u0627\u0644\u062F\u0631\u0648\u0639 \u0627\u0644\u062C\u0648\u064A\u0629 \u0644\u0627\u062E\u062A\u0631\u0627\u0642 \u062E\u0637\u0648\u0637 \u0627\u0644\u062F\u0641\u0627\u0639 \u0648\u0634\u0644 \u0627\u0644\u0639\u062F\u0648.", source: "\u0627\u0644\u0639\u0642\u064A\u062F\u0629 \u0627\u0644\u0639\u0633\u0643\u0631\u064A\u0629 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0642\u0627\u0626\u062F \u0627\u0644\u0639\u0633\u0643\u0631\u064A \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u0627\u0644\u0645\u0644\u0642\u0628 \u0628\u0640 \xAB\u062B\u0639\u0644\u0628 \u0627\u0644\u0635\u062D\u0631\u0627\u0621\xBB \u0648\u0642\u0627\u062F \u0641\u064A\u0644\u0642 \u0627\u0644\u0635\u062D\u0631\u0627\u0621 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A (\u0623\u0641\u0631\u064A\u0643\u0627 \u0643\u0648\u0631\u0628\u0633) \u0641\u064A \u0634\u0645\u0627\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627\u061F", correctAnswer: "\u0625\u0631\u0641\u064A\u0646 \u0631\u0648\u0645\u0644 (Erwin Rommel)", explanation: "\u0627\u0634\u062A\u0647\u0631 \u0631\u0648\u0645\u0644 \u0628\u0628\u0631\u0627\u0639\u062A\u0647 \u0627\u0644\u062A\u0643\u062A\u064A\u0643\u064A\u0629 \u0641\u064A \u0645\u0639\u0627\u0631\u0643 \u0634\u0645\u0627\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627 \u0636\u062F \u0627\u0644\u0642\u0648\u0627\u062A \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u062D\u0645\u0644\u0629 \u0634\u0645\u0627\u0644 \u0625\u0641\u0631\u064A\u0642\u064A\u0627" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0641\u0627\u0635\u0644\u0629 \u0641\u064A \u0645\u0635\u0631 \u0639\u0627\u0645 1942 \u0627\u0644\u062A\u064A \u0642\u0627\u062F \u0641\u064A\u0647\u0627 \u0627\u0644\u062C\u0646\u0631\u0627\u0644 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A \u0645\u0648\u0646\u062A\u063A\u0645\u0631\u064A \u0627\u0644\u062D\u0644\u0641\u0627\u0621 \u0644\u0644\u0627\u0646\u062A\u0635\u0627\u0631 \u0639\u0644\u0649 \u0642\u0648\u0627\u062A \u0631\u0648\u0645\u0644\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0639\u0644\u0645\u064A\u0646 \u0627\u0644\u062B\u0627\u0646\u064A\u0629", explanation: "\u0634\u0643\u0644\u062A \u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0639\u0644\u0645\u064A\u0646 \u0646\u0647\u0627\u064A\u0629 \u062A\u0647\u062F\u064A\u062F \u0627\u0644\u0645\u062D\u0648\u0631 \u0644\u0642\u0646\u0627\u0629 \u0627\u0644\u0633\u0648\u064A\u0633 \u0648\u0628\u062F\u0627\u064A\u0629 \u0637\u0631\u062F \u0642\u0648\u0627\u062A \u0627\u0644\u0645\u062D\u0648\u0631 \u0645\u0646 \u0625\u0641\u0631\u064A\u0642\u064A\u0627.", source: "\u0623\u0631\u0634\u064A\u0641 \u0645\u0639\u0627\u0631\u0643 \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u0648\u0633\u0637" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0631\u0645\u0632\u064A \u0644\u0644\u063A\u0632\u0648 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u0627\u0644\u0636\u062E\u0645 \u0644\u0644\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u0633\u0648\u0641\u064A\u062A\u064A \u0641\u064A 22 \u064A\u0648\u0646\u064A\u0648 1941\u061F", correctAnswer: "\u0639\u0645\u0644\u064A\u0629 \u0628\u0627\u0631\u0628\u0627\u0631\u0648\u0633\u0627 (Operation Barbarossa)", explanation: "\u0634\u0647\u062F\u062A \u0639\u0645\u0644\u064A\u0629 \u0628\u0627\u0631\u0628\u0627\u0631\u0648\u0633\u0627 \u062D\u0634\u062F \u0623\u0643\u062B\u0631 \u0645\u0646 3 \u0645\u0644\u0627\u064A\u064A\u0646 \u062C\u0646\u062F\u064A \u0623\u0644\u0645\u0627\u0646\u064A \u0639\u0644\u0649 \u0637\u0648\u0644 \u062C\u0628\u0647\u0629 \u0627\u0645\u062A\u062F\u062A \u0644\u0622\u0644\u0627\u0641 \u0627\u0644\u0643\u064A\u0644\u0648\u0645\u062A\u0631\u0627\u062A.", source: "\u0627\u0644\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0639\u0633\u0643\u0631\u064A\u0629 \u0644\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0643\u0628\u0631 \u0645\u0639\u0631\u0643\u0629 \u062F\u0628\u0627\u0628\u0627\u062A \u0648\u0645\u062F\u0631\u0639\u0627\u062A \u0641\u064A \u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0633\u0643\u0631\u064A \u0648\u0648\u0642\u0639\u062A \u0639\u0627\u0645 1943 \u0628\u064A\u0646 \u0627\u0644\u0642\u0648\u0627\u062A \u0627\u0644\u0633\u0648\u0641\u064A\u062A\u064A\u0629 \u0648\u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0643\u0648\u0631\u0633\u0643 (Battle of Kursk)", explanation: "\u0627\u0634\u062A\u0628\u0643\u062A \u0622\u0644\u0627\u0641 \u0627\u0644\u062F\u0628\u0627\u0628\u0627\u062A \u0648\u0627\u0644\u0645\u062F\u0631\u0639\u0627\u062A \u0627\u0644\u0633\u0648\u0641\u064A\u062A\u064A\u0629 \u0648\u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629 \u0641\u064A \u0643\u0648\u0631\u0633\u0643 \u0648\u062D\u0633\u0645 \u0627\u0644\u0633\u0648\u0641\u064A\u062A \u0627\u0644\u0645\u0639\u0631\u0643\u0629.", source: "\u0627\u0644\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0633\u0643\u0631\u064A \u0644\u0644\u0645\u062F\u0631\u0639\u0627\u062A" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0633\u0645 \u062C\u0647\u0627\u0632 \u0627\u0644\u062A\u0634\u0641\u064A\u0631 \u0627\u0644\u0645\u064A\u0643\u0627\u0646\u064A\u0643\u064A \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u0627\u0644\u0634\u0647\u064A\u0631 \u0627\u0644\u0630\u064A \u062A\u0645\u0643\u0646 \u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u062D\u0644\u0641\u0627\u0621 \u0641\u064A \u0628\u0644\u062A\u0634\u0644\u064A \u0628\u0627\u0631\u0643 \u0628\u0642\u064A\u0627\u062F\u0629 \u0622\u0644\u0627\u0646 \u062A\u0648\u0631\u0646\u063A \u0645\u0646 \u0641\u0643 \u0634\u0641\u0631\u062A\u0647\u061F", correctAnswer: "\u0622\u0644\u0629 \u0625\u0646\u064A\u063A\u0645\u0627 (Enigma machine)", explanation: "\u0633\u0627\u0647\u0645 \u0641\u0643 \u0634\u0641\u0631\u0629 \u0625\u0646\u064A\u063A\u0645\u0627 \u0639\u0628\u0631 \u0645\u0634\u0631\u0648\u0639 \u0623\u0644\u062A\u0631\u0627 \u0641\u064A \u062A\u0642\u0635\u064A\u0631 \u0623\u0645\u062F \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0648\u0625\u0646\u0642\u0627\u0630 \u0622\u0644\u0627\u0641 \u0627\u0644\u0623\u0631\u0648\u0627\u062D.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0627\u0633\u062A\u062E\u0628\u0627\u0631\u0627\u062A \u0648\u0641\u0643 \u0627\u0644\u062A\u0634\u0641\u064A\u0631" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u062C\u0648\u064A\u0629 \u0627\u0644\u062D\u0627\u0633\u0645\u0629 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0641\u064A \u064A\u0648\u0646\u064A\u0648 1942 \u0648\u062F\u0645\u0631\u062A \u0641\u064A\u0647\u0627 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 4 \u062D\u0627\u0645\u0644\u0627\u062A \u0637\u0627\u0626\u0631\u0627\u062A \u064A\u0627\u0628\u0627\u0646\u064A\u0629\u061F", correctAnswer: "\u0645\u0639\u0631\u0643\u0629 \u0645\u064A\u062F\u0648\u0627\u064A (Battle of Midway)", explanation: "\u0643\u0633\u0631\u062A \u0645\u0639\u0631\u0643\u0629 \u0645\u064A\u062F\u0648\u0627\u064A \u0627\u0644\u0647\u064A\u0645\u0646\u0629 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0644\u0644\u064A\u0627\u0628\u0627\u0646 \u0641\u064A \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0647\u0627\u062F\u0626 \u0648\u0634\u0643\u0644\u062A \u0646\u0642\u0637\u0629 \u062A\u062D\u0648\u0644 \u0627\u0644\u062D\u0631\u0628.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0623\u0645\u0631\u064A\u0643\u064A\u0629 \u0641\u064A \u0627\u0644\u0647\u0627\u062F\u0626" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u062E\u0637 \u0627\u0644\u062F\u0641\u0627\u0639 \u0627\u0644\u062E\u0631\u0633\u0627\u0646\u064A \u0648\u0627\u0644\u062D\u0635\u064A\u0646 \u0627\u0644\u0636\u062E\u0645 \u0627\u0644\u0630\u064A \u0628\u0646\u062A\u0647 \u0641\u0631\u0646\u0633\u0627 \u0639\u0644\u0649 \u062D\u062F\u0648\u062F\u0647\u0627 \u0645\u0639 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u0642\u0628\u0644 \u0627\u0644\u062D\u0631\u0628 \u0648\u0638\u0646\u062A \u0623\u0646\u0647 \u0644\u0627 \u064A\u064F\u062E\u062A\u0631\u0642\u061F", correctAnswer: "\u062E\u0637 \u0645\u0627\u062C\u064A\u0646\u0648 (Maginot Line)", explanation: "\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u062C\u064A\u0634 \u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A \u062E\u0637 \u0645\u0627\u062C\u064A\u0646\u0648 \u0628\u0627\u0644\u0627\u0644\u062A\u0641\u0627\u0641 \u0639\u0628\u0631 \u063A\u0627\u0628\u0627\u062A \u0627\u0644\u0623\u0631\u062F\u064A\u0646 \u0641\u064A \u0628\u0644\u062C\u064A\u0643\u0627 \u0648\u0644\u0648\u0643\u0633\u0645\u0628\u0648\u0631\u063A \u0639\u0627\u0645 1940.", source: "\u0627\u0644\u0647\u0646\u062F\u0633\u0629 \u0627\u0644\u0639\u0633\u0643\u0631\u064A\u0629 \u0627\u0644\u062F\u0641\u0627\u0639\u064A\u0629" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0628\u0631\u0642\u064A\u0629 \u0627\u0644\u062F\u0628\u0644\u0648\u0645\u0627\u0633\u064A\u0629 \u0627\u0644\u0633\u0631\u064A\u0629 \u0627\u0644\u062A\u064A \u0627\u0639\u062A\u0631\u0636\u062A\u0647\u0627 \u0627\u0644\u0645\u062E\u0627\u0628\u0631\u0627\u062A \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629 \u0639\u0627\u0645 1917 \u0648\u0627\u0642\u062A\u0631\u062D\u062A \u0641\u064A\u0647\u0627 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u062A\u062D\u0627\u0644\u0641\u0627\u064B \u0645\u0639 \u0627\u0644\u0645\u0643\u0633\u064A\u0643 \u0644\u063A\u0632\u0648 \u0623\u0645\u0631\u064A\u0643\u0627\u061F", correctAnswer: "\u0628\u0631\u0642\u064A\u0629 \u0632\u064A\u0645\u0631\u0645\u0627\u0646 (Zimmermann Telegram)", explanation: "\u0623\u062B\u0627\u0631 \u0646\u0634\u0631 \u0628\u0631\u0642\u064A\u0629 \u0632\u064A\u0645\u0631\u0645\u0627\u0646 \u0627\u0644\u063A\u0636\u0628 \u0627\u0644\u0634\u0639\u0628\u064A \u0641\u064A \u0627\u0644\u0648\u0644\u0627\u064A\u0627\u062A \u0627\u0644\u0645\u062A\u062D\u062F\u0629 \u0648\u0643\u0627\u0646 \u0633\u0628\u0628\u0627\u064B \u0645\u0628\u0627\u0634\u0631\u0627\u064B \u0644\u0625\u0639\u0644\u0627\u0646\u0647\u0627 \u0627\u0644\u062D\u0631\u0628 \u0639\u0644\u0649 \u0623\u0644\u0645\u0627\u0646\u064A\u0627.", source: "\u0623\u0631\u0634\u064A\u0641 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0627\u0644\u062F\u0628\u0644\u0648\u0645\u0627\u0633\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0631\u0645\u0632\u064A \u0644\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0639\u0644\u0645\u064A \u0648\u0627\u0644\u0641\u064A\u0632\u064A\u0627\u0626\u064A \u0627\u0644\u0633\u0631\u064A \u0628\u0642\u064A\u0627\u062F\u0629 \u0631\u0648\u0628\u0631\u062A \u0623\u0648\u0628\u0646\u0647\u0627\u064A\u0645\u0631 \u0627\u0644\u0630\u064A \u0637\u0648\u0631 \u0623\u0648\u0644 \u0642\u0646\u0628\u0644\u0629 \u0630\u0631\u064A\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645\u061F", correctAnswer: "\u0645\u0634\u0631\u0648\u0639 \u0645\u0627\u0646\u0647\u0627\u062A\u0646 (Manhattan Project)", explanation: "\u0623\u062C\u0631\u0649 \u0645\u0634\u0631\u0648\u0639 \u0645\u0627\u0646\u0647\u0627\u062A\u0646 \u0623\u0648\u0644 \u0627\u062E\u062A\u0628\u0627\u0631 \u0646\u0648\u0648\u064A \u0646\u0627\u062C\u062D \u0641\u064A \u0635\u062D\u0631\u0627\u0621 \u0646\u064A\u0648 \u0645\u0643\u0633\u064A\u0643\u0648 (\u062A\u062C\u0631\u0628\u0629 \u062A\u0631\u064A\u0646\u064A\u062A\u064A) \u0641\u064A \u064A\u0648\u0644\u064A\u0648 1945.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0630\u0631\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0645\u0639\u0627\u0647\u062F\u0629 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629 \u0627\u0644\u062A\u064A \u0648\u0642\u0639\u062A\u0647\u0627 \u0631\u0648\u0633\u064A\u0627 \u0627\u0644\u0628\u0644\u0634\u0641\u064A\u0629 \u0645\u0639 \u0642\u0648\u0649 \u0627\u0644\u0645\u062D\u0648\u0631 \u0648\u062E\u0631\u062C\u062A \u0628\u0645\u0648\u062C\u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u062D\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064A \u0645\u0627\u0631\u0633 1918\u061F", correctAnswer: "\u0645\u0639\u0627\u0647\u062F\u0629 \u0628\u0631\u0633\u062A \u0644\u064A\u062A\u0648\u0641\u0633\u0643 (Treaty of Brest-Litovsk)", explanation: "\u062A\u0646\u0627\u0632\u0644\u062A \u0631\u0648\u0633\u064A\u0627 \u0627\u0644\u0628\u0644\u0634\u0641\u064A\u0629 \u0628\u0642\u064A\u0627\u062F\u0629 \u0644\u064A\u0646\u064A\u0646 \u0639\u0646 \u0623\u0631\u0627\u0636\u064D \u0648\u0627\u0633\u0639\u0629 \u0641\u064A \u0623\u0648\u0631\u0648\u0628\u0627 \u0627\u0644\u0634\u0631\u0642\u064A\u0629 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0642\u062A\u0627\u0644 \u0648\u0627\u0644\u062A\u0641\u0631\u063A \u0644\u0644\u062B\u0648\u0631\u0629.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u062B\u0648\u0631\u0629 \u0627\u0644\u0631\u0648\u0633\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u0625\u062C\u0644\u0627\u0621 \u0627\u0644\u0628\u062D\u0631\u064A \u0627\u0644\u0636\u062E\u0645\u0629 \u0627\u0644\u0645\u0639\u062C\u0632\u0629 \u0644\u0623\u0643\u062B\u0631 \u0645\u0646 330 \u0623\u0644\u0641 \u062C\u0646\u062F\u064A \u0628\u0631\u064A\u0637\u0627\u0646\u064A \u0648\u0641\u0631\u0646\u0633\u064A \u0645\u0646 \u0634\u0648\u0627\u0637\u0626 \u0634\u0645\u0627\u0644 \u0641\u0631\u0646\u0633\u0627 \u0641\u064A \u0645\u0627\u064A\u0648 1940\u061F", correctAnswer: "\u0639\u0645\u0644\u064A\u0629 \u062F\u064A\u0646\u0627\u0645\u0648 (\u0625\u062C\u0644\u0627\u0621 \u062F\u0646\u0643\u064A\u0631\u0643 / Dunkirk evacuation)", explanation: "\u0634\u0627\u0631\u0643\u062A \u0641\u064A\u0647\u0627 \u0645\u0626\u0627\u062A \u0627\u0644\u0633\u0641\u0646 \u0627\u0644\u0645\u062F\u0646\u064A\u0629 \u0648\u0627\u0644\u0635\u063A\u064A\u0631\u0629 \u0648\u0627\u0644\u064A\u062E\u0648\u062A \u0625\u0644\u0649 \u062C\u0627\u0646\u0628 \u0627\u0644\u0633\u0641\u0646 \u0627\u0644\u062D\u0631\u0628\u064A\u0629 \u0644\u0625\u0646\u0642\u0627\u0630 \u0627\u0644\u0642\u0648\u0627\u062A \u0627\u0644\u0645\u062D\u0627\u0635\u0631\u0629.", source: "\u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0628\u062D\u0631\u064A\u0629 \u0627\u0644\u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0629" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u062C\u0632\u064A\u0631\u0629 \u0627\u0644\u0625\u064A\u0637\u0627\u0644\u064A\u0629 \u0641\u064A \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0645\u062A\u0648\u0633\u0637 \u0627\u0644\u062A\u064A \u0634\u0647\u062F\u062A \u0625\u0637\u0644\u0627\u0642 \u0623\u0648\u0644 \u063A\u0632\u0648 \u0628\u0631\u0645\u0627\u0626\u064A \u0644\u0644\u062D\u0644\u0641\u0627\u0621 \u0644\u0644\u0623\u0631\u0627\u0636\u064A \u0627\u0644\u0623\u0648\u0631\u0648\u0628\u064A\u0629 \u0641\u064A \u064A\u0648\u0644\u064A\u0648 1943 \u0648\u0633\u0642\u0648\u0637 \u0645\u0648\u0633\u0648\u0644\u064A\u0646\u064A\u061F", correctAnswer: "\u062C\u0632\u064A\u0631\u0629 \u0635\u0642\u0644\u064A\u0629 (\u0639\u0645\u0644\u064A\u0629 \u0647\u0627\u0633\u0643\u064A / Operation Husky)", explanation: "\u0623\u062F\u0649 \u0646\u062C\u0627\u062D \u0639\u0645\u0644\u064A\u0629 \u0647\u0627\u0633\u0643\u064A \u0648\u0627\u062C\u062A\u064A\u0627\u062D \u0635\u0642\u0644\u064A\u0629 \u0625\u0644\u0649 \u0639\u0632\u0644 \u0627\u0644\u0645\u0644\u0643 \u0641\u064A\u0643\u062A\u0648\u0631 \u0625\u064A\u0645\u0627\u0646\u0648\u064A\u0644 \u0644\u0644\u062F\u064A\u0643\u062A\u0627\u062A\u0648\u0631 \u0628\u064A\u0646\u064A\u062A\u0648 \u0645\u0648\u0633\u0648\u0644\u064A\u0646\u064A \u0648\u0627\u0639\u062A\u0642\u0627\u0644\u0647.", source: "\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u062D\u0631\u0628\u064A\u0629 \u0641\u064A \u0627\u0644\u0628\u062D\u0631 \u0627\u0644\u0645\u062A\u0648\u0633\u0637" }
      ]
    };
  }
});

