        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0637\u0648\u0644 \u0633\u0648\u0631\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629 \u0647\u064A \u0623\u0637\u0648\u0644 \u0633\u0648\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0628\u0639\u062F\u062F 286 \u0622\u064A\u0629.", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0642\u0635\u0631 \u0633\u0648\u0631\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0645\u0646 \u062D\u064A\u062B \u0639\u062F\u062F \u0627\u0644\u0622\u064A\u0627\u062A\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0648\u062B\u0631", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0648\u062B\u0631 \u062A\u062A\u0643\u0648\u0646 \u0645\u0646 3 \u0622\u064A\u0627\u062A \u0643\u0631\u064A\u0645\u0629 \u0641\u0642\u0637.", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u0645\u0649 \xAB\u0623\u0645 \u0627\u0644\u0643\u062A\u0627\u0628\xBB \u0648\xAB\u0627\u0644\u0633\u0628\u0639 \u0627\u0644\u0645\u062B\u0627\u0646\u064A\xBB\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0641\u0627\u062A\u062D\u0629", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0641\u0627\u062A\u062D\u0629 \u0647\u064A \u0641\u0627\u062A\u062D\u0629 \u0627\u0644\u0643\u062A\u0627\u0628 \u0648\u062A\u0633\u0645\u0649 \u0628\u0623\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0633\u0628\u0639 \u0627\u0644\u0645\u062B\u0627\u0646\u064A.", source: "\u062A\u0641\u0633\u064A\u0631 \u0627\u0628\u0646 \u0643\u062B\u064A\u0631" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0623\u062C\u0632\u0627\u0621 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "30 \u062C\u0632\u0621\u0627\u064B", explanation: "\u064A\u062A\u0623\u0644\u0641 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0645\u0646 \u062B\u0644\u0627\u062B\u064A\u0646 \u062C\u0632\u0621\u0627\u064B.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0642\u0631\u0622\u0646" },
        { points: 100, difficulty: "\u0633\u0647\u0644", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0639\u0638\u0645 \u0622\u064A\u0629 \u0641\u064A \u0643\u062A\u0627\u0628 \u0627\u0644\u0644\u0647 \u062A\u0639\u0627\u0644\u0649\u061F", correctAnswer: "\u0622\u064A\u0629 \u0627\u0644\u0643\u0631\u0633\u064A", explanation: "\u0622\u064A\u0629 \u0627\u0644\u0643\u0631\u0633\u064A \u0641\u064A \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629 (\u0627\u0644\u0622\u064A\u0629 255) \u0647\u064A \u0623\u0639\u0638\u0645 \u0622\u064A\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646.", source: "\u0635\u062D\u064A\u062D \u0645\u0633\u0644\u0645" },
        // 200
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0627\u0644\u062A\u064A \u0644\u0627 \u062A\u0628\u062F\u0623 \u0628\u0627\u0644\u0628\u0633\u0645\u0644\u0629\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u0648\u0628\u0629 (\u0628\u0631\u0627\u0621\u0629)", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u0648\u0628\u0629 \u0646\u0632\u0644\u062A \u0628\u0627\u0644\u0633\u064A\u0641 \u0648\u0631\u0641\u0639 \u0627\u0644\u0623\u0645\u0627\u0646 \u0639\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064A\u0646 \u0641\u0644\u0645 \u062A\u0628\u062F\u0623 \u0628\u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062D\u0645\u0646 \u0627\u0644\u0631\u062D\u064A\u0645.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0642\u0631\u0622\u0646" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u0628\u0633\u0645\u0644\u062A\u064A\u0646 \u0641\u064A \u0622\u064A\u0627\u062A\u0647\u0627\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0645\u0644", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0645\u0644 \u062A\u0628\u062F\u0623 \u0628\u0627\u0644\u0628\u0633\u0645\u0644\u0629 \u0648\u0641\u064A \u0622\u064A\u062A\u0647\u0627 30: \u0625\u0646\u0647 \u0645\u0646 \u0633\u0644\u064A\u0645\u0627\u0646 \u0648\u0625\u0646\u0647 \u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062D\u0645\u0646 \u0627\u0644\u0631\u062D\u064A\u0645.", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0639\u062F\u0644 \u0642\u0631\u0627\u0621\u062A\u0647\u0627 \u062B\u0644\u062B \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u062E\u0644\u0627\u0635 (\u0642\u0644 \u0647\u0648 \u0627\u0644\u0644\u0647 \u0623\u062D\u062F)", explanation: "\u062B\u0628\u062A \u0641\u064A \u0627\u0644\u0623\u062D\u0627\u062F\u064A\u062B \u0627\u0644\u0635\u062D\u064A\u062D\u0629 \u0623\u0646 \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u062E\u0644\u0627\u0635 \u062A\u0639\u062F\u0644 \u062B\u0644\u062B \u0627\u0644\u0642\u0631\u0622\u0646 \u0644\u0627\u0634\u062A\u0645\u0627\u0644\u0647\u0627 \u0639\u0644\u0649 \u062A\u0648\u062D\u064A\u062F \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0648\u0627\u0644\u0635\u0641\u0627\u062A.", source: "\u0635\u062D\u064A\u062D \u0627\u0644\u0628\u062E\u0627\u0631\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0633\u0648\u0631\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u062A\u0633\u0645\u0649 \xAB\u0639\u0631\u0648\u0633 \u0627\u0644\u0642\u0631\u0622\u0646\xBB\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0631\u062D\u0645\u0646", explanation: "\u0648\u0631\u062F \u0641\u064A \u0627\u0644\u0623\u062B\u0631 \u062A\u0633\u0645\u064A\u0629 \u0633\u0648\u0631\u0629 \u0627\u0644\u0631\u062D\u0645\u0646 \u0628\u0639\u0631\u0648\u0633 \u0627\u0644\u0642\u0631\u0622\u0646 \u0644\u062D\u0633\u0646 \u062F\u064A\u0628\u0627\u062C\u062A\u0647\u0627 \u0648\u062C\u0645\u0627\u0644 \u0622\u064A\u0627\u062A\u0647\u0627.", source: "\u0634\u0639\u0628 \u0627\u0644\u0625\u064A\u0645\u0627\u0646 \u0644\u0644\u0628\u064A\u0647\u0642\u064A" },
        { points: 200, difficulty: "\u0645\u062A\u0648\u0633\u0637", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u0645\u0649 \xAB\u0627\u0644\u0645\u0646\u062C\u064A\u0629 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0642\u0628\u0631\xBB\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0644\u0643 (\u062A\u0628\u0627\u0631\u0643)", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0644\u0643 \u062B\u0644\u0627\u062B\u0648\u0646 \u0622\u064A\u0629 \u062A\u0634\u0641\u0639 \u0644\u0635\u0627\u062D\u0628\u0647\u0627 \u0648\u062A\u0646\u062C\u064A\u0647 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0642\u0628\u0631.", source: "\u0633\u0646\u0646 \u0627\u0644\u062A\u0631\u0645\u0630\u064A" },
        // 300
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0623\u0637\u0648\u0644 \u0643\u0644\u0645\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0631\u0633\u0645\u0627\u064B \u0648\u062D\u0631\u0648\u0641\u0627\u064B\u061F", correctAnswer: "\u0641\u0623\u0633\u0642\u064A\u0646\u0627\u0643\u0645\u0648\u0647", explanation: "\u0648\u0631\u062F\u062A \u0641\u064A \u0633\u0648\u0631\u0629 \u0627\u0644\u062D\u062C\u0631 \u0622\u064A\u0629 22 \u0648\u062A\u062A\u0643\u0648\u0646 \u0645\u0646 11 \u062D\u0631\u0641\u0627\u064B \u0628\u0631\u0633\u0645 \u0627\u0644\u0645\u0635\u062D\u0641.", source: "\u0645\u0639\u0627\u062C\u0645 \u0623\u0644\u0641\u0627\u0638 \u0627\u0644\u0642\u0631\u0622\u0646" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u062A\u064A \u0633\u064F\u0645\u064A\u062A \u0628\u0627\u0633\u0645 \u0627\u0645\u0631\u0623\u0629 \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0645\u0631\u064A\u0645", explanation: "\u0633\u0648\u0631\u0629 \u0645\u0631\u064A\u0645 \u0633\u064F\u0645\u064A\u062A \u0628\u0627\u0633\u0645 \u0645\u0631\u064A\u0645 \u0627\u0644\u0639\u0630\u0631\u0627\u0621 \u0627\u0628\u0646\u0629 \u0639\u0645\u0631\u0627\u0646 \u0639\u0644\u064A\u0647\u0627 \u0627\u0644\u0633\u0644\u0627\u0645.", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0633\u0648\u0631\u0629 \u0627\u0641\u062A\u062A\u062D\u062A \u0628\u0644\u0641\u0638 \xAB\u0633\u0648\u0631\u0629 \u0623\u0646\u0632\u0644\u0646\u0627\u0647\u0627 \u0648\u0641\u0631\u0636\u0646\u0627\u0647\u0627\xBB\u060C \u0641\u0645\u0627 \u0647\u064A\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0648\u0631", explanation: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0648\u0631 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u0648\u062D\u064A\u062F\u0629 \u0627\u0644\u062A\u064A \u062A\u0628\u062F\u0623 \u0628\u0647\u0630\u0647 \u0627\u0644\u0622\u064A\u0629 \u0627\u0644\u0643\u0631\u064A\u0645\u0629.", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u0633\u062C\u062F\u0627\u062A \u0627\u0644\u0645\u062A\u0641\u0642 \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u062A\u0644\u0627\u0648\u0629 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "14 \u0623\u0648 15 \u0633\u062C\u062F\u0629", explanation: "\u0623\u0634\u0647\u0631 \u0627\u0644\u0623\u0642\u0648\u0627\u0644 14 \u0633\u062C\u062F\u0629 \u0623\u0648 15 \u0628\u0633\u062C\u062F\u0629 \u0633\u0648\u0631\u0629 \u0627\u0644\u062D\u062C \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0648\u0633\u0648\u0631\u0629 \u0635.", source: "\u0643\u062A\u0628 \u0627\u0644\u0641\u0642\u0647 \u0627\u0644\u0645\u0642\u0627\u0631\u0646" },
        { points: 300, difficulty: "\u0635\u0639\u0628", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u0645\u0649 \xAB\u0633\u0648\u0631\u0629 \u0628\u0646\u064A \u0625\u0633\u0631\u0627\u0626\u064A\u0644\xBB\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0633\u0631\u0627\u0621", explanation: "\u0633\u064F\u0645\u064A\u062A \u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u0633\u0631\u0627\u0621 \u0628\u0633\u0648\u0631\u0629 \u0628\u0646\u064A \u0625\u0633\u0631\u0627\u0626\u064A\u0644 \u0644\u0630\u0643\u0631 \u0642\u0635\u062A\u0647\u0645 \u0641\u064A \u0645\u0637\u0644\u0639\u0647\u0627.", source: "\u062A\u0641\u0633\u064A\u0631 \u0627\u0644\u0637\u0628\u0631\u064A" },
        // 400
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u0630\u0643\u0631\u062A \u0641\u064A\u0647\u0627 \u0627\u0644\u0628\u0633\u0645\u0644\u0629 \u0645\u0631\u062A\u064A\u0646\u060C \u0648\u0641\u064A \u0623\u064A \u0622\u064A\u0629 \u062C\u0627\u0621\u062A \u0627\u0644\u0628\u0633\u0645\u0644\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0645\u0644 - \u0627\u0644\u0622\u064A\u0629 30", explanation: "\u062C\u0627\u0621\u062A \u0641\u064A \u0643\u062A\u0627\u0628 \u0633\u0644\u064A\u0645\u0627\u0646 \u0639\u0644\u064A\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u0645\u0644\u0643\u0629 \u0633\u0628\u0623: (\u0625\u0646\u0647 \u0645\u0646 \u0633\u0644\u064A\u0645\u0627\u0646 \u0648\u0625\u0646\u0647 \u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062D\u0645\u0646 \u0627\u0644\u0631\u062D\u064A\u0645).", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u0631\u0641 \u0627\u0644\u0623\u0643\u062B\u0631 \u062A\u0643\u0631\u0627\u0631\u0627\u064B \u0641\u064A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "\u062D\u0631\u0641 \u0627\u0644\u0623\u0644\u0641", explanation: "\u062D\u0631\u0641 \u0627\u0644\u0623\u0644\u0641 \u0647\u0648 \u0623\u0643\u062B\u0631 \u0627\u0644\u062D\u0631\u0648\u0641 \u0648\u0631\u0648\u062F\u0627\u064B \u0641\u064A \u0646\u0635\u0648\u0635 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u064A\u0644\u064A\u0647 \u0627\u0644\u0644\u0627\u0645.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0644\u0644\u0625\u062A\u0642\u0627\u0646" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0646 \u0647\u0648 \u0627\u0644\u0635\u062D\u0627\u0628\u064A \u0627\u0644\u0648\u062D\u064A\u062F \u0627\u0644\u0630\u064A \u0630\u064F\u0643\u0631 \u0627\u0633\u0645\u0647 \u0635\u0631\u064A\u062D\u0627\u064B \u0641\u064A \u0622\u064A\u0627\u062A \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645\u061F", correctAnswer: "\u0632\u064A\u062F \u0628\u0646 \u062D\u0627\u0631\u062B\u0629 \u0631\u0636\u064A \u0627\u0644\u0644\u0647 \u0639\u0646\u0647", explanation: "\u0630\u064F\u0643\u0631 \u0641\u064A \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062D\u0632\u0627\u0628 \u0622\u064A\u0629 37: (\u0641\u0644\u0645\u0627 \u0642\u0636\u0649 \u0632\u064A\u062F \u0645\u0646\u0647\u0627 \u0648\u0637\u0631\u0627 \u0632\u0648\u062C\u0646\u0627\u0643\u0647\u0627).", source: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062D\u0632\u0627\u0628" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0646\u062A\u0647\u064A \u062C\u0645\u064A\u0639 \u0622\u064A\u0627\u062A\u0647\u0627 \u0628\u062D\u0631\u0641 \u0627\u0644\u0633\u064A\u0646\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0627\u0633", explanation: "\u0641\u0648\u0627\u0635\u0644 \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0627\u0633 \u0643\u0644\u0647\u0627 \u062A\u0646\u062A\u0647\u064A \u0628\u062D\u0631\u0641 \u0627\u0644\u0633\u064A\u0646 (\u0627\u0644\u0646\u0627\u0633\u060C \u0627\u0644\u062E\u0646\u0627\u0633\u060C \u0627\u0644\u0648\u0633\u0648\u0627\u0633).", source: "\u0627\u0644\u0645\u0635\u062D\u0641 \u0627\u0644\u0634\u0631\u064A\u0641" },
        { points: 400, difficulty: "\u0635\u0639\u0628 \u062C\u062F\u0627\u064B", questionText: "\u0645\u0627 \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u062E\u062A\u062A\u0645 \u0628\u0622\u064A\u0629 \u062A\u0630\u0643\u0631 \u0627\u0633\u0645 \u0646\u0628\u064A\u064A\u0646 \u0643\u0631\u064A\u0645\u064A\u0646\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0639\u0644\u0649 (\u0635\u062D\u0641 \u0625\u0628\u0631\u0627\u0647\u064A\u0645 \u0648\u0645\u0648\u0633\u0649)", explanation: "\u062A\u062E\u062A\u062A\u0645 \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0639\u0644\u0649 \u0628\u0642\u0648\u0644\u0647 \u062A\u0639\u0627\u0644\u0649: (\u0635\u062D\u0641 \u0625\u0628\u0631\u0627\u0647\u064A\u0645 \u0648\u0645\u0648\u0633\u0649).", source: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0639\u0644\u0649" },
        // 500
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u0630\u064F\u0643\u0631\u062A \u0641\u064A \u0643\u0644 \u0622\u064A\u0629 \u0645\u0646 \u0622\u064A\u0627\u062A\u0647\u0627 \u0644\u0641\u0638 \u0627\u0644\u062C\u0644\u0627\u0644\u0629 \xAB\u0627\u0644\u0644\u0647\xBB\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u062C\u0627\u062F\u0644\u0629", explanation: "\u062A\u062A\u0643\u0648\u0646 \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u062C\u0627\u062F\u0644\u0629 \u0645\u0646 22 \u0622\u064A\u0629 \u0648\u0631\u062F \u0627\u0633\u0645 \u0627\u0644\u062C\u0644\u0627\u0644\u0629 \u0641\u064A \u0643\u0644 \u0622\u064A\u0629 \u0645\u0646\u0647\u0627 \u0628\u0644\u0627 \u0627\u0633\u062A\u062B\u0646\u0627\u0621.", source: "\u0627\u0644\u0625\u062A\u0642\u0627\u0646 \u0641\u064A \u0639\u0644\u0648\u0645 \u0627\u0644\u0642\u0631\u0622\u0646" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0645\u062B\u0644 \u0646\u0635\u0641 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0631\u0633\u0645\u0627\u064B \u0628\u062D\u0633\u0628 \u0639\u062F\u0651 \u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0642\u0631\u0622\u0646\u064A\u061F", correctAnswer: "\u0648\u0644\u064A\u062A\u0644\u0637\u0641", explanation: "\u0643\u0644\u0645\u0629 \xAB\u0648\u0644\u064A\u062A\u0644\u0637\u0641\xBB \u0641\u064A \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641 \u0627\u0644\u0622\u064A\u0629 19 \u062A\u0642\u0639 \u0641\u064A \u0645\u0646\u062A\u0635\u0641 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 \u0641\u064A \u0645\u0639\u0638\u0645 \u0627\u0644\u0645\u0635\u0627\u062D\u0641.", source: "\u062A\u0627\u0631\u064A\u062E \u0631\u0633\u0645 \u0627\u0644\u0645\u0635\u062D\u0641" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0647\u064A \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u064A\u0637\u0644\u0642 \u0639\u0644\u064A\u0647\u0627 \u0627\u0633\u0645 \xAB\u0633\u0648\u0631\u0629 \u0627\u0644\u0642\u062A\u0627\u0644\xBB\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0645\u062D\u0645\u062F", explanation: "\u0633\u0648\u0631\u0629 \u0645\u062D\u0645\u062F \u062A\u0633\u0645\u0649 \u0628\u0633\u0648\u0631\u0629 \u0627\u0644\u0642\u062A\u0627\u0644 \u0644\u0627\u0634\u062A\u0645\u0627\u0644\u0647\u0627 \u0639\u0644\u0649 \u0623\u062D\u0643\u0627\u0645 \u0627\u0644\u062D\u0631\u0628 \u0648\u0627\u0644\u0642\u062A\u0627\u0644.", source: "\u062A\u0641\u0633\u064A\u0631 \u0627\u0644\u0642\u0631\u0637\u0628\u064A" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0643\u0645 \u0639\u062F\u062F \u0627\u0644\u0633\u0648\u0631 \u0627\u0644\u0645\u0643\u064A\u0629 \u0645\u0646 \u0625\u062C\u0645\u0627\u0644\u064A \u0633\u0648\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064A\u0645 (114 \u0633\u0648\u0631\u0629) \u0639\u0644\u0649 \u0627\u0644\u0631\u0627\u062C\u062D\u061F", correctAnswer: "86 \u0633\u0648\u0631\u0629", explanation: "\u0627\u0644\u0633\u0648\u0631 \u0627\u0644\u0645\u0643\u064A\u0629 \u0639\u062F\u062F\u0647\u0627 86 \u0633\u0648\u0631\u0629 \u0648\u0627\u0644\u0633\u0648\u0631 \u0627\u0644\u0645\u062F\u0646\u064A\u0629 28 \u0633\u0648\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0631\u0623\u064A \u0627\u0644\u0623\u0631\u062C\u062D.", source: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0642\u0631\u0622\u0646" },
        { points: 500, difficulty: "\u062E\u0628\u064A\u0631", questionText: "\u0645\u0627 \u0627\u0633\u0645 \u0627\u0644\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u0645\u0649 \xAB\u0627\u0644\u0641\u0627\u0636\u062D\u0629\xBB \u0644\u0623\u0646\u0647\u0627 \u0643\u0634\u0641\u062A \u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064A\u0646\u061F", correctAnswer: "\u0633\u0648\u0631\u0629 \u0627\u0644\u062A\u0648\u0628\u0629", explanation: "\u0633\u0645\u0627\u0647\u0627 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0628\u0627\u0644\u0641\u0627\u0636\u062D\u0629 \u0644\u0623\u0646\u0647\u0627 \u0641\u0636\u062D\u062A \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064A\u0646 \u0648\u0623\u0641\u0639\u0627\u0644\u0647\u0645.", source: "\u0635\u062D\u064A\u062D \u0627\u0644\u0628\u062E\u0627\u0631\u064A" }
