        // 500 خبير (3)
        {
          points: 500,
          difficulty: "\u062E\u0628\u064A\u0631",
          questionText: "\u0645\u0627 \u0627\u0633\u0645 \u0627\u0644\u062A\u062D\u0648\u0644 \u0627\u0644\u0623\u0639\u0644\u0649 \u0648\u0627\u0644\u0633\u0631\u0651\u064A \u0627\u0644\u0630\u064A \u064A\u0645\u0644\u0643\u0647 \u0623\u0648\u0644\u0643\u064A\u0648\u0631\u0627 \u0633\u064A\u0641\u064A\u0631 \u0641\u0642\u0637 \u0645\u0646 \u0628\u064A\u0646 \u062C\u0645\u064A\u0639 \u0627\u0644\u0625\u0633\u0628\u0627\u062F\u0627 \u0648\u0627\u0644\u0630\u064A \u0644\u0645 \u064A\u0639\u0644\u0645 \u0628\u0647 \u062D\u062A\u0649 \u0633\u0648\u0633\u0643\u064A \u0622\u064A\u0632\u0646\u061F",
          correctAnswer: "\u0627\u0644\u0631\u064A\u0633\u0648\u0631\u064A\u0643\u0633\u064A\u0648\u0646: \u0633\u064A\u063A\u0648\u0646\u062F\u0627 \u0625\u064A\u062A\u0627\u0628\u0627 (Segunda Etapa / \u0627\u0644\u0645\u0631\u062D\u0644\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629)",
          explanation: "\u0623\u0643\u062F \u0623\u0648\u0644\u0643\u064A\u0648\u0631\u0627 \u0623\u0646\u0647 \u0627\u0644\u0625\u0633\u0628\u0627\u062F\u0627 \u0627\u0644\u0648\u062D\u064A\u062F \u0627\u0644\u0642\u0627\u062F\u0631 \u0639\u0644\u0649 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u062A\u062D\u0648\u0644 \u062B\u0627\u0646\u064D \u0628\u0639\u062F \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0645\u0648\u0631\u0633\u064A\u064A\u0644\u0627\u063A\u0648.",
          source: "\u0628\u0644\u064A\u062A\u0634 - \u0647\u0648\u064A\u0643\u0648 \u0645\u0648\u0646\u062F\u0648"
        },
        {
          points: 500,
          difficulty: "\u062E\u0628\u064A\u0631",
          questionText: "\u0645\u0627 \u0627\u0633\u0645 \u0627\u0644\u0645\u0642\u0627\u062A\u0644\u0629 \u0627\u0644\u062D\u0627\u0631\u0633\u0629 \u0641\u064A \u0627\u0644\u0641\u0631\u0642\u0629 \u0635\u0641\u0631 \u0627\u0644\u062A\u064A \u062A\u062D\u064A\u0643 \u062E\u064A\u0648\u0637 \u0627\u0644\u0632\u0645\u0646 \u0648\u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u0645\u0644\u0643\u064A\u0629 \u0648\u0643\u0634\u0641\u062A \u0639\u0646 \u0628\u0627\u0646\u0643\u0627\u064A \u064A\u063A\u0645\u0631 \u0627\u0644\u0639\u0648\u0627\u0644\u0645 \u0627\u0644\u062B\u0644\u0627\u062B\u0629 \u0628\u0640 \xAB\u0634\u0627\u0645\u0627\u062A\u0633\u0648 \u0646\u0648 \u0645\u064A\u064A\u0627\u0643\u0648\xBB\u061F",
          correctAnswer: "\u0633\u064A\u0646\u062C\u0648\u0645\u0627\u0631\u0648 \u0634\u0648\u062A\u0627\u0631\u0627 (Senjumaru Shutara)",
          explanation: "\u0627\u0633\u062A\u0639\u0631\u0636 \u0627\u0644\u0623\u0646\u0645\u064A \u0627\u0644\u0631\u0633\u0645\u064A \u0641\u064A \u062D\u0631\u0628 \u0627\u0644\u0623\u0644\u0641 \u0639\u0627\u0645 \u0627\u0644\u062F\u0645\u0648\u064A\u0629 \u0628\u0627\u0646\u0643\u0627\u064A \u0634\u0648\u062A\u0627\u0631\u0627 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629 \u0628\u0639\u062F \u0627\u0646\u062A\u062D\u0627\u0631 \u0628\u0642\u064A\u0629 \u0623\u0639\u0636\u0627\u0621 \u0627\u0644\u0641\u0631\u0642\u0629 \u0635\u0641\u0631 \u0644\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u062E\u062A\u0645.",
          source: "\u0628\u0644\u064A\u062A\u0634 - \u0627\u0644\u0623\u0646\u0645\u064A 2023"
        },
        {
          points: 500,
          difficulty: "\u062E\u0628\u064A\u0631",
          questionText: "\u0645\u0627 \u0627\u0633\u0645 \u0627\u0644\u0633\u0647\u0645 \u0627\u0644\u0645\u0635\u0646\u0648\u0639 \u0645\u0646 \u0631\u0648\u0627\u0633\u0628 \u0627\u0644\u0641\u0636\u0629 \u0627\u0644\u0633\u0627\u0643\u0646\u0629 \u0627\u0644\u0645\u062A\u0643\u0648\u0646\u0629 \u0641\u064A \u0642\u0644\u0648\u0628 \u0627\u0644\u0643\u0648\u064A\u0646\u0634\u064A \u0627\u0644\u0645\u0635\u0627\u0628\u064A\u0646 \u0628\u0623\u0648\u0633\u0648\u0627\u0644\u0646\u060C \u0648\u0627\u0644\u0630\u064A \u0623\u0648\u0642\u0641\u062A \u0628\u0647 \u0646\u0628\u0648\u0621\u0629 \u064A\u0648\u0647\u0627\u0628\u0627\u062E \u0644\u0644\u0623\u0628\u062F \u0641\u064A \u0627\u0644\u0645\u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0623\u062E\u064A\u0631\u0629\u061F",
          correctAnswer: "\u0627\u0644\u0633\u0647\u0645 \u0627\u0644\u0641\u0636\u064A \u0627\u0644\u0633\u0627\u0643\u0646 (Still Silver Arrow)",
          explanation: "\u0635\u0646\u0639\u0647 \u0631\u064A\u0648\u0643\u064A\u0646 \u0625\u064A\u0634\u064A\u062F\u0627 \u0645\u0646 \u0642\u0644\u0628 \u0632\u0648\u062C\u062A\u0647 \u0643\u0627\u0646\u0627\u064A \u0643\u0627\u062A\u0627\u063A\u064A\u0631\u064A \u0648\u0623\u0637\u0644\u0642\u0647 \u0627\u0628\u0646\u0647 \u0623\u0648\u0631\u064A\u0648 \u0644\u062A\u062C\u0645\u064A\u062F \u0642\u062F\u0631\u0627\u062A \u064A\u0648\u0647\u0627\u0628\u0627\u062E \u0644\u0644\u062D\u0638\u0629 \u062D\u0627\u0633\u0645\u0629 \u0636\u0631\u0628 \u0641\u064A\u0647\u0627 \u0625\u064A\u062A\u0634\u064A\u063A\u0648.",
          source: "\u0645\u0627\u0646\u063A\u0627 \u0628\u0644\u064A\u062A\u0634 - \u0627\u0644\u0646\u0647\u0627\u064A\u0629"
        }
