          const room = raw;
          if (room.status !== "playing" && room.status !== "in_game") {
            throw new ApiError(400, "room/not-playing", "\u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629 \u0644\u064A\u0633\u062A \u0641\u064A \u062D\u0627\u0644\u0629 \u0644\u0639\u0628 \u062D\u0627\u0644\u064A\u0627\u064B.");
          }
