          const nextUsedTileKeys = [...room.usedTileKeys || [], aq.tileKey];
          const nextRoundUsedQuestionIds = (room.roundUsedQuestionIds || []).includes(aq.questionId) ? room.roundUsedQuestionIds : [...room.roundUsedQuestionIds || [], aq.questionId];
          const nextTurnRole = actorRole === "host" ? "guest" : "host";
          const nextTeamIndex = nextTurnRole === "host" ? 0 : 1;
          const nextTurnNumber = (room.turnNumber || 1) + 1;
          const nextTurnName = getRoleDisplayName(room, nextTurnRole);
