            teams: nextTeams,
            usedTileKeys: nextUsedTileKeys,
            roundUsedQuestionIds: nextRoundUsedQuestionIds,
            activeQuestion: null,
            activeTurnRole: nextTurnRole,
            activeTeamIndex: nextTeamIndex,
            turnNumber: nextTurnNumber,
